\chapter{Anderson's theorem}

This section contains a proof of Anderson's theorem.
See \url{https://en.wikipedia.org/wiki/Anderson's_theorem} for more details.

\begin{theorem}
  \label{thm:brunn_minkowski_onedim}
  \lean{brunn_minkowski_1d}
  If $A, B, A + B \subseteq \mathbb{R}$ are nonempty and Lebesgue measurable where
  $A + B = {x + y | x \in A, y \in B}$, then $\mu(A) + \mu(B) \leq \mu(A+B)$.
\end{theorem}
\begin{proof}
  Let $A_k = A \cap [-k, k]$ for $k \in \mathbb{N}$.
  Since $\mu(A+B) = \lim_{k \to \infty} \mu(A_k+B_k)$ and $\mu(A) = \lim_{k \to \infty} \mu(A_k)$, $\mu(B) = \lim_{k \to \infty} \mu(B_k)$, it suffices to show that for each $k$ such that both $A_k$ and $B_k$ are nonempty, $\mu(A_k) + \mu(B_k) \leq \mu(A_k+B_k)$.
  For any $\epsilon > 0$, there are shifts $A_{k, \epsilon}, B_{k, \epsilon}$ of $A_k, B_k$, such that $0 \in A_{k, \epsilon} \cap B_{k, \epsilon}$ and
  $\mu(A_{k, \epsilon} \cap B_{k, \epsilon}) < \epsilon$.
  Then $A_k \cup B_k \subseteq A_k + B_k$ and $\mu(A_k \cup B_k) \leq \mu(A_k) + \mu(B_k) - \epsilon$. By taking $\epsilon \to 0$ we get $\mu(A_k) + \mu(B_k) \leq \mu(A_k+B_k)$.
\end{proof}

\begin{theorem}
  \label{thm:prekopa_leindler_for_anderson}
  \lean{prekopa_leindler_for_anderson}
  \uses{thm:brunn_minkowski_onedim}
  Fix $\lambda \in (0,1)$. Let $f, g, h: \mathbb{R}^n \to \mathbb{R}_{+}$ be non-negative, measurable functions satisfying $h(\lambda x+(1-\lambda)y) \geq f(x)^{\lambda}g(y)^{1-\lambda}$ for all $x,y\in \mathbb{R}^n$. Then $\int_{\mathbb{R}^n}h(x)dx \geq (\int_{\mathbb{R}^n}f(x)dx)^{\lambda}(\int_{\mathbb{R}^n}g(x)dx)^{1-\lambda}$.
\end{theorem}
\begin{proof}
  We first show the $n=1$ case.
  Let $L_h(t) = \{x : h(x) \geq t\}$. Then by assumption,
  $L_h(t) \supseteq \lambda L_f(t) + (1-\lambda)L_g(t)$.
  By Theorem~\ref{thm:brunn_minkowski_onedim},
  \begin{displaymath}
    \mu(L_h(t)) \geq \mu(\lambda L_h(t) + (1 - \lambda)L_g(t))
    \geq \lambda\mu(L_f(t)) + (1-\lambda)\mu(L_g(t)).
  \end{displaymath}
  Since $f(x)$ is non-negative, by Fubini theorem,
  $\int_{\mathbb{R}} h(x)dx = \int_{t \geq 0} \mu(L_h(t)) dt$. Then, we have that
  \begin{displaymath}
    \int_{\mathbb{R}} h(x)dx = \int_{t \geq 0} \mu(L_h(t)) dt
    \geq \lambda \int_{t \geq 0} \mu(L_f(t)) dt + (1-\lambda) \int_{t \geq 0} \mu(L_g(t)) dt
    = \lambda \int_{\mathbb{R}} f(x)dx + (1-\lambda) \int_{\mathbb{R}} g(x)dx
    \geq (\int_{\mathbb{R}} f(x)dx)^\lambda(\int_{\mathbb{R}} g(x)dx)^(1-\lambda)
  \end{displaymath}
  where the last step uses concavity of $\log(\cdot)$.

  Now we prove the $n>1$ case using induction. For $x, y \in \mathbb{R}^{n-1}$, $\alpha, \beta \in \mathbb{R}$, we set $\gamma = \lambda\alpha + (1-\lambda)\beta$. For any $c$, we define $h_c(x)=h(x,c)$ for $x \in \mathbb{R}^{n-1}$, i.e., setting the last coordinate to be $c$. Then
  \begin{displaymath}
    h_\gamma(\lambda x + (1-\lambda) y) = h(\lambda(x,\alpha)+(1-\lambda)(y,\beta))
    \geq f(x,\alpha)^{\lambda} g(y,\beta)^{1-\lambda}
    \geq f_\alpha(x)^\lambda g_\beta(y)^{1-\lambda}.
  \end{displaymath}
  By the inductive case applied to $h_\gamma, f_\alpha, g_\beta$, we obtain
  $\int_{\mathbb{R}^{n-1}}h_\gamma(z)dz \geq (\int_{\mathbb{R}^{n-1}}f_\alpha(z)dz)^{\lambda}(\int_{\mathbb{R}^{n-1}}g_\beta(z)dz)^{1-\lambda}$.
  We define $H(\gamma) = \int_{\mathbb{R}^{n-1}}h_\gamma(z)dz$ and $F(\alpha)$, $G(\beta)$ similarly. Then
  $H(\lambda\alpha+(1-\lambda)\beta) \geq F(\alpha)^\lambda G(\beta)^{1-\lambda}$.
  So $H,F,G$ satisfy the hypothesis for $n=1$. So
  $\int_{\mathbb{R}} H(\gamma)d\gamma
    \geq (\int_{\mathbb{R}} F(\alpha)d\alpha)^\lambda(\int_{\mathbb{R}} G(\beta)d\beta)^(1-\lambda)$.
  So the conclusion follows by Fubini's theorem.
\end{proof}

\begin{theorem}
  \label{thm:brunn_minkowski_mul}
  \lean{brunn_minkowski_mul}
  \uses{thm:prekopa_leindler_for_anderson}
  If $A,B, A+B$ are nonempty Lebesgue measurable subsets of $\mathbb{R}^n$ and $\lambda \in [0, 1]$, then $\mu(\lambda A + (1-\lambda) B) \geq \mu(A)^\lambda \mu(B)^{1-\lambda}$.
\end{theorem}
\begin{proof}
  Apply Theorem~\ref{thm:prekopa_leindler_for_anderson} by taking $h = 1_{\lambda A + (1-\lambda) B}$, $f = 1_{A}$, $g = 1_{B}$.
\end{proof}

\begin{theorem}
  \label{thm:brunn_minkowski}
  \lean{brunn_minkowski}
  \uses{thm:brunn_minkowski_mul}
  If $A,B, A+B$ are nonempty Lebesgue measurable subsets of $\mathbb{R}^n$, then $\mu(A + B)^{1/n} \geq \mu(A)^{1/n} + \mu(B)^{1/n}$.
\end{theorem}
\begin{proof}
  Let $\lambda = \frac{\mu(A)^{1/n}}{\mu(A)^{1/n}+\mu(B)^{1/n}}$. Then by
  Theorem~\ref{thm:brunn_minkowski_mul}
  \begin{displaymath}
    \mu(A+B) = \mu(\lambda \frac{A}{\lambda} + (1-\lambda) \frac{B}{1-\lambda})
    \geq (\frac{\mu(A)}{\lambda^n})^{\lambda} (\frac{\mu(B)}{(1-\lambda)^n})^{1-\lambda}.
  \end{displaymath}
  Substitute $\lambda$ back and we get $\mu(A+B) \geq (\mu(A)^{1/n}+\mu(B)^{1/n})^n$.
\end{proof}

\begin{theorem}
  \label{thm:anderson}
  \lean{anderson}
  \uses{thm:brunn_minkowski}
  Let $E \subseteq \mathbb{R}^n$ be convex, symmetric about the origin.
  Let $f$ be a nonnegative function on $\mathbb{R}^n$ such that
  \begin{enumerate}
    \item $f(x)=f(-x)$ for all $x$.
    \item $\{x | f(x) \geq u\} = K_u$ is convex for every $u$ ($0 < u < \infty$), and
    \item $\int_{\mathbb{R}^n} f(x)dx<\infty$.
  \end{enumerate}
  Then
  \begin{displaymath}
    \int_E f(x+ky)dx \geq \int_E f(x+y)dx
  \end{displaymath}
  for $0 \leq k \leq 1$.
\end{theorem}
\begin{proof}
  We need to show that
  \begin{displaymath}
    \int_{E+ky} f(x)dx \geq \int_{E+y} f(x)dx
  \end{displaymath}
  where $E+y$ is the set $E$ translated by the vector $y$.
  For this, it suffices to show that
  \begin{displaymath}
    \mu((E+ky)\cap K_u) \geq \mu((E+y)\cap K_u)
  \end{displaymath}
  for every $u$.
  Let $\alpha = (1+k)/2$. Then
  $(E+ky)\cap K_u \supseteq \alpha((E+y)\cap K_u) + (1-\alpha) ((E-y)\cap K_u)$
  because $K_u$ is convex and
  $E+ky \supseteq \alpha(E+y)+(1-\alpha)(E-y) = (\alpha E + (1-\alpha)E)+ky$.
  Thus,
  \begin{displaymath}
    \mu((E+ky)\cap K_u) \geq \mu(\alpha((E+y)\cap K_u) + (1-\alpha) ((E-y)\cap K_u)).
  \end{displaymath}
  By Theorem~\ref{thm:brunn_minkowski},
  \begin{displaymath}
    \mu(\alpha((E+y)\cap K_u) + (1-\alpha) ((E-y)\cap K_u))
    \geq (\alpha \mu((E+y)\cap K_u)^{1/n} + (1-\alpha) \mu((E-y)\cap K_u)^{1/n})^n
    = \mu((E+y)\cap K_u)
  \end{displaymath}
  where the last equality is because $(E+y)\cap K_u$ is the mirror image through the origin of $(E-y)\cap K_u$, and therefore these two sets have the same volume.
\end{proof}

