\chapter{Banach–Mazur theorem}

This section contains a proof of the Banach–Mazur theorem.
See \url{https://en.wikipedia.org/wiki/Banach%E2%80%93Mazur_theorem} for more details.

\begin{lemma}
  \label{lem:compact-hausdorff-coincide}
  \lean{compact_hausdorff_coincide}
  If $K$ is a compact set for some topology $\tau$, and $\tau'$ is any Hausdorff topology on $K$ which is weaker than $\tau$, then $\tau$ and $\tau'$ coincide.
\end{lemma}
\begin{proof}
  Suppose $A$ is a $\tau$-closed subset of $K$. Then $A$ is $\tau$-compact and so its continuous
  image in $(K, \tau')$ under the identity mapping $id_K : (K, \tau) \tau (K, \tau')$ is also
  compact, i.e., $A$ is $\tau'$-compact. Since $\tau'$ is Hausdorff, $A$ is $\tau'$-closed.
\end{proof}

\begin{lemma}
  \label{lem:separable-implies-compact-metrizable-weak-star}
  \lean{separable_implies_compact_metrizable_weak_star}
  \uses{lem:compact-hausdorff-coincide}
  If $X$ is a separable Banach space then the closed ball of $X^*$, $B_{X^*}$, is compact and metrizable for the weak$^*$ topology.
\end{lemma}
\begin{proof}
  Take $(x_n)_{n=1}^{\infty}$ dense in the unit ball $B_X$ of $X$. We define the topology $\rho$
  induced on $X^*$ by convergence on each $x_n$. Precisely, a base of neighborhoods for $\rho$ at
  a point $x_0^* \in X^*$ is given by sets of the form
  \begin{displaymath}
    V_\eps (x_0^*: x_1, \dots, x_N) = \{ x^* \in X^* : |x^*(x_n) - x_0^*(x_n)| < \eps, n = 1, \dots, N\},
  \end{displaymath}
  where $\eps > 0$ and $N \in \mathbb{N}$. This topology is metrizable, and a metric inducing $\rho$
  may be defined by
  \begin{displaymath}
    d (x^*, y^*) = \sum_{n=1}^{\infty} 2^{-n} min (1, |x^*(x_n) - y^*(x_n)|), x^*, y^* \in X^*.
  \end{displaymath}
  $\rho$ is Hausdorff and weaker than the weak$^*$ topology, so it coincides with the weak$^*$
  topology on the weak$^*$ compact set $B_{X^*}$.
\end{proof}

\begin{lemma}
  \label{lem:separable-banach-implies-embeds-cont}
  \lean{separable_banach_implies_embeds_cont}
  \uses{lem:separable-implies-compact-metrizable-weak-star}
  If $X$ is a separable Banach space, then there exists a compact, Hausdorff, metrizable space $K$ such that $X$ embeds isometrically into $C(K)$.
\end{lemma}
\begin{proof}
  Take $K = B_{X^*}$ with the relative weak$^*$ topology. By Lemma~\ref{lem:separable-implies-compact-metrizable-weak-star}, $B_{X^*}$ is compact and metrizable. The
  isometric embedding of $X$ into $C(B_{X^*})$ is the embedding $x \mapsto f_x$ where
  $f_x(x^*) = x^*(x)$ for all $x^* \in B_{X^*}$.
\end{proof}

\begin{lemma}
  \label{lem:compact-metrizable-implies-embeds}
  \lean{compact_metrizable_implies_embeds}
  If $K$ is a compact metrizable space, then $K$ embeds homeomorphically into $[0, 1]^{\mathbb{N}}$.
\end{lemma}
\begin{proof}
  Being compact and metrizable, $K$ contains a countable dense set, $(s_n)_{n=1}^{\infty}$. Let
  $\rho$ be a metric on $K$ inducing its topology. Without loss of generality we can assume that
  $0 \leq \rho \leq 1$. Now we define $\theta : K \to [0, 1]^{\mathbb{N}}$ by
  $\theta(x) = (\rho(x, s_n))_{n=1}^{\infty}$.

  $\theta$ is continuous since the mapping $x \mapsto \rho(x, s_n)$ is continuous for each $n$.
  $\theta$ is injective because if $x$ and $y$ are two different points in $K$ then there exists
  some $s_n$ such that $\rho(x, s_n) < \rho(y, s_n)$ (or the other way around and, therefore,
  $\theta(x)$ and $\theta(y)$ will differ in the $n$th-coordinate.

  Since $K$ is compact and $[0, 1]^{\mathbb{N}}$ is Hausdorff, it follows that $\theta$ maps $K$
  homeomorphically into its image.
\end{proof}

\begin{lemma}
  \label{lem:closed-subset-interval-implies-cont-embeds}
  \lean{closed_subset_interval_implies_cont_embeds}
  If $E$ is a closed subset of $[0, 1]$, then $C(E)$ embeds isometrically into $C[0, 1]$.
\end{lemma}
\begin{proof}
  We define $A : C(E) \to C[0, 1]$ which satisfies $Af|_E = f$ for all $f \in C(E)$. Notice that
  $[0, 1] \setminus E$ is a countable disjoint union of relatively open intervals. Thus, we define
  $Af$ to be an extension of $f$ which is affine on each such interval interior to $[0, 1]$ and is
  constant on any such interval containing an endpoint of $[0, 1]$.
\end{proof}

\begin{lemma}
  \label{lem:compact-metrizable-implies-cont-embeds}
  \lean{compact_metrizable_implies_cont_embeds}
  \uses{lem:compact-metrizable-implies-embeds}
  \uses{lem:closed-subset-interval-implies-cont-embeds}
  If $K$ is a compact metrizable space, then $C(K)$ embeds isometrically into $C[0, 1]$.
\end{lemma}
\begin{proof}
  Let $\Delta$ be the Cantor set. Let $\psi : \Delta \tau [0, 1]^{\mathbb{N}}$ be a continuous
  injection. By Lemma~\ref{lem:compact-metrizable-implies-embeds}, we may assume $K$ is a closed
  subset of $[0, 1]^{\mathbb{N}}$. Let $E = \psi^{-1}(K)$. Then $E$ is a closed subset of $[0, 1]$.
  By lemma~\ref{lem:closed-subset-interval-implies-cont-embeds}, $C(E)$ embeds isometrically into
  $C[0, 1]$. $C(K)$ embeds isometrically into $C(E)$ by $f \mapsto f \circ \psi$. Therefore, $C(K)$
  embeds isometrically into $C[0, 1]$.
\end{proof}

\begin{theorem}[Banach-Mazur Theorem]
  \label{thm:banach-mazur}
  \lean{banach_mazur}
  \uses{lem:separable-banach-implies-embeds-cont}
  \uses{lem:compact-metrizable-implies-cont-embeds}
  If $X$ is a separable Banach space, then $X$ embeds isometrically into $C[0, 1]$.
\end{theorem}
\begin{proof}
  By Lemma~\ref{lem:separable-banach-implies-embeds-cont}, there exists a compact, Hausdorff,
  metrizable space $K$ such that $X$ embeds isometrically into $C(K)$. For such $K$, by
  Lemma~\ref{compact-metrizable-implies-cont-embeds}, $C(K)$ embeds isometrically into $C[0, 1]$.
  Therefore, $X$ embeds isometrically into $C[0, 1]$.
\end{proof}

\chapter{Bauer–Fike Theorem}

This section contains a proof of the Bauer–Fike Theorem.
See \url{https://en.wikipedia.org/wiki/Bauer%E2%80%93Fike_theorem} for more details.

\begin{definition}[Subordinate Matrix Norm Properties]
    \label{def:Subordinate_Matrix_Norm}
    \lean{IsSubordinateMatrixNorm}
    A matrix norm $\|\cdot\|_p$ on the space of $n \times n$ complex matrices is a norm that is consistent with a vector p-norm, defined as $\|M\|_p = \sup_{x \neq 0} \frac{\|Mx\|_p}{\|x\|_p}$. For the purposes of this theorem, we require that the norm satisfies the following properties, in addition to being nonnegative and taking the value 1 on the identity matrix:

    \begin{itemize}
        \item \textbf{Eigenvalue Bound:} For any matrix $M \in \mathbb{C}^{n \times n}$, if $\gamma$ is an eigenvalue of $M$, then $|\gamma| \le \|M\|_p$.
        \item \textbf{Sub-multiplicative Property:} For any two matrices $M_1, M_2 \in \mathbb{C}^{n \times n}$, the norm satisfies $\|M_1 M_2\|_p \le \|M_1\|_p \|M_2\|_p$.
        \item \textbf{Diagonal Matrix Norm:} For any diagonal matrix $D \in \mathbb{C}^{n \times n}$ with diagonal entries $d_1, d_2, \dots, d_n$, the norm satisfies $\|D\|_p = \max_{i=1,\dots,n} |d_i|$.
    \end{itemize}

\end{definition}

\begin{definition}[Condition Number]
    \label{def:Condition_Number}
    \lean{conditionNumber}
    For an invertible matrix $V \in \mathbb{C}^{n \times n}$, its condition number with respect to a norm is defined as $\kappa_p(V) = \|V\| \|V^{-1}\|$.
\end{definition}

\begin{lemma}[Equivalent Eigenvalue Condition]
    \label{lem:Equivalent_Eigenvalue_Condition}
    \lean{equivalent_eigenvalue_condition}
    Let $A$ be a diagonalizable matrix with eigenvector matrix $V$ and eigenvalue matrix $\Lambda$. Let $\mu$ be an eigenvalue of the perturbed matrix $A + \delta A$. If $\mu \notin \Lambda(A)$, then $-1$ is an eigenvalue of the matrix $(\Lambda - \mu I)^{-1} V^{-1} \delta A V$.
\end{lemma}

\begin{proof}
    Since $\mu$ is an eigenvalue of $A + \delta A$, the matrix $(A + \delta A - \mu I)$ is singular, so its determinant is zero. Using lemma \ref{lem:Determinant_Invariance}:
    $$ 0 = \det(A + \delta A - \mu I) = \det(V^{-1}(A + \delta A - \mu I)V) $$
    $$ 0 = \det(V^{-1}AV + V^{-1}\delta A V - \mu V^{-1}IV) = \det(\Lambda + V^{-1}\delta A V - \mu I) $$
    $$ 0 = \det((\Lambda - \mu I) + V^{-1}\delta A V) $$
    Since $\mu \notin \Lambda(A)$, the diagonal matrix $(\Lambda - \mu I)$ is invertible. Using lemma \ref{lem:Determinant_Multiplicative}:
    $$ 0 = \det(\Lambda - \mu I) \det(I + (\Lambda - \mu I)^{-1} V^{-1} \delta A V) $$
    As $\det(\Lambda - \mu I) \neq 0$, we must have $\det(I + (\Lambda - \mu I)^{-1} V^{-1} \delta A V) = 0$.
    This implies that the matrix $M = I + (\Lambda - \mu I)^{-1} V^{-1} \delta A V$ is singular and thus has an eigenvalue of $0$. Let $N = (\Lambda - \mu I)^{-1} V^{-1} \delta A V$, so $M=I+N$. Since $0$ is an eigenvalue of $I+N$, it follows that $N$ must have an eigenvalue of $0-1 = -1$.
\end{proof}


\begin{lemma}[Norm of an Inverted Diagonal Matrix]
    \label{lem:Norm_of_Inverted_Diagonal_Matrix}
    \lean{norm_inverted_diagonal}
    \uses{def:Subordinate_Matrix_Norm}
    Let $\Lambda$ be a diagonal matrix with diagonal entries $\lambda_1, \dots, \lambda_n$. For any scalar $\mu$ such that $\lambda_i \neq \mu$ for all $i$, the p-norm of the inverse of $(\Lambda - \mu I)$ is given by:
    $$ \|(\Lambda - \mu I)^{-1}\|_p = \frac{1}{\min_{i} |\lambda_i - \mu|} $$
\end{lemma}

\begin{proof}
    The matrix $(\Lambda - \mu I)^{-1}$ is a diagonal matrix with diagonal entries $(\lambda_i - \mu)^{-1}$ for $i=1, \dots, n$. Then
    $$ \|(\Lambda - \mu I)^{-1}\|_p = \max_{i} \left| \frac{1}{\lambda_i - \mu} \right| = \frac{1}{\min_{i} |\lambda_i - \mu|} $$
    This concludes the proof.
\end{proof}

\begin{theorem}[Bauer–Fike Theorem]
    \label{thm:Bauer-Fike_Theorem}
    \lean{bauer_fike}
    \uses{def:Subordinate_Matrix_Norm}
    \uses{def:Condition_Number}
    \uses{lem:Equivalent_Eigenvalue_Condition}
    \uses{lem:Norm_of_Inverted_Diagonal_Matrix}
    Let $A \in \mathbb{C}^{n \times n}$ be a diagonalizable matrix, and let $\mu$ be an eigenvalue of $A + \delta A$. Then there exists an eigenvalue $\lambda \in \Lambda(A)$ such that:
    $$ |\lambda - \mu| \le \kappa_p(V) \|\delta A\|_p $$
    where $V$ is the matrix of eigenvectors of $A$ and $\kappa_p(V)$ is the condition number of $V$.
\end{theorem}

\begin{proof}
    If $\mu$ is an eigenvalue of $A$, we can choose $\lambda = \mu$, so $|\lambda - \mu| = 0$. Since $\kappa_p(V) \ge 1$ by lemma \ref{lem:Condition_Number_Lower_Bound} and $\|\delta A\|_p \ge 0$, the inequality $0 \le \kappa_p(V) \|\delta A\|_p$ holds trivially.

    If $\mu$ is not an eigenvalue of $A$, by lemma \ref{lem:Equivalent_Eigenvalue_Condition}, we know that $-1$ is an eigenvalue of the matrix $M = (\Lambda - \mu I)^{-1} V^{-1} \delta A V$.

    Using the property of subordinate matrix norms from definition \ref{def:Subordinate_Matrix_Norm}, the magnitude of any eigenvalue is bounded by the norm of the matrix:
    $$ 1 = |-1| \le \|M\|_p = \|(\Lambda - \mu I)^{-1} V^{-1} \delta A V\|_p $$
    By the sub-multiplicative property of the norm and definition \ref{def:Condition_Number}:
    $$ 1 \le \|(\Lambda - \mu I)^{-1}\|_p \|V^{-1}\|_p \|\delta A\|_p \|V\|_p = \|(\Lambda - \mu I)^{-1}\|_p \kappa_p(V) \|\delta A\|_p $$
    Applying lemma \ref{lem:Norm_of_Inverted_Diagonal_Matrix}:
    $$ 1 \le \left(\frac{1}{\min_{\lambda \in \Lambda(A)} |\lambda - \mu|}\right) \kappa_p(V) \|\delta A\|_p $$
    Rearranging this inequality gives the desired result:
    $$ \min_{\lambda \in \Lambda(A)} |\lambda - \mu| \le \kappa_p(V) \|\delta A\|_p $$
    This implies the existence of a $\lambda \in \Lambda(A)$ satisfying the theorem's inequality.
\end{proof}

