\chapter{Berge's theorem}

This section contains a (stub of a) proof of Berge's theorem.
See \url{https://en.wikipedia.org/wiki/Berge's_theorem} for more details.

\begin{definition}[Augmenting path]
  \label{def:augmenting-path}
  \lean{SimpleGraph.Subgraph.IsAugmentingPath}
  Let \(G\) be a finite graph and \(M\) be a matching in \(G\).
  An \emph{\(M\)-augmenting path} is a path in \(G\) that starts and ends with unmatched vertices, and whose edges alternate between edges not in \(M\) and edges in \(M\).
\end{definition}

\begin{theorem}[Berge's theorem, forward direction]
  \label{theorem:berge-forward}
  \lean{SimpleGraph.Subgraph.IsMatching.not_maximal_of_augmentingPath}
  \uses{def:augmenting-path}
  Let \(G\) be a finite graph and \(M\) be a matching in \(G\).
  If there is an \(M\)-augmenting path in \(G\), then \(M\) is not a matching of maximal cardinality.
\end{theorem}

\begin{proof}
  Let \(P\) be an \(M\)-augmenting path in \(G\).
  We can construct a new matching \(M'\) by taking the symmetric difference of \(M\) and the edges of \(P\).
  Since \(P\) starts and ends with unmatched vertices, the number of edges in \(M'\) is one more than the number of edges in \(M\).
  Therefore, \(M'\) is a matching of larger cardinality than \(M\), which means that \(M\) is not a matching of maximal cardinality.
\end{proof}

\begin{lemma}[symmetric difference of matchings]
  \label{lemma:symmetric-difference-matchings}
  \lean{SimpleGraph.isAlternating_symmDiff_of_isMatching}
  Let \(G\) be a finite graph and \(M\) and \(M'\) be two matchings in \(G\).
  Then the graph formed by the edges in the symmetric difference \(M \oplus M'\) consists of a union of paths and cycles where edges alternate between those in \(M\) and those in \(M'\).
\end{lemma}

\begin{proof}
  Each vertex in the graph formed by \(M \oplus M'\) has degree at most 2, since it can be incident to at most one edge from \(M\) and at most one edge from \(M'\).
  Therefore, the connected components of this graph are either paths or cycles.
  Moreover, since \(M\) and \(M'\) are matchings, the edges in these paths and cycles cannot be adjacent to each other if they belong to the same matching, which means that the edges must alternate between those in \(M\) and those in \(M'\).
\end{proof}

\begin{theorem}[Berge's theorem, backward direction]
  \label{theorem:berge-backward}
  \lean{SimpleGraph.Subgraph.IsMatching.maximal_of_no_augmentingPath}
  \uses{lemma:symmetric-difference-matchings, def:augmenting-path}
  Let \(G\) be a finite graph and \(M\) be a matching in \(G\).
  If there is no \(M\)-augmenting path in \(G\), then \(M\) is a matching of maximal cardinality.
\end{theorem}

\begin{proof}
  Assume for the sake of contradiction that \(M\) is not a matching of maximal cardinality.
  Then there exists a matching \(M'\) in \(G\) such that \(|M'| > |M|\).
  Consider the symmetric difference \(M \oplus M'\), which consists of edges that are in either \(M\) or \(M'\) but not in both.
  The graph formed by the edges in \(M \oplus M'\) consists of paths and cycles where edges alternate between those in \(M\) and those in \(M'\), as stated in Lemma~\ref{lemma:symmetric-difference-matchings}.
  Cycles contain an equal number of edges from \(M\) and \(M'\), so they do not contribute to the difference in cardinality between \(M\) and \(M'\).
  Since \(|M'| > |M|\), there must be at least one path in this graph that starts and ends with unmatched vertices (with respect to \(M\)).
  This path is an \(M\)-augmenting path, which contradicts our assumption that there are no \(M\)-augmenting paths in \(G\).
  Therefore, \(M\) must be a matching of maximal cardinality.
\end{proof}

\begin{theorem}[Berge's theorem]
  \label{theorem:berge}
  \lean{SimpleGraph.Subgraph.IsMatching.berge}
  \uses{theorem:berge-forward, theorem:berge-backward, def:augmenting-path}
  Let \(G\) be a finite graph and \(M\) be a matching in \(G\).
  Then \(M\) is a matching of maximal cardinality if and only if there is no \(M\)-augmenting path in \(G\).
\end{theorem}

\begin{proof}
  This follows directly from the earlier proofs of the forward and backward directions Theorem~\ref{theorem:berge-forward} and Theorem~\ref{theorem:berge-backward}.
\end{proof}

\chapter{Bondy's theorem}

This section contains a (stub of a) proof of Bondy's theorem.
See \url{https://en.wikipedia.org/wiki/Bondy's_theorem} for more details.

\begin{definition}[Hypercube Graph]
    \label{def:hypercube-graph}
    \lean{hypercubeGraph}
    The \emph{hypercube graph} $Q_n$ is the graph whose vertices are the subsets of $[n]$, and two vertices $A, B$ are adjacent if and only if $|A \triangle B| = 1$.
\end{definition}

\begin{lemma}
    \label{lem:parallel-edges-hypercube-graph}
    \lean{hypercube_cycle_has_parallel_edges}
    \uses{def:hypercube-graph}
    Any cycle in $Q_n$ has two distinct edges that are parallel.
\end{lemma}

\begin{proof}
    Let $C$ be a cycle in $Q_n$, and let $v_1, \dots, v_k$ be the vertices of $C$ in order.
    Let $i$ be the index along which $v_0, v_1$ differ, and let $v_j$ be the next vertex in $c$ which is equal to $v_0$ along index $i$.
    Then the edges $v_0 v_1$ and $v_{j-1} v_j$ are parallel.
\end{proof}

\begin{lemma}
    \label{lem:acyclic-graph-vertices-edges-components}
    \lean{acyclic_card_eq_edges_add_components}
    An acyclic graph has a number of vertices equal to the sum of the number of edges and the number of connected components.
\end{lemma}

\begin{proof}
    We proceed by induction on the number of edges.
    If there are no edges, then the number of vertices is equal to the number of connected components, and we are done.
    Otherwise, let $e$ be an edge, and let $G'$ be the graph obtained by removing $e$ from $G$.
    Then $G'$ has one more connected component than $G$, and one less edge than $G$, so the number of vertices in $G'$ is equal to the number of edges in $G$ plus the number of connected components in $G$.
    Since $G$ is acyclic, it has at least one edge, so the number of vertices in $G$ is equal to the number of edges in $G$ plus the number of connected components in $G$.
\end{proof}

\begin{theorem}[Bondy's theorem]
    \label{thm:bondy-theorem}
    \lean{bondy}
    \uses{lem:parallel-edges-hypercube-graph, lem:acyclic-graph-vertices-edges-components}
    Let $A_0, \dots, A_{n-1} \subseteq [n]$ be distinct sets.
    Then there exists a set $S \subseteq [n]$ of size $n-1$ such that the sets $A_0 \cap S, \dots, A_{n-1} \cap S$ are distinct.
\end{theorem}

\begin{proof}
  Suppose for contradiction that for every $S$ of size $n-1$, i.e. for every $S = {0, 1, ..., n-1} \ {k}$, there exist $i ≠ j$ such that $(S ∩ A_i) = (S ∩ A_j)$.
  This would make an induced subgraph of $n$ edges on the boolean hypercube with one edge in every orientation
  But such a subgraph must be a forest, by Lemma~\ref{lem:parallel-edges-hypercube-graph}.
  By Lemma~\ref{lem:acyclic-graph-vertices-edges-components}, the number of vertices in this subgraph is equal to the number of edges plus the number of connected components, which is at least $n + 1$.
  Thus the number of vertices of the subgraph is at least $n+1$, a contradiction to the claim that there are only $n$ vertices (the $A_i$'s).
\end{proof}

