\chapter{Brunn-Minkowski Theorem}

This section contains a proof of the Brunn-Minkowski Theorem.
See \url{https://en.wikipedia.org/wiki/Brunn%E2%80%93Minkowski_theorem} for more details.

\begin{lemma}
    \label{lem:PL_ineq_dim1'}
    \lean{prekopa_leindler_dim1}
    Let $0 < \lambda < 1$ and let $f, g, h$ be nonnegative integrable functions on $\mathbb{R}$ satisfying
    \[ h\big((1-\lambda)x + \lambda y\big) \;\ge\; f(x)^{1-\lambda} g(y)^{\lambda} \tag{10}\]
    for all $x,y \in \mathbb{R}$. Then
    \[
    \int_{\mathbb{R}} h(x)\,dx \;\ge\;
    \left( \int_{\mathbb{R}} f(x)\,dx \right)^{1-\lambda}
    \left( \int_{\mathbb{R}} g(x)\,dx \right)^{\lambda}.
    \tag{12}
    \]
\end{lemma}
\begin{proof}
    If $\int_{\mathbb{R}} f(x)\,dx = 0$ or $\int_{\mathbb{R}} g(x)\,dx = 0$ the Prékopa–Leindler inequality (12) holds trivially. We thus assume $\int_{\mathbb{R}} f(x)\,dx = F > 0$ and $\int_{\mathbb{R}} g(x)\,dx = G > 0$.
    Define the auxiliary functions $u,v : [0,1] \to \mathbb{R}$ such that $u(t)$ and $v(t)$ are the smallest numbers satisfying
    \[
    \frac{1}{F}\int_{-\infty}^{u(t)} f(x)\,dx
    = \frac{1}{G}\int_{-\infty}^{v(t)} g(x)\,dx
    = t.
    \tag{13}
    \]
    Since $f$ and $g$ are nonnegative, $u$ and $v$ are strictly increasing functions and hence are differentiable almost everywhere. Note that $u$ and $v$ do not have to be continuous everywhere. Taking the derivative of (13) with respect to $t$ gives for almost every $t$:
    \[
    \frac{f(u(t))u'(t)}{F} = \frac{g(v(t))v'(t)}{G} = 1.
    \tag{14}
    \]
    Let $w(t) = (1-\lambda)u(t) + \lambda v(t)$. By (14), for almost every $t \in (0,1)$ we have $f(u(t)) \neq 0 \neq g(v(t))$, and thus also
    \[
    \begin{aligned}
    w'(t) &= (1-\lambda)u'(t) + \lambda v'(t) \\
    &\ge u'(t)^{1-\lambda} v'(t)^{\lambda} \\
    &= \left( \frac{F}{f(u(t))} \right)^{1-\lambda}
      \left( \frac{G}{g(v(t))} \right)^{\lambda},
    \end{aligned}
    \tag{15}
    \]
    where we used Young’s inequality in the first step and (14) in the second step.
    By assumption (10), (15), $h \ge 0$ and $w$ being strictly increasing we have
    \[
    \int_{\mathbb{R}} h(x)\,dx
    \;\ge\; \int_{0}^{1} h(w(t))w'(t)\,dt
    \]
    \[
    \;\ge\; \int_{0}^{1} f(u(t))^{1-\lambda} g(v(t))^{\lambda}
    \left( \frac{F}{f(u(t))} \right)^{1-\lambda}
    \left( \frac{G}{g(v(t))} \right)^{\lambda} dt
    \]
    \[
    = F^{1-\lambda} G^{\lambda}
    = \left(\int_{\mathbb{R}} f(x)\,dx\right)^{1-\lambda}
      \left(\int_{\mathbb{R}} g(x)\,dx\right)^{\lambda}.
    \]
\end{proof}

\begin{lemma}
    \label{lem:PL_ineq}
    \uses{lem:PL_ineq_dim1'}
    \lean{prekopa_leindler}
    Let $0 < \lambda < 1$ and let $f,g,h : \mathbb{R}^n \to [0,+\infty)$ be non-negative real valued measurable functions defined on $n$ dimensional Euclidean space $\mathbb{R}^n$. Suppose that these functions satisfy
    \[ h\big((1-\lambda)x + \lambda y\big) \;\ge\; f(x)^{1-\lambda} g(y)^{\lambda}
    \qquad \text{for all } x,y \in \mathbb{R}^n . \]
    Then
    \[ \int_{\mathbb{R}^n} h(x)\,dx \;\ge\;
    \left(\int_{\mathbb{R}^n} f(x)\,dx\right)^{1-\lambda}
    \left(\int_{\mathbb{R}^n} g(x)\,dx\right)^{\lambda} \]
\end{lemma}
\begin{proof}
    We have just proven the Prékopa–Leindler inequality holds for dimension $n=1$. Suppose that the Prékopa–Leindler inequality holds for all positive integers less than $n$.
    For each $s \in \mathbb{R}$, define a nonnegative function $h_s$ on $\mathbb{R}^{n-1}$ by
    \[
    h_s(z) := h(z,s) \quad \text{for } z \in \mathbb{R}^{n-1},
    \]
    and define $f_s$ and $g_s$ analogously. Let $a,b \in \mathbb{R}$, and let $c := (1-\lambda)a + \lambda b$. Then, for any $x,y \in \mathbb{R}^{n-1}$, by assumption (10)
    \[
    \begin{aligned}
    h_c((1-\lambda)x + \lambda y)
    &= h\big((1-\lambda)x + \lambda y, (1-\lambda)a + \lambda b\big) \\
    &= h\big((1-\lambda)(x,a) + \lambda(y,b)\big) \\
    &\ge f(x,a)^{1-\lambda} g(y,b)^{\lambda} \\
    &= f_a(x)^{1-\lambda} g_b(y)^{\lambda}.
    \end{aligned}
    \]
    Using our inductive hypothesis (11) for $n-1$ we obtain that
    \[
    \int_{\mathbb{R}^{n-1}} h_c(x)\,dx
    \;\ge\;
    \left( \int_{\mathbb{R}^{n-1}} f_a(x)\,dx \right)^{1-\lambda}
    \left( \int_{\mathbb{R}^{n-1}} g_b(x)\,dx \right)^{\lambda}.
    \]
    Now define
    \[
    F(a) := \int_{\mathbb{R}^{n-1}} f_a(x)\,dx,
    \quad G(b) := \int_{\mathbb{R}^{n-1}} g_b(x)\,dx,
    \quad H(c) := \int_{\mathbb{R}^{n-1}} h_c(x)\,dx.
    \]
    Then this inequality reads
    \[
    H(c) = H((1-\lambda)a + \lambda b) \;\ge\; F(a)^{1-\lambda} G(b)^{\lambda}.
    \]
    Finally, using Fubini’s theorem and our induction base $n=1$ Lemma 12, we find that
    \[
    \begin{aligned}
    \int_{\mathbb{R}^n} h(x)\,dx
    &= \int_{\mathbb{R}} \int_{\mathbb{R}^{n-1}} h_c(z)\,dz\,dc \\
    &= \int_{\mathbb{R}} H(c)\,dc \\
    &\ge \left( \int_{\mathbb{R}} F(a)\,da \right)^{1-\lambda}
       \left( \int_{\mathbb{R}} G(b)\,db \right)^{\lambda} \\
    &= \left( \int_{\mathbb{R}^n} f(x)\,dx \right)^{1-\lambda}
       \left( \int_{\mathbb{R}^n} g(x)\,dx \right)^{\lambda},
    \end{aligned}
    \]
    proving the Prékopa–Leindler inequality in all dimensions.
\end{proof}

\begin{lemma}
    \label{lem:PL_ineq_variant}
    \uses{lem:PL_ineq}
    \lean{prekopa_leindler'}
    Let $d \in \mathbb{N}$ and $t \in (0,1)$. Let $f, g, h: \mathbb{R}^d \to \mathbb{R}_{\ge 0}$ be three non-negative, integrable functions on the Euclidean space $\mathbb{R}^d$.
    Assume that for all $x, y \in \mathbb{R}^d$, the following pointwise condition holds:
    $$f(x)^{1-t} g(y)^t \le h(x+y).$$
    Then their integrals satisfy the inequality:
    $$\left(\int_{\mathbb{R}^d} f(x)\,dx\right)^{1-t} \left(\int_{\mathbb{R}^d} g(y)\,dy\right)^{t} \le (1-t)^{d(1-t)} t^{dt} \int_{\mathbb{R}^d} h(z)\,dz.$$
\end{lemma}
\begin{proof}
    Consider the rescaled functions
    \[ \phi(x) := f\big((1-t)x\big),\qquad \psi(y) := g\big(ty\big). \]
    For any $x,y\in\mathbb R^d$,
    \[ \phi(x)^{\,1-t}\psi(y)^{\,t}
    = f\big((1-t)x\big)^{1-t}\,g\big(ty\big)^{t}
    \le h\big((1-t)x+ty\big), \]
    where the inequality is exactly the given assumption with the substitutions $x\mapsto(1-t)x$ and $y\mapsto ty$.
    By the classical Prékopa–Leindler inequality (in its Jensen-type form),
    \[ \int_{\mathbb R^d} h \ \ge\
    \Big(\int_{\mathbb R^d}\phi\Big)^{1-t}
    \Big(\int_{\mathbb R^d}\psi\Big)^{t}.
    \tag{1} \]
    Now compute the two integrals via change of variables. Since the linear maps $x\mapsto (1-t)x$ and $y\mapsto ty$ have Jacobians $(1-t)^d$ and $t^d$ respectively,
    \[ \int_{\mathbb R^d}\phi(x)\,dx
    =\int f\big((1-t)x\big)\,dx
    =(1-t)^{-d}\!\int f,
    \qquad
    \int_{\mathbb R^d}\psi(y)\,dy
    =\int g(ty)\,dy
    =t^{-d}\!\int g.
    \tag{2} \]
    Plug (2) into (1):
    \[ \int h \ \ge\
    \big((1-t)^{-d}\!\int f\big)^{1-t}
    \big(t^{-d}\!\int g\big)^{t}
    =(1-t)^{-d(1-t)}\,t^{-dt}\,
    \Big(\int f\Big)^{1-t}\Big(\int g\Big)^t. \]
    Rearranging gives
    \[\Big(\int f\Big)^{1-t}\Big(\int g\Big)^{t}
    \ \le\ (1-t)^{\,d(1-t)}\,t^{\,dt}\,\int h, \]
    which is the desired inequality.
\end{proof}

\begin{lemma}
    \label{lem:vol_mul_le}
    \lean{prekopa_leindler'}
    \leanok
    For any $f, g, h : \mathbb R^n \to \mathbb R$ integrable functions, $t \in \left(0, 1\right)$
    and $d \in \mathbb N$, $\left(\int_{\mathbb R^d} f(x) dx\right)^{1-t} * \left(\int_{\mathbb R^d} g(y) dy \right)^t \le
    (1 - t) ^ (d * (1 - t)) * t ^ (d * t) * \int_{mathbb R^n} h (z) dz$.
\end{lemma}
\begin{proof}
    \uses{lem:PL_ineq_variant}
    This is another version of the Prékopa–Leindler inequality, which is trivial after ~\href{lem:PL_ineq_variant}.
\end{proof}

\begin{theorem}[Brunn-Minkowski Inequality (Additive Form)]
    \label{thm:Brunn-Minkowski_Inequality_Additive}
    \uses{lem:PL_ineq_variant}
    \lean{EuclideanSpace.volume_pow_add_le}
    \uses{lem:PL_ineq_variant}
    Let $A$ and $B$ be two non-empty measurable subsets of $\mathbb{R}^n$ such that $A+B$ is also measurable. Then the following inequality holds:
    \[ [\mu(A+B)]^{1/n} \geq [\mu(A)]^{1/n} + [\mu(B)]^{1/n}. \]
\end{theorem}

\begin{proof}
    \uses{lem:vol_mul_le}
    Let $n \geq 1$ and let $A, B \subseteq \mathbb{R}^n$ be non-empty, compact, and measurable sets. We aim to prove that
    $(\mathrm{vol}(A+B))^{1/n} \geq (\mathrm{vol}(A))^{1/n} + (\mathrm{vol}(B))^{1/n},$
    where $A+B={a+b \mid a\in A,, b\in B}$.

    The proof proceeds in two stages: first, we handle the trivial cases, and then, in the general case, we appeal to the **Prékopa–Leindler inequality**. If $\mathrm{vol}(A)=0$, the inequality reduces to $(\mathrm{vol}(A+B))^{1/n}\geq (\mathrm{vol}(B))^{1/n}$, which is immediate since $B\subseteq A+B$. A symmetric argument applies if $\mathrm{vol}(B)=0$. If $\mathrm{vol}(A+B)=\infty$, the inequality holds trivially. Thus, we may assume that $\mathrm{vol}(A), \mathrm{vol}(B),$ and $\mathrm{vol}(A+B)$ are all finite and strictly positive.

    In this setting, consider a parameter $t$ with $0<t<1$. Applying the Prékopa–Leindler inequality to the indicator functions $f=\mathbf{1}\_A$ and $g=\mathbf{1}*B$ yields
    $(\mathrm{vol}(A))^{1-t} \cdot (\mathrm{vol}(B))^t \leq \big((1-t)^{1-t} t^t\big)^n \cdot \mathrm{vol}(A+B).$
    This holds because for every $x\in A$ and $y\in B$, one has $x+y\in A+B$, ensuring that $f(x)^{1-t}g(y)^t \leq \mathbf{1}*{A+B}((1-t)x+ty)$.

    The crucial step is a specific choice of $t$. Define $v\_A = (\mathrm{vol}(A))^{1/n}$ and $v\_B = (\mathrm{vol}(B))^{1/n}$, and set
    $t = \frac{v_B}{v_A+v_B}, \qquad 1-t = \frac{v_A}{v_A+v_B}.$
    Substituting these values into the inequality above and simplifying, the intermediate factors cancel, leaving
    $(v_A+v_B)^n \leq \mathrm{vol}(A+B).$
    Taking the $n$-th root of both sides gives
    $v_A+v_B \leq (\mathrm{vol}(A+B))^{1/n},$
    or equivalently,
    $(\mathrm{vol}(A))^{1/n} + (\mathrm{vol}(B))^{1/n} \leq (\mathrm{vol}(A+B))^{1/n}.$

    This completes the proof of the Brunn–Minkowski inequality.
\end{proof}

\begin{theorem}[Brunn-Minkowski Inequality (Multiplicative Form)]
    \label{thm:Brunn-Minkowski_Inequality_Multiplicative}
    \lean{EuclideanSpace.volume_pow_mul_le}
    \uses{thm:Brunn-Minkowski_Inequality_Additive}
    Let $A$ and $B$ be two non-empty measurable subsets of $\mathbb{R}^n$ such that their Minkowski convex combination is measurable. For any $\lambda \in [0, 1]$, the following inequality holds:
    \[ \mu(\lambda A + (1-\lambda)B) \geq \mu(A)^\lambda \mu(B)^{1-\lambda}. \]
    This form is equivalent to the additive form.
\end{theorem}

\begin{proof}
    Applying Theorem~\ref{thm:Brunn-Minkowski_Inequality_Additive} to the sets $\lambda A$ and $(1-\lambda)B$, we have
    \[\mu(\lambda A + (1-\lambda)B)^{1/n} \geq \mu(\lambda A)^{1/n} + \mu((1-\lambda)B)^{1/n}.\]
    Since scaling a set by a factor $c$ scales its volume by $c^n$, we have
    \[\mu(\lambda A) = \lambda^n \mu(A) \quad \text{and} \quad \mu((1-\lambda)B) = (1-\lambda)^n \mu(B).\]
    Substituting these into the inequality gives
    \[\mu(\lambda A + (1-\lambda)B)^{1/n} \geq \lambda \mu(A)^{1/n} + (1-\lambda) \mu(B)^{1/n}.\]
    By the weighted arithmetic-geometric mean inequality, we have
    \[\lambda \mu(A)^{1/n} + (1-\lambda) \mu(B)^{1/n} \geq \mu(A)^{\lambda/n} \mu(B)^{(1-\lambda)/n}.\]
    Combining these results, we obtain
    \[\mu(\lambda A + (1-\lambda)B)^{1/n} \geq \mu(A)^{\lambda/n} \mu(B)^{(1-\lambda)/n}.\]
    Raising both sides to the power of $n$ yields the desired inequality:
    \[\mu(\lambda A + (1-\lambda)B) \geq \mu(A)^\lambda \mu(B)^{1-\lambda}.\]
\end{proof}

\chapter{Brunn-Minkowski Theorem}

This section contains a proof of the Brunn-Minkowski Theorem.
See \url{https://en.wikipedia.org/wiki/Brunn%E2%80%93Minkowski_theorem} for more details.

\begin{lemma}
    \label{lem:PL_ineq_dim1'}
    \lean{prekopa_leindler_dim1}
    Let $0 < \lambda < 1$ and let $f, g, h$ be nonnegative integrable functions on $\mathbb{R}$ satisfying
    \[ h\big((1-\lambda)x + \lambda y\big) \;\ge\; f(x)^{1-\lambda} g(y)^{\lambda} \tag{10}\]
    for all $x,y \in \mathbb{R}$. Then
    \[
    \int_{\mathbb{R}} h(x)\,dx \;\ge\;
    \left( \int_{\mathbb{R}} f(x)\,dx \right)^{1-\lambda}
    \left( \int_{\mathbb{R}} g(x)\,dx \right)^{\lambda}.
    \tag{12}
    \]
\end{lemma}
\begin{proof}
    If $\int_{\mathbb{R}} f(x)\,dx = 0$ or $\int_{\mathbb{R}} g(x)\,dx = 0$ the Prékopa–Leindler inequality (12) holds trivially. We thus assume $\int_{\mathbb{R}} f(x)\,dx = F > 0$ and $\int_{\mathbb{R}} g(x)\,dx = G > 0$.
    Define the auxiliary functions $u,v : [0,1] \to \mathbb{R}$ such that $u(t)$ and $v(t)$ are the smallest numbers satisfying
    \[
    \frac{1}{F}\int_{-\infty}^{u(t)} f(x)\,dx
    = \frac{1}{G}\int_{-\infty}^{v(t)} g(x)\,dx
    = t.
    \tag{13}
    \]
    Since $f$ and $g$ are nonnegative, $u$ and $v$ are strictly increasing functions and hence are differentiable almost everywhere. Note that $u$ and $v$ do not have to be continuous everywhere. Taking the derivative of (13) with respect to $t$ gives for almost every $t$:
    \[
    \frac{f(u(t))u'(t)}{F} = \frac{g(v(t))v'(t)}{G} = 1.
    \tag{14}
    \]
    Let $w(t) = (1-\lambda)u(t) + \lambda v(t)$. By (14), for almost every $t \in (0,1)$ we have $f(u(t)) \neq 0 \neq g(v(t))$, and thus also
    \[
    \begin{aligned}
    w'(t) &= (1-\lambda)u'(t) + \lambda v'(t) \\
    &\ge u'(t)^{1-\lambda} v'(t)^{\lambda} \\
    &= \left( \frac{F}{f(u(t))} \right)^{1-\lambda}
      \left( \frac{G}{g(v(t))} \right)^{\lambda},
    \end{aligned}
    \tag{15}
    \]
    where we used Young’s inequality in the first step and (14) in the second step.
    By assumption (10), (15), $h \ge 0$ and $w$ being strictly increasing we have
    \[
    \int_{\mathbb{R}} h(x)\,dx
    \;\ge\; \int_{0}^{1} h(w(t))w'(t)\,dt
    \]
    \[
    \;\ge\; \int_{0}^{1} f(u(t))^{1-\lambda} g(v(t))^{\lambda}
    \left( \frac{F}{f(u(t))} \right)^{1-\lambda}
    \left( \frac{G}{g(v(t))} \right)^{\lambda} dt
    \]
    \[
    = F^{1-\lambda} G^{\lambda}
    = \left(\int_{\mathbb{R}} f(x)\,dx\right)^{1-\lambda}
      \left(\int_{\mathbb{R}} g(x)\,dx\right)^{\lambda}.
    \]
\end{proof}

\begin{lemma}
    \label{lem:PL_ineq}
    \uses{lem:PL_ineq_dim1'}
    \lean{prekopa_leindler}
    Let $0 < \lambda < 1$ and let $f,g,h : \mathbb{R}^n \to [0,+\infty)$ be non-negative real valued measurable functions defined on $n$ dimensional Euclidean space $\mathbb{R}^n$. Suppose that these functions satisfy
    \[ h\big((1-\lambda)x + \lambda y\big) \;\ge\; f(x)^{1-\lambda} g(y)^{\lambda}
    \qquad \text{for all } x,y \in \mathbb{R}^n . \]
    Then
    \[ \int_{\mathbb{R}^n} h(x)\,dx \;\ge\;
    \left(\int_{\mathbb{R}^n} f(x)\,dx\right)^{1-\lambda}
    \left(\int_{\mathbb{R}^n} g(x)\,dx\right)^{\lambda} \]
\end{lemma}
\begin{proof}
    We have just proven the Prékopa–Leindler inequality holds for dimension $n=1$. Suppose that the Prékopa–Leindler inequality holds for all positive integers less than $n$.
    For each $s \in \mathbb{R}$, define a nonnegative function $h_s$ on $\mathbb{R}^{n-1}$ by
    \[
    h_s(z) := h(z,s) \quad \text{for } z \in \mathbb{R}^{n-1},
    \]
    and define $f_s$ and $g_s$ analogously. Let $a,b \in \mathbb{R}$, and let $c := (1-\lambda)a + \lambda b$. Then, for any $x,y \in \mathbb{R}^{n-1}$, by assumption (10)
    \[
    \begin{aligned}
    h_c((1-\lambda)x + \lambda y)
    &= h\big((1-\lambda)x + \lambda y, (1-\lambda)a + \lambda b\big) \\
    &= h\big((1-\lambda)(x,a) + \lambda(y,b)\big) \\
    &\ge f(x,a)^{1-\lambda} g(y,b)^{\lambda} \\
    &= f_a(x)^{1-\lambda} g_b(y)^{\lambda}.
    \end{aligned}
    \]
    Using our inductive hypothesis (11) for $n-1$ we obtain that
    \[
    \int_{\mathbb{R}^{n-1}} h_c(x)\,dx
    \;\ge\;
    \left( \int_{\mathbb{R}^{n-1}} f_a(x)\,dx \right)^{1-\lambda}
    \left( \int_{\mathbb{R}^{n-1}} g_b(x)\,dx \right)^{\lambda}.
    \]
    Now define
    \[
    F(a) := \int_{\mathbb{R}^{n-1}} f_a(x)\,dx,
    \quad G(b) := \int_{\mathbb{R}^{n-1}} g_b(x)\,dx,
    \quad H(c) := \int_{\mathbb{R}^{n-1}} h_c(x)\,dx.
    \]
    Then this inequality reads
    \[
    H(c) = H((1-\lambda)a + \lambda b) \;\ge\; F(a)^{1-\lambda} G(b)^{\lambda}.
    \]
    Finally, using Fubini’s theorem and our induction base $n=1$ Lemma 12, we find that
    \[
    \begin{aligned}
    \int_{\mathbb{R}^n} h(x)\,dx
    &= \int_{\mathbb{R}} \int_{\mathbb{R}^{n-1}} h_c(z)\,dz\,dc \\
    &= \int_{\mathbb{R}} H(c)\,dc \\
    &\ge \left( \int_{\mathbb{R}} F(a)\,da \right)^{1-\lambda}
       \left( \int_{\mathbb{R}} G(b)\,db \right)^{\lambda} \\
    &= \left( \int_{\mathbb{R}^n} f(x)\,dx \right)^{1-\lambda}
       \left( \int_{\mathbb{R}^n} g(x)\,dx \right)^{\lambda},
    \end{aligned}
    \]
    proving the Prékopa–Leindler inequality in all dimensions.
\end{proof}

\begin{lemma}
    \label{lem:PL_ineq_variant}
    \uses{lem:PL_ineq}
    \lean{prekopa_leindler'}
    Let $d \in \mathbb{N}$ and $t \in (0,1)$. Let $f, g, h: \mathbb{R}^d \to \mathbb{R}_{\ge 0}$ be three non-negative, integrable functions on the Euclidean space $\mathbb{R}^d$.
    Assume that for all $x, y \in \mathbb{R}^d$, the following pointwise condition holds:
    $$f(x)^{1-t} g(y)^t \le h(x+y).$$
    Then their integrals satisfy the inequality:
    $$\left(\int_{\mathbb{R}^d} f(x)\,dx\right)^{1-t} \left(\int_{\mathbb{R}^d} g(y)\,dy\right)^{t} \le (1-t)^{d(1-t)} t^{dt} \int_{\mathbb{R}^d} h(z)\,dz.$$
\end{lemma}
\begin{proof}
    Consider the rescaled functions
    \[ \phi(x) := f\big((1-t)x\big),\qquad \psi(y) := g\big(ty\big). \]
    For any $x,y\in\mathbb R^d$,
    \[ \phi(x)^{\,1-t}\psi(y)^{\,t}
    = f\big((1-t)x\big)^{1-t}\,g\big(ty\big)^{t}
    \le h\big((1-t)x+ty\big), \]
    where the inequality is exactly the given assumption with the substitutions $x\mapsto(1-t)x$ and $y\mapsto ty$.
    By the classical Prékopa–Leindler inequality (in its Jensen-type form),
    \[ \int_{\mathbb R^d} h \ \ge\
    \Big(\int_{\mathbb R^d}\phi\Big)^{1-t}
    \Big(\int_{\mathbb R^d}\psi\Big)^{t}.
    \tag{1} \]
    Now compute the two integrals via change of variables. Since the linear maps $x\mapsto (1-t)x$ and $y\mapsto ty$ have Jacobians $(1-t)^d$ and $t^d$ respectively,
    \[ \int_{\mathbb R^d}\phi(x)\,dx
    =\int f\big((1-t)x\big)\,dx
    =(1-t)^{-d}\!\int f,
    \qquad
    \int_{\mathbb R^d}\psi(y)\,dy
    =\int g(ty)\,dy
    =t^{-d}\!\int g.
    \tag{2} \]
    Plug (2) into (1):
    \[ \int h \ \ge\
    \big((1-t)^{-d}\!\int f\big)^{1-t}
    \big(t^{-d}\!\int g\big)^{t}
    =(1-t)^{-d(1-t)}\,t^{-dt}\,
    \Big(\int f\Big)^{1-t}\Big(\int g\Big)^t. \]
    Rearranging gives
    \[\Big(\int f\Big)^{1-t}\Big(\int g\Big)^{t}
    \ \le\ (1-t)^{\,d(1-t)}\,t^{\,dt}\,\int h, \]
    which is the desired inequality.
\end{proof}

\begin{lemma}
    \label{lem:vol_mul_le}
    \lean{prekopa_leindler'}
    \leanok
    For any $f, g, h : \mathbb R^n \to \mathbb R$ integrable functions, $t \in \left(0, 1\right)$
    and $d \in \mathbb N$, $\left(\int_{\mathbb R^d} f(x) dx\right)^{1-t} * \left(\int_{\mathbb R^d} g(y) dy \right)^t \le
    (1 - t) ^ (d * (1 - t)) * t ^ (d * t) * \int_{mathbb R^n} h (z) dz$.
\end{lemma}
\begin{proof}
    \uses{lem:PL_ineq_variant}
    This is another version of the Prékopa–Leindler inequality, which is trivial after ~\href{lem:PL_ineq_variant}.
\end{proof}

\begin{theorem}[Brunn-Minkowski Inequality (Additive Form)]
    \label{thm:Brunn-Minkowski_Inequality_Additive}
    \uses{lem:PL_ineq_variant}
    \lean{EuclideanSpace.volume_pow_add_le}
    \uses{lem:PL_ineq_variant}
    Let $A$ and $B$ be two non-empty measurable subsets of $\mathbb{R}^n$ such that $A+B$ is also measurable. Then the following inequality holds:
    \[ [\mu(A+B)]^{1/n} \geq [\mu(A)]^{1/n} + [\mu(B)]^{1/n}. \]
\end{theorem}

\begin{proof}
    \uses{lem:vol_mul_le}
    Let $n \geq 1$ and let $A, B \subseteq \mathbb{R}^n$ be non-empty, compact, and measurable sets. We aim to prove that
    $(\mathrm{vol}(A+B))^{1/n} \geq (\mathrm{vol}(A))^{1/n} + (\mathrm{vol}(B))^{1/n},$
    where $A+B={a+b \mid a\in A,, b\in B}$.

    The proof proceeds in two stages: first, we handle the trivial cases, and then, in the general case, we appeal to the **Prékopa–Leindler inequality**. If $\mathrm{vol}(A)=0$, the inequality reduces to $(\mathrm{vol}(A+B))^{1/n}\geq (\mathrm{vol}(B))^{1/n}$, which is immediate since $B\subseteq A+B$. A symmetric argument applies if $\mathrm{vol}(B)=0$. If $\mathrm{vol}(A+B)=\infty$, the inequality holds trivially. Thus, we may assume that $\mathrm{vol}(A), \mathrm{vol}(B),$ and $\mathrm{vol}(A+B)$ are all finite and strictly positive.

    In this setting, consider a parameter $t$ with $0<t<1$. Applying the Prékopa–Leindler inequality to the indicator functions $f=\mathbf{1}\_A$ and $g=\mathbf{1}*B$ yields
    $(\mathrm{vol}(A))^{1-t} \cdot (\mathrm{vol}(B))^t \leq \big((1-t)^{1-t} t^t\big)^n \cdot \mathrm{vol}(A+B).$
    This holds because for every $x\in A$ and $y\in B$, one has $x+y\in A+B$, ensuring that $f(x)^{1-t}g(y)^t \leq \mathbf{1}*{A+B}((1-t)x+ty)$.

    The crucial step is a specific choice of $t$. Define $v\_A = (\mathrm{vol}(A))^{1/n}$ and $v\_B = (\mathrm{vol}(B))^{1/n}$, and set
    $t = \frac{v_B}{v_A+v_B}, \qquad 1-t = \frac{v_A}{v_A+v_B}.$
    Substituting these values into the inequality above and simplifying, the intermediate factors cancel, leaving
    $(v_A+v_B)^n \leq \mathrm{vol}(A+B).$
    Taking the $n$-th root of both sides gives
    $v_A+v_B \leq (\mathrm{vol}(A+B))^{1/n},$
    or equivalently,
    $(\mathrm{vol}(A))^{1/n} + (\mathrm{vol}(B))^{1/n} \leq (\mathrm{vol}(A+B))^{1/n}.$

    This completes the proof of the Brunn–Minkowski inequality.
\end{proof}

\begin{theorem}[Brunn-Minkowski Inequality (Multiplicative Form)]
    \label{thm:Brunn-Minkowski_Inequality_Multiplicative}
    \lean{EuclideanSpace.volume_pow_mul_le}
    \uses{thm:Brunn-Minkowski_Inequality_Additive}
    Let $A$ and $B$ be two non-empty measurable subsets of $\mathbb{R}^n$ such that their Minkowski convex combination is measurable. For any $\lambda \in [0, 1]$, the following inequality holds:
    \[ \mu(\lambda A + (1-\lambda)B) \geq \mu(A)^\lambda \mu(B)^{1-\lambda}. \]
    This form is equivalent to the additive form.
\end{theorem}

\begin{proof}
    Applying Theorem~\ref{thm:Brunn-Minkowski_Inequality_Additive} to the sets $\lambda A$ and $(1-\lambda)B$, we have
    \[\mu(\lambda A + (1-\lambda)B)^{1/n} \geq \mu(\lambda A)^{1/n} + \mu((1-\lambda)B)^{1/n}.\]
    Since scaling a set by a factor $c$ scales its volume by $c^n$, we have
    \[\mu(\lambda A) = \lambda^n \mu(A) \quad \text{and} \quad \mu((1-\lambda)B) = (1-\lambda)^n \mu(B).\]
    Substituting these into the inequality gives
    \[\mu(\lambda A + (1-\lambda)B)^{1/n} \geq \lambda \mu(A)^{1/n} + (1-\lambda) \mu(B)^{1/n}.\]
    By the weighted arithmetic-geometric mean inequality, we have
    \[\lambda \mu(A)^{1/n} + (1-\lambda) \mu(B)^{1/n} \geq \mu(A)^{\lambda/n} \mu(B)^{(1-\lambda)/n}.\]
    Combining these results, we obtain
    \[\mu(\lambda A + (1-\lambda)B)^{1/n} \geq \mu(A)^{\lambda/n} \mu(B)^{(1-\lambda)/n}.\]
    Raising both sides to the power of $n$ yields the desired inequality:
    \[\mu(\lambda A + (1-\lambda)B) \geq \mu(A)^\lambda \mu(B)^{1-\lambda}.\]
\end{proof}

