\chapter{Cartan–Brauer–Hua theorem}

This section contains a proof of Cartan–Brauer–Hua theorem.
See \url{https://en.wikipedia.org/wiki/Cartan%E2%80%93Brauer%E2%80%93Hua_theorem} for more details.

\begin{lemma}
  \label{lem:hua_identity}
  \lean{hua_identity}
  Let $D$ be a division ring and let $a, b \in D$ such that $ab \neq ba$. Then
  \begin{displaymath}
    a = (b^{-1} - (a-1)^{-1}b^{-1}(a-1)) (a^{-1}b^{-1}a - (a-1)^{-1}b^{-1}(a-1))^{-1}
  \end{displaymath}
\end{lemma}
\begin{proof}
  Since $ab \neq ba$, $a, a-1, b$ are all nonzero hence invertible.
  Let $c = b^{-1} - (a-1)^{-1}b^{-1}(a-1)$.
  Let $d = a^{-1}b^{-1}a - (a-1)^{-1}b^{-1}(a-1)$.
  Then
  \begin{displaymath}
    ad = b^{-1}a - a(a-1)^{-1}b^{-1}(a-1)
    = b^{-1}a - (a-1+1)(a-1)^{-1}b^{-1}(a-1)
    = b^{-1}a - b^{-1}(a-1) - (a-1)^{-1}b^{-1}(a-1)
    = b^{-1} - (a-1)^{-1}b^{-1}(a-1) = c
  \end{displaymath}
  We must have $d \neq 0$, because otherwise $c=0$, implying
  \begin{displaymath}
    b^{-1} = (a-1)^{-1}b^{-1}(a-1)
  \end{displaymath}
  and multiplying $b(a-1)$ on the left and $b$ on the right, we get
  \begin{displaymath}
    b(a-1) = (a-1)b
  \end{displaymath}
  and therefore $ab = ba$, contradiction. Therefore, $a = cd^{-1}$.
\end{proof}

\begin{theorem}
  \label{thm:cartan_brauer_hua}
  \lean{cartan_brauer_hua}
  \uses{lem:hua_identity}
  If $D$ is a division ring and $K$ is a sub-division ring of $D$ such that $x K x^{-1} \subseteq K$
  for every $x$ not equal to $0$ in $D$, then either $K \subseteq Z(D)$ or $K=D$.
\end{theorem}
\begin{proof}
  Suppose, to the contrary, that $K \not\subseteq Z(D)$. Let $a \in D$, $b \in K$ such that
  $ab \neq ba$.
  Then, since $K^{\times}$ is a normal subgroup of $D^{\times}$, all the elements
  \begin{displaymath}
    b^{-1}, (a-1)^{-1}b^{-1}(a-1), a^{-1}b^{-1}a, (a-1)^{-1}b^{-1}(a-1)
  \end{displaymath}
  are in $K^{\times}$ and hence, by Lemma~\ref{lem:hua_identity}, $a \in K$.
  So every element of $D \setminus K$ commutes with $b$.
  Let $c \in D \setminus K$. Then $ac \in D \setminus K$. So both $c$, $ac$ commute with $b$.
  So $a = acc^{-1}$ also commutes with $b$, contradiction.
\end{proof}

\chapter{Casorati-Weierstrass Theorem}

This section contains a proof of the Casorati-Weierstrass Theorem.
See \url{https://en.wikipedia.org/wiki/Casorati%E2%80%93Weierstrass_theorem} for more details.

\begin{definition}[Essential Singularity]
    \lean{EssentialSingularity}
    \label{def:Essential_Singularity}
    An isolated singularity $z_0$ of a holomorphic function $f$ is called an essential singularity if it is neither a removable singularity nor a pole.
\end{definition}

\begin{lemma}[Boundedness from Non-Dense Image]
    \label{lem:Boundedness_from_Non_Dense_Image}
    \lean{boundedness_from_non_dense_image}
    Let $f$ be a holomorphic function in a punctured open neighborhood $U = \{z \in \mathbb{C} : 0 < |z - z_0| < \delta\}$ of an isolated singularity $z_0$. If the image $f(U)$ is not dense in $\mathbb{C}$, then there exists a complex number $w_0$ and a real number $\epsilon > 0$ such that the function $g(z) = \frac{1}{f(z) - w_0}$ is holomorphic and bounded on $U$.
\end{lemma}

\begin{proof}
    If $f(U)$ is not dense in $\mathbb{C}$, then by definition of dense sets, there exists a point $w_0 \in \mathbb{C}$ and an $\epsilon > 0$ such that the open disk $B(w_0, \epsilon)$ has no intersection with $f(U)$. This means that for all $z \in U$, we have $|f(z) - w_0| \ge \epsilon$.
    Now, consider the function $g(z) = \frac{1}{f(z) - w_0}$. Since the denominator $f(z) - w_0$ is never zero in $U$, $g(z)$ is holomorphic in $U$.
    Furthermore, for all $z \in U$, we have $|g(z)| = \frac{1}{|f(z) - w_0|} \le \frac{1}{\epsilon}$. Thus, $g(z)$ is bounded on $U$.
\end{proof}

\begin{lemma}[Characterization of Removable Singularities and Poles]
    \label{lem:Non_Essential_Singularity_Conclusion}
    \lean{not_EssentialSingularity_of}
    Let $f$ have an isolated singularity at $z_0$. Suppose there exists $w_0 \in \mathbb{C}$ such that $g(z) = \frac{1}{f(z) - w_0}$ has a removable singularity at $z_0$. Then $f(z)$ at $z_0$ is not an essential singularity.
\end{lemma}

\begin{proof}
    By the removable singularity theorem, $g(z)$ can be extended to a function $\tilde{g}$ that is holomorphic at $z_0$. We can express $f(z)$ in terms of $\tilde{g}(z)$ for $z$ in a punctured neighborhood of $z_0$: $f(z) = w_0 + \frac{1}{\tilde{g}(z)}$.
    There are two cases for the value of $\tilde{g}(z_0)$:
    \begin{enumerate}
        \item If $\tilde{g}(z_0) \neq 0$: Since $\tilde{g}$ is holomorphic and non-zero at $z_0$, the function $\frac{1}{\tilde{g}(z)}$ is also holomorphic at $z_0$. Thus, $\lim_{z \to z_0} f(z) = w_0 + \frac{1}{\tilde{g}(z_0)}$ exists and is finite. This implies that $z_0$ is a removable singularity for $f$.
        \item If $\tilde{g}(z_0) = 0$: Since $f(z)$ has an isolated singularity, $f(z)$ is not constant, so $g(z)$ is not identically zero. Thus, $\tilde{g}(z)$ is not identically zero. As $z \to z_0$, $|f(z)| \to \infty$, so this is a pole for $f$.
    \end{enumerate}
    In both cases, the singularity $z_0$ is either removable or a pole, and therefore not essential.
\end{proof}

\begin{theorem}[Casorati-Weierstrass]
    \label{thm:Casorati_Weierstrass}
    \lean{casorati_weierstrass}
    \uses{def:Essential_Singularity}
    Let $f$ be a holomorphic function with an essential singularity at $z_0$. For any punctured open neighborhood $U$ of $z_0$, the image $f(U)$ is dense in the complex plane $\mathbb{C}$.
\end{theorem}

\begin{proof}
    \uses{lem:Boundedness_from_Non_Dense_Image}
    \uses{lem:Non_Essential_Singularity_Conclusion}
    We prove this by contradiction. Assume that the image $f(U)$ is not dense in $\mathbb{C}$.
    By lemma \ref{lem:Boundedness_from_Non_Dense_Image}, this assumption implies that there exists $w_0 \in \mathbb{C}$ such that the function $g(z) = \frac{1}{f(z) - w_0}$ is holomorphic and bounded on $U$.
    According to the removable singularity theorem, because $g(z)$ is bounded on $U$, the singularity at $z_0$ must be removable for $g$.
    Finally, by lemma \ref{lem:Non_Essential_Singularity_Conclusion}, if $g(z)$ has a removable singularity at $z_0$, then $f(z)$ must have either a removable singularity or a pole at $z_0$.
    This contradicts our initial hypothesis that $z_0$ is an essential singularity of $f$, as per definition \ref{def:Essential_Singularity}. Therefore, the assumption that $f(U)$ is not dense in $\mathbb{C}$ must be false, and the theorem is proved.
\end{proof}

