\chapter{Condorcet's Jury Theorem}

This section contains a proof of Condorcet's Jury Theorem.
See \url{https://en.wikipedia.org/wiki/Condorcet%27s_jury_theorem} for more details.

\begin{definition}[Jury Accuracy]
  \label{def:jury_accuracy}
  \lean{jury_majority_decision_probability}
  The accuracy of a jury of size $2n+1$ is defined as the probability that the majority decision made by the jury is correct, which is given by the probability that a binomial random variable with parameters $n$ (the number of jurors) and $p$ (the probability of each juror being correct) exceeds $n$.
\end{definition}

\begin{lemma}[A sum of two independent binomial distributions is binomial]
  \label{lem:sum_of_two_independent_binomials_is_binomial}
  \lean{PMF.binomial_add_binomial}
  Let $X \sim \text{Binomial}(n_1, p)$ and $Y \sim \text{Binomial}(n_2, p)$ be two independent binomial random variables. Then the sum $Z = X + Y$ follows a binomial distribution with parameters $n_1 + n_2$ and $p$, i.e., $Z \sim \text{Binomial}(n_1 + n_2, p)$.
\end{lemma}

\begin{proof}
  This follows from the formula for the probability mass function of the sum of two independent random variables. Specifically, for any integer $k$,
  \[P(Z = k) = \sum_{i=0}^{k} P(X = i) P(Y = k - i)\]
  Substituting the binomial probability mass functions for $X$ and $Y$, we have
  \[P(Z = k) = \sum_{i=0}^{k} \binom{n_1}{i} p^i (1-p)^{n_1 - i} \cdot \binom{n_2}{k - i} p^{k - i} (1-p)^{n_2 - (k - i)}\]
  Simplifying this expression, we get
  \[P(Z = k) = p^k (1-p)^{(n_1 + n_2) - k} \sum_{i=0}^{k} \binom{n_1}{i} \binom{n_2}{k - i}\]
  By the Vandermonde's identity, we know that
  \[\sum_{i=0}^{k} \binom{n_1}{i} \binom{n_2}{k - i} = \binom{n_1 + n_2}{k}\]
  Therefore, we have
  \[P(Z = k) = \binom{n_1 + n_2}{k} p^k (1-p)^{(n_1 + n_2) - k}\]
  which is the probability mass function of a binomial distribution with parameters $n_1 + n_2$ and $p$. Thus, $Z \sim \text{Binomial}(n_1 + n_2, p)$.
\end{proof}

\begin{lemma}[Breakdown for increase of accuracy on adding two jurors]
  \label{lem:breakdown_for_increase_of_accuracy_on_adding_two_jurors}
  \lean{convolution_identity}
  \uses{def:jury_accuracy}
  \uses{lem:sum_of_two_independent_binomials_is_binomial}
  By adding two jurors to a jury of size $2n+1$, the increase in accuracy is given by
  the probability that the smaller jury has exactly $n$ correct votes and the two additional jurors are both correct,
  minus the probability that the smaller jury has exactly $n+1$ correct votes and both additional jurors are incorrect.
\end{lemma}

\begin{proof}
  Since a jury of size $2n+3$ can be viewed as a jury of size $2n+1$ plus two additional jurors, we can use \ref{lem:sum_of_two_independent_binomials_is_binomial} to express the distribution of correct votes in the larger jury as the sum of the distribution of correct votes in the smaller jury and the distribution of correct votes from the two additional jurors.

  Thus, the accuracy of the larger jury can be expressed as the sum, over all possible numbers of correct votes from the smaller jury, of the probability that the smaller jury has a certain number of correct votes multiplied by the probability that the two additional jurors contribute enough correct votes to ensure that the total number of correct votes exceeds half of $2n+3$.

  By analyzing the terms of this sum, we see that
  \begin{enumerate}
    \item When the smaller jury has $n-1$ or fewer correct votes, then the two additional jurors cannot make the total exceed $n+1$ correct votes.
    \item When the smaller jury has exactly $n$ correct votes, then both additional jurors must be correct to achieve a majority, which occurs with probability $p^2$.
    \item When the smaller jury has $n+1$ correct votes, then at least one of the additional jurors must be correct, which occurs with probability $1 - (1-p)^2 = p(2-p)$.
    \item When the smaller jury has over $n+1$ correct votes, then the larger jury will always have a majority of correct votes regardless of the additional jurors.
  \end{enumerate}
\end{proof}

\begin{lemma}[Expression for increase of accuracy on adding two jurors]
  \label{lem:expression_for_increase_of_accuracy_on_adding_two_jurors}
  \lean{jury_probability_recurrence}
  \uses{lem:breakdown_for_increase_of_accuracy_on_adding_two_jurors}
  By adding two jurors to a jury of size $2n+1$, the increase in accuracy can be expressed as
  \[\binom{2n+1}{n} p^n (1-p)^{n+1} p^2 - \binom{2n+1}{n+1} p^{n+1} (1-p)^{n+1} (1-p)^2\]
\end{lemma}

\begin{proof}

  From \ref{lem:breakdown_for_increase_of_accuracy_on_adding_two_jurors}
  if we compute the difference in accuracy between the larger and smaller juries,
  we find that it is given by
  the probability that the smaller jury has exactly $n$ correct votes and the two additional jurors are both correct,
  minus the probability that the smaller jury has exactly $n+1$ correct votes and both additional jurors are incorrect.

  This comes to
  \[\binom{2n+1}{n} p^n (1-p)^{n+1} p^2 - \binom{2n+1}{n+1} p^{n+1} (1-p)^{n+1} (1-p)^2\]
\end{proof}

\begin{lemma}[Adding two jurors increases accuracy]
  \label{lem:adding_two_jurors_increases_accuracy}
  \lean{jury_majority_decision_probability_succ_lt}
  \uses{def:jury_accuracy}
  \uses{lem:expression_for_increase_of_accuracy_on_adding_two_jurors}
  For a jury of size $2n+1$ where each juror has an independent probability $p > 1/2$ of making the correct decision, and another jury of size $2n+3$ formed by adding two jurors with the same accuracy, the probability that the larger jury makes the correct decision is greater than that of the smaller jury.
\end{lemma}

\begin{proof}
  By \ref{lem:expression_for_increase_of_accuracy_on_adding_two_jurors}, the increase in accuracy when adding two jurors is given by
  \[\binom{2n+1}{n} p^n (1-p)^{n+1} p^2 - \binom{2n+1}{n+1} p^{n+1} (1-p)^{n+1} (1-p)^2\]

  When $p > 0.5$, this expression is positive, showing that the accuracy of the larger jury is greater than that of the smaller jury.
\end{proof}

\begin{theorem}[Condorcet's Jury Theorem]
  \label{thm:condorcet_jury}
  \lean{condorcet_jury_theorem}
  \uses{def:jury_accuracy}
  \uses{lem:adding_two_jurors_increases_accuracy}
  If each member of a jury of odd size has an independent probability greater than 1/2 of making the correct decision, then as the size of the jury increases, the probability that the majority decision is correct approaches 1.
\end{theorem}

\begin{proof}
  The proof proceeds by induction on the size of the jury. For juries of sizes $2n + 1 < 2m + 1$, we can show by induction on $m-n$ that the accuracy of the larger jury is greater than that of the smaller jury. The base case where $m - n = 1$ is established by \ref{lem:adding_two_jurors_increases_accuracy}. The inductive step follows similarly by repeatedly applying the lemma.
\end{proof}

