\chapter{The De Bruijn-Erd\H{o}s Theorem for Graph Coloring}

This section contains a proof of the De Bruijn-Erd\H{o}s theorem for graph coloring. The proof, attributed to Gottschalk (1951), relies on Tychonoff's compactness theorem.
See \url{https://en.wikipedia.org/wiki/De_Bruijn%E2%80%93Erd%C5%91s_theorem_(graph_theory)} for more details.

\begin{lemma}[The Space of Colorings is Compact]
  \label{lem:coloring_space_compact}
  \lean{colorings_space_compact}
  Let $G=(V, E)$ be a graph and let $C$ be a finite set of $k$ colors. The space $X = C^V$ of all functions from the vertex set $V$ to $C$, endowed with the product topology, is a compact topological space.
\end{lemma}

\begin{proof}
We equip the finite set of colors $C$ with the discrete topology. In this topology, every subset of $C$ is open. Since $C$ is a finite set, it is compact.

The space $X = C^V$ is the generalized product of the space $C$ indexed by the vertex set $V$. By Tychonoff's theorem, the product of any collection of compact topological spaces is itself compact with respect to the product topology.

Since $X$ is a product of compact spaces, it is compact.
\end{proof}

\begin{lemma}[Subspaces of Valid Colorings are Closed]
  \label{lem:valid_colorings_closed}
  \lean{valid_colorings_is_closed}
  For any finite subgraph $F$ of $G$, the set $X_F \subseteq X$ consisting of all color assignments that constitute a valid $k$-coloring of $F$ is a closed set in the product topology.
\end{lemma}

\begin{proof}
A coloring $c \in X$ is a valid coloring of the finite subgraph $F=(V_F, E_F)$ if and only if for every edge $\{u, v\} \in E_F$, the colors assigned to vertices $u$ and $v$ are different; that is, $c(u) \neq c(v)$.

Thus, the set $X_F$ can be expressed as the intersection of sets:
$$ X_F = \bigcap_{\{u, v\} \in E_F} \{ c \in X \mid c(u) \neq c(v) \} $$

A finite intersection of closed sets is closed, so it suffices to show that for each edge $\{u, v\}$ in the finite subgraph $F$, the set of colorings where $u$ and $v$ have different colors is closed. For a given edge $\{u, v\}$, this can itself be expressed as the finite union of sets for particular valid color values. The individual sets are closed in the product topology because they are defined by fixing the values of the coloring function at two coordinates, which corresponds to taking preimages of closed sets under continuous projection maps.

\end{proof}

\begin{lemma}[The Finite Intersection Property]
  \label{lem:fip}
  \lean{finite_intersection_property}
  The family of sets $\mathcal{F} = \{X_F \mid F \text{ is a finite subgraph of } G\}$ has the finite intersection property.
\end{lemma}

\begin{proof}
To prove the finite intersection property, we must show that any finite intersection of sets from $\mathcal{F}$ is non-empty. Consider a finite collection of such sets: $X_{F_1}, X_{F_2}, \dots, X_{F_n}$. Their intersection is:
$$ \bigcap_{i=1}^{n} X_{F_i} $$
An element in this intersection is a color assignment that is a valid coloring for every subgraph $F_i$ simultaneously. This is equivalent to being a valid coloring for the union of these subgraphs.
Let $F_{\cup} = \bigcup_{i=1}^{n} F_i$. The union of a finite number of finite graphs is still a finite subgraph of $G$.

The central premise of the theorem is that every finite subgraph of $G$ is $k$-colorable. Since $F_{\cup}$ is a finite subgraph of $G$, there must exist at least one valid $k$-coloring for it. This means the set of valid colorings for $F_{\cup}$, which is precisely $\bigcap_{i=1}^{n} X_{F_i}$, is non-empty.

Thus, the family $\mathcal{F}$ has the finite intersection property.
\end{proof}

\begin{theorem}[De Bruijn-Erd\H{o}s Theorem (Graph Coloring)]
  \label{thm:de_bruijn_erdos}
  \lean{SimpleGraph.colorable_of_finitely_colorable}
  If for an infinite graph $G$, the chromatic number of every finite subgraph is at most a finite integer $k$, then the chromatic number of $G$ is also at most $k$.
\end{theorem}

\begin{proof}
  \uses{lem:coloring_space_compact, lem:valid_colorings_closed, lem:fip}
  Let $C$ be a set of $k$ colors.
  By Lemma~\ref{lem:coloring_space_compact}, the space $X = C^V$ of all possible assignments of colors to the vertices of $G$ is compact.
  By Lemma~\ref{lem:valid_colorings_closed}, for each finite subgraph $F \subset G$, the subset $X_F$ of valid $k$-colorings for $F$ is a closed set in $X$.
  By Lemma~\ref{lem:fip}, the collection of all such closed sets $\{X_F\}$ has the finite intersection property.

  A fundamental property of compact spaces is that any collection of closed subsets with the finite intersection property has a non-empty intersection. Therefore:
  $$ \bigcap_{F \subset G, F \text{ finite}} X_F \neq \emptyset $$
  Let $c$ be a color assignment in this intersection. By being in the intersection, $c \in X_F$ for every finite subgraph $F$ of $G$.

  We claim that $c$ is a valid $k$-coloring for the entire infinite graph $G$. To verify this, we must show that for any edge $\{u, v\}$ in $G$, $c(u) \neq c(v)$.
  Consider an arbitrary edge $\{u, v\} \in E(G)$. The subgraph $F_{uv}$ consisting of just this single edge and its two vertices is a finite subgraph of $G$.
  Since $c$ is in the total intersection, $c$ must be an element of $X_{F_{uv}}$. By definition, this means $c$ is a valid coloring for the subgraph $F_{uv}$, which requires that $c(u) \neq c(v)$.

  Since this holds for every edge in $G$, $c$ is a valid $k$-coloring of $G$. The existence of such a coloring proves that the chromatic number of $G$, $\chi(G)$, is at most $k$.
\end{proof}

