\chapter{Dilworth's Theorem}

This section contains a proof of Dilworth's Theorem.
See \url{https://en.wikipedia.org/wiki/Dilworth%27s_theorem} for more details.

\begin{definition}[Chain Partition]
    \label{def:Chain_Partition}
    \lean{PartialOrder.IsChainPartition}
    A chain partition of a poset $P$ is a collection of disjoint chains whose union is $P$.
\end{definition}

\begin{definition}[Full Antichains]
    \label{def:Full_Antichain}
    \lean{PartialOrder.fullAntichains}
    \uses{def:Chain_Partition}
    We call an antichain $A$ in a poset $P$ a \textit{full antichain} for a chain partition
    if it intersects every chain in that partition exactly once
    (equivalently, if it has size equal to the number of chains in the partition).
\end{definition}

\begin{definition}[Full Chain Maximizers]
    \label{def:Full_Chain_Maximizers}
    \lean{PartialOrder.fullChainMaximizers}
    \uses{def:Chain_Partition, def:Full_Antichain}
    Given a chain partition of a poset $P$, we choose a set $A$ of \textit{full chain maximizers} consisting of, from each chain $c_i$, a maximal element $a_i \in c_i$ that belongs to some full antichain.
\end{definition}

\begin{lemma}[Full Chain Maximizers is an Antichain]
    \label{lem:Full_Chain_Maximizers_is_an_Antichain}
    \lean{PartialOrder.isAntichain_fullChainMaximizers}
    \uses{def:Chain_Partition, def:Full_Antichain, def:Full_Chain_Maximizers}
    Let $P$ be a finite poset. Then the set of full chain maximizers constructed from any chain partition of $P$ comprise an antichain.
\end{lemma}

\begin{proof}
    Suppose, for the sake of contradiction, that $A$ is not an antichain. Then there exist $a_i, a_j \in A$ with $i \neq j$ such that $a_i < a_j$. By definition, $a_j$ is an element of some $k$-element antichain $A_j$. Since $A_j$ cannot have more than one element in any chain in $P'$, it must intersect every chain in the partition of $P'$ once. In particular, there exists an element $x \in C_i \cap A_j$.
    By the definition of $a_i$ as the maximal element of $C_i$ belonging to any $k$-antichain, and since $x \in C_i$, we must have $x \le a_i$.
    By transitivity, $x \le a_i < a_j$, which implies $x < a_j$.
    However, this is a contradiction, as both $x$ and $a_j$ are elements of the antichain $A_j$, and thus cannot be comparable. Therefore, $A = \{a_1, \dots, a_k\}$ must be an antichain.
\end{proof}

\begin{lemma}[Dilworth's Theorem, Inductive Step Case 1]
    \label{lem:Dilworth_inductive_step_case1}
    \lean{PartialOrder.dilworth_induction_greater_width}
    Let $P$ be a finite poset, and let $a$ be a maximal element of $P$. Let $P' = P \setminus \{a\}$. Assume the conclusion of Dilworth's theorem holds for all posets smaller than $P$. If the width of $P$ is one greater than the width of $P'$, i.e., $w(P) = w(P') + 1$, then $P$ can be partitioned into $w(P)$ chains.
\end{lemma}
\begin{proof}
    By the induction hypothesis, $P'$ can be partitioned into $w(P') = w(P)-1$ chains. The set $\{a\}$ forms a new chain, since $a$ is a maximal element. Thus, we can partition $P$ into $(w(P)-1)+1=w(P)$ chains.
\end{proof}

\begin{lemma}[Dilworth's Theorem, Inductive Step Case 2]
    \label{lem:Dilworth_inductive_step_case2}
    \lean{PartialOrder.dilworth_induction_equal_width}
    \uses{lem:Full_Chain_Maximizers_is_an_Antichain}
    Let $P$ be a finite poset, and let $a$ be a maximal element of $P$. Let $P' = P \setminus \{a\}$. Assume Dilworth's theorem holds for all posets smaller than $P$. If the width of $P$ is equal to the width of $P'$, i.e., $w(P) = w(P')$, then $P$ can be partitioned into $w(P)$ chains.
\end{lemma}
\begin{proof}
    Let $r = w(P) = w(P')$. By the induction hypothesis, $P'$ can be partitioned into $r$ chains $C_1, \dots, C_r$. Let $A = \{a_1, \dots, a_r\}$ be the antichain of maximal elements from these chains, as constructed in Lemma \ref{lem:Full_Chain_Maximizers_is_an_Antichain}.
    If $a$ were not comparable to any element in $A$, then $A \cup \{a\}$ would be an antichain of size $r+1$ in $P$, which contradicts $w(P)=r$.
    Therefore, since $a$ is maximal in $P$, it must be greater than some element $a_i \in A$.
    Let $K = \{a\} \cup \{x \in C_i : x \le a_i\}$. Since $a > a_i$ and all elements in $C_i$ up to $a_i$ form a chain, $K$ is a new chain in $P$.
    Consider the remaining poset $P \setminus K$. Any antichain in $P \setminus K$ can have at most $r-1$ elements. This is because any antichain of size $r$ in $P'$ must contain one element from each chain $C_j$, but we have removed from $C_i$ the element $a_i$ and all elements below it that could have been part of such an antichain.
    By the induction hypothesis, $P \setminus K$ can be partitioned into $r-1$ chains. Together with the chain $K$, we have a partition of $P$ into $(r-1)+1=r$ chains.
\end{proof}

\begin{theorem}[Dilworth's Theorem]
    \label{thm:Dilworths_Theorem}
    \lean{PartialOrder.dilworth}
    In any finite partially ordered set $P$, the minimum number of chains in a chain partition is equal to the maximum size of an antichain.
\end{theorem}

\begin{proof}
    \uses{lem:Full_Chain_Maximizers_is_an_Antichain, lem:Dilworth_inductive_step_case1, lem:Dilworth_inductive_step_case2}

    Let $w(P) = r$ be the size of the largest antichain in $P$. The proof proceeds by induction on the size of the poset, $|P|=n$. The base case, $n=1$, is trivial.
    Assume the theorem holds for all posets with size less than $n$. Let $a$ be a maximal element in $P$, and let $P' = P \setminus \{a\}$. Let $w(P') = k$ be the size of the largest antichain in $P'$. We know that $k \le r$ and either $k=r$ or $k=r-1$.

    Case 1: $k = r-1$. This case is handled by Lemma \ref{lem:Dilworth_inductive_step_case1}.

    Case 2: $k=r$. This case is handled by Lemma \ref{lem:Dilworth_inductive_step_case2}.

    Thus, in both cases, $P$ can be partitioned into $r$ chains.
\end{proof}

