\chapter{Finitely Many Primes Implies Dimension \texorpdfstring{$\leq 1$}{≤ 1} (Stacks 0ALV)}

This section contains a proof of the fact that a Noetherian ring with finitely many prime ideals has Krull dimension $\leq 1$.
See \url{https://stacks.math.columbia.edu/tag/0ALV} for more details.

\begin{lemma}[Finite spectrum quotient]
\label{lem:finite_spectrum_quotient}
\lean{PrimeSpectrum.finite_quotient}
\leanok
If $R$ has finitely many prime ideals, then $R/I$ has finitely many prime ideals for any ideal $I$.
\end{lemma}

\begin{proof}
\leanok
The map $\operatorname{Spec}(R/I) \to \operatorname{Spec}(R)$ induced by the quotient is injective, and an injection from a type into a finite type is finite.
\end{proof}

\begin{lemma}[Prime avoidance for maximal ideals]
\label{lem:prime_avoidance_maximal}
\lean{Ideal.exists_mem_not_mem_other_primes}
\leanok
If $\mathfrak{m}$ is a maximal ideal in a ring with finitely many primes, there exists $y \in \mathfrak{m}$ with $y \notin \mathfrak{q}$ for every prime $\mathfrak{q} \neq \mathfrak{m}$.
\end{lemma}

\begin{proof}
\leanok
Since $\mathfrak{m}$ is maximal, $\mathfrak{m} \not\subseteq \mathfrak{q}$ for every other prime $\mathfrak{q}$ (if $\mathfrak{m} \subseteq \mathfrak{q}$ then $\mathfrak{m} = \mathfrak{q}$ by maximality). By prime avoidance applied to the finite collection of other primes, $\mathfrak{m} \not\subseteq \bigcup \mathfrak{q}$, so there exists such $y$.
\end{proof}

\begin{lemma}[Domain case: nonzero primes are maximal]
\label{lem:nonzero_prime_maximal_domain}
\lean{Ideal.IsPrime.isMaximal_of_finite_primeSpectrum}
\leanok
In a Noetherian domain with finitely many primes, every nonzero prime ideal is maximal.
\end{lemma}

\begin{proof}
\leanok
\uses{lem:prime_avoidance_maximal}
Suppose $\mathfrak{p}$ is a nonzero prime that is not maximal. Pick a maximal ideal $\mathfrak{m} \supseteq \mathfrak{p}$. Since $R$ is a domain, $0$ is prime, giving the chain $0 \subsetneq \mathfrak{p} \subseteq \mathfrak{m}$, so $\operatorname{height}(\mathfrak{m}) \geq 2$.

By Lemma~\ref{lem:prime_avoidance_maximal}, pick $y \in \mathfrak{m}$ not in any other prime. Then $\mathfrak{m}$ is the unique minimal prime over $(y)$. By Krull's principal ideal theorem, $\operatorname{height}(\mathfrak{m}) \leq 1$, a contradiction.
\end{proof}

\begin{lemma}[Domain dimension bound]
\label{lem:domain_dim_bound}
\lean{Ring.krullDimLE_one_of_isDomain_of_finite_primeSpectrum}
\leanok
A Noetherian domain with finitely many primes has Krull dimension $\leq 1$.
\end{lemma}

\begin{proof}
\leanok
\uses{lem:nonzero_prime_maximal_domain}
Follows immediately from Lemma~\ref{lem:nonzero_prime_maximal_domain}: every nonzero prime is maximal, so $\operatorname{KrullDimLE}\ 1$ holds by \texttt{Ring.KrullDimLE.mk₁'}.
\end{proof}

\begin{theorem}[Finitely Many Primes $\Rightarrow$ Dimension $\leq 1$ (Stacks 0ALV)]
\label{thm:finitely_many_primes_dim_one}
\lean{Ring.krullDimLE_one_of_finite_primeSpectrum}
\leanok
A Noetherian ring with finitely many prime ideals has Krull dimension $\leq 1$.
\end{theorem}

\begin{proof}
\leanok
\uses{lem:finite_spectrum_quotient, lem:domain_dim_bound}
By \texttt{Ring.KrullDimLE.mk₁}, it suffices to show every prime ideal is either minimal or maximal. Let $I$ be a prime that is not minimal. Pick a minimal prime $\mathfrak{q} \leq I$ with $\mathfrak{q} \neq I$. The quotient $R/\mathfrak{q}$ is a Noetherian domain with finitely many primes (Lemma~\ref{lem:finite_spectrum_quotient}). By Lemma~\ref{lem:domain_dim_bound}, $R/\mathfrak{q}$ has dimension $\leq 1$, so the image of $I$ in $R/\mathfrak{q}$ --- being a nonzero prime --- is maximal. Pulling back along $R \to R/\mathfrak{q}$, $I$ is maximal in $R$.
\end{proof}

\chapter{Fitting's theorem}

This section contains a proof of Fitting's theorem.
See \url{https://en.wikipedia.org/wiki/Fitting's_theorem} for more details.

\begin{definition}
  \label{def:commFin}
  \lean{commFin}
  Suppose $G$ is a group. We define $[H_0, \dots, H_n]$ for subgroups $H_0, \dots, H_n$ of $G$
  inductively by $[H_0] = H_0$ and for $n \geq 1$,
  \begin{displaymath}
    [H_0, \dots, H_n] = [[H_0, \dots, H_{n-1}], H_n].
  \end{displaymath}
  Here $[H, K]$ denotes the commutator subgroup, which is generated by
  $\{[h, k] | h \in H, k \in K\}$, where $[h, k] = hkh^{-1}k^{-1}$.
\end{definition}

\begin{lemma}
  \label{lem:commFin_normal}
  \lean{commFin_normal}
  Let $H_0, \dots, H_n$ be normal subgroups of $G$. Then $[H_0, \dots, H_n]$ is a normal subgroup of $G$.
\end{lemma}
\begin{proof}
  By induction on $n$. The inductive step uses the fact that if $H$, $K$ are normal subgroups of
  $G$, then $[H, K]$ is normal too.
\end{proof}

\begin{lemma}
  \label{lem:commFin_le}
  \lean{commFin_le}
  Let $H_0, \dots, H_n$ be normal subgroups of $G$. Let $I_0 < \dots < I_k \leq n$. Then $[H_0, \dots, H_n] \subseteq [H_{I_0}, \dots, H_{I_k}]$.
\end{lemma}
\begin{proof}
  By induction on $n$. $n=0$ is trivial. Suppose $n \geq 1$ and the lemma holds for $n - 1$.
  Note that $[H, K] \subseteq H$ if $H$ is a normal subgroup of $G$.
  If $i_k < n$, then
  \begin{displaymath}
    [H_0, \dots, H_n] = [[H_0, \dots, H_{n-1}], H_n] \subseteq [H_0, \dots, H_{n-1}] \subseteq [H_{I_0}, \dots, H_{I_k}].
  \end{displaymath}
  If $i_k = n$, then
  \begin{displaymath}
    [H_0, \dots, H_n] = [[H_0, \dots, H_{n-1}], H_{I_k}] \subseteq[[H_{I_0}, \dots, H_{I_{k-1}}], H_{I_k}] = [H_{I_0}, \dots, H_{I_k}].
  \end{displaymath}
\end{proof}

\begin{lemma}
  \label{lem:mul_left_distrib}
  \lean{mul_left_distrib}
  Let $H_0, \dots, H_n, L$ be normal subgroups of $G$. Then
  \begin{displaymath}
    [H_0 \dots H_n, L] = [H_0, L] \dots [H_n, L].
  \end{displaymath}
\end{lemma}
\begin{proof}
  By induction on $n$. We only need to prove the identities for $n=1$.
  Let $h_0 \in H_0$, $h_1 \in H_1$, $x \in L$. Then
  \begin{displaymath}
    [h_0h_1, x] = h_0h_1xh_1^{-1}h_0^{-1}x^{-1} = [h_0, h_1xh_1^{-1}][h_1, x] \in [H_0, L] [H_1, L].
  \end{displaymath}
  So $[H_0H_1, L] \subseteq [H_0, L][H_1, L]$. The other direction of the inclusion is trivial.
\end{proof}

\begin{theorem}
  \label{thm:fitting}
  \lean{fitting}
  \uses{def:commFin}
  \uses{lem:commFin_normal}
  \uses{lem:commFin_le}
  \uses{lem:mul_left_distrib}
  If $M$ and $N$ are nilpotent normal subgroups of a group $G$, then their product $MN$ is also a nilpotent normal subgroup of $G$; if, moreover, $M$ is nilpotent of class $m$ and $N$ is nilpotent of class $N$, then $MN$ is nilpotent of class at most $m + n$.
\end{theorem}
\begin{proof}
  For any group $K$, let $\gamma_i(K)$, $i \geq 0$ be the lower central series of $K$. Note that, using the notation above, $\gamma_i(K) = [K, \dots, K]$ with $i+1$ many $K$'s.
  We claim that $\gamma_i(MN)$ is a product of terms of the form $[L_0, \dots, L_i]$ where each $L_j$ is either $M$ or $N$.
  This is proved by induction on $i$. When $i=0$, $\gamma_0(MN) = MN$ is a product of two terms $M$ and $N$, so the claim is satisfied.
  Suppose the claim holds for $i$. Then
  \begin{displaymath}
    \gamma_{i+1}(MN) = [\gamma_i(MN), MN] = [\gamma_i(MN), M] [\gamma_i(MN), N],
  \end{displaymath}
  the last equality from Lemma~\ref{lem:mul_left_distrib}. So by induction hypothesis, the claim holds for $i+1$.
  If the nilpotency class of $M$ is $m$ and the nilpotency class of $N$ is $n$, then $\gamma_m(M)=\gamma_n(N)=\{e\}$.
  By our claim, $\gamma_{m+n}(MN)$ is a product of terms of the form $[L_0, \dots, L_{m+n}]$ where each $L_j$ is either $M$ or $N$.
  So at least $m+1$ of $L_j$ are equal to $M$ or at least $n+1$ of $L_j$ are equal to $N$.
  Therefore, by Lemma~\ref{lem:commFin_le}, either
  \begin{displaymath}
    [L_0, \dots, L_{m+n}] \subseteq [M, \dots, M] = \gamma_m(M) = \{e\}
  \end{displaymath}
  with $m+1$ $M$'s in the second term, or
  \begin{displaymath}
    [L_0, \dots, L_{m+n}] \subseteq [N, \dots, N] = \gamma_m(N) = \{e\}
  \end{displaymath}
  with $n+1$ $N$'s in the second term.
  Either way, $[L_0, \dots, L_{m+n}] = \{e\}$ and so $\gamma_{m+n}(MN)=\{e\}$. This proves that $MN$ is nilpotent of class at most $m+n$.
\end{proof}

