\chapter{Froda's Theorem}

This section contains a proof of Froda's Theorem.
See \url{https://en.wikipedia.org/wiki/Discontinuities_of_monotone_functions} ("proof 2") for more details.

\begin{lemma}[Monotone functions separate values at discontinuities]
    \label{lem:Jump_of_Monotone}
    \lean{jump_discontinuities_of_monotone}
    For a monotone function that is discontinuous at a point $x$,
    the supremum of the values of the function over inputs $y < x$
    is strictly less than the infimum of the values of the function over inputs $z > x$.
\end{lemma}

\begin{proof}
    Suppose the supremum were greater than or equal to this infimum.
    We argue that the function would then be continuous at $x$.
    We let $\epsilon > 0$ be given, and we show there is a $\delta > 0$ such that $f$ is within $\epsilon$ of $f(x)$ on $(x - \delta, x + \delta)$.
    Note that there is a $y < x$ such that $f(y) + \epsilon/2$ is greater than the supremum of the function values to the left of $x$.
    Similarly, there is a $z > x$ such that $f(z) - \epsilon/2$ less than the infimum of the function values to the right of $x$.
    Using our assumption, these facts give us $f(z) - f(y) < \epsilon$.
    We may therefore choose $\delta = \min(x - y, z - x)$.
    This guarantees that for any $w$ such that $|w - x| < \delta$,
    we have $f(w)$ is within $\epsilon$ of both $f(y)$ and $f(z)$,
    and therefore within $\epsilon$ of $f(x)$.
\end{proof}

\begin{lemma}[Upper and Lower Limits of different values of a Monotone Function]
    \label{lem:upper_lower}
    \lean{Monotone.sInf_Ioi_le_sSup_Iio}
    For a monotone function $f$ and inputs $x < y$,
    the infimum of the values of the function over inputs $z > x$
    is less than or equal to the supremum of the values of the function over inputs $z < y$.
\end{lemma}

\begin{proof}
    Consider $z$ such that $x < z < y$.
    We have that $z$ is included in both the set of values to the right of $x$
    and the set of values to the left of $y$.
    Therefore, the infimum of the function values to the right of $x$
    is less than or equal to $f(z)$,
    which is less than or equal to the supremum of the function values to the left of $y$.
\end{proof}

\begin{theorem}[Froda's Theorem]
    \label{thm:froda}
    \lean{Real.countable_not_continuousAt}
    \uses{lem:Jump_of_Monotone}
    \uses{lem:upper_lower}
    Let $f: \mathbb{R} \to \mathbb{R}$ be a monotone function.
    The set of discontinuities of $f$ is at most countable.
\end{theorem}

\begin{proof}
    Let $D$ be the set of discontinuities of $f$ in $[a, b]$.
    For any $x \in D$,
    we have that the supremum of the values of the function over inputs $y < x$, which we can denote $f(x^-)$, is strictly less than the infimum of the values of the function over inputs $z > x$ which we can denote $f(x^+)$.
    There is therefore a rational number $q_x$ such that:
    \[f(x^-) < q_x < f(x^+)\]
    And since the function is monotone, we have that for any $y < x$ discontinuities,
    $q_y \leq f(y^+) \leq f(x^-) < q_x$.
    Therefore, we can use the axiom of choice to construct the mapping $x \mapsto q_x$, which is injective from the set of discontinuities $D$
    to the set of rational numbers $\mathbb{Q}$, and $D$ is therefore countable
\end{proof}

\chapter{The Gauss-Lucas Theorem}

This section contains a proof of the Gauss-Lucas Theorem.
See \url{https://en.wikipedia.org/wiki/Gauss%E2%80%93Lucas_theorem} for more details.

\begin{lemma}[Logarithmic Derivative of a Complex Polynomial]
  \label{lem:logDeriv_Polynomial}
  \lean{logDeriv_Polynomial}
  \leanok
  The logarithmic derivative of a complex polynomial
  is the sum of the inverses of its factors.
\end{lemma}

\begin{proof}
Let the polynomial be $P(z) = c \prod_{i=1}^{n} (z - r_i)$, where $r_i$ are the roots of the polynomial.
Taking the natural logarithm of both sides gives:
$$ \ln P(z) = \ln c + \sum_{i=1}^{n} \ln(z - r_i) $$
The logarithmic derivative is the derivative of $\ln P(z)$, which is $\frac{P'(z)}{P(z)}$. Differentiating the right-hand side with respect to $z$ yields:
$$ \frac{P'(z)}{P(z)} = \sum_{i=1}^{n} \frac{1}{z - r_i} $$
This proves that the logarithmic derivative is the sum of the inverses of the terms $(z - r_i)$.
\end{proof}

\begin{lemma}[Sum of inverses of polynomial factors on a root]
  \label{lem:sum_inv_sub_roots_eq_zero}
  \lean{sum_inv_sub_roots_eq_zero}
  \leanok
  If $z$ is a root of the derivative of a polynomial $p$, but not a root of $p$ itself,
  then the sum of the inverses of the differences between x and each root of $p$ is zero.
\end{lemma}

\begin{proof}
  \uses{lem:logDeriv_Polynomial}
  From Lemma~\ref{lem:logDeriv_Polynomial}, we have the identity $\frac{P'(z)}{P(z)} = \sum_{i=1}^{n} \frac{1}{z - r_i}$.
  The lemma states that $z$ is a root of the derivative, so $P'(z) = 0$. It also states that $z$ is not a root of $P$ itself, which means $P(z) \neq 0$.
  Substituting these conditions into the identity gives:
  $$ \frac{0}{P(z)} = \sum_{i=1}^{n} \frac{1}{z - r_i} $$
  Therefore, we must have:
  $$ \sum_{i=1}^{n} \frac{1}{z - r_i} = 0 $$
\end{proof}

\begin{lemma}[The weighting of roots has non-zero total weight]
  \label{lem:sum_norm_sq_sub_inv_nonzero}
  \lean{sum_norm_sq_sub_inv_nonzero}
  \leanok
  The weighting which assigns to each root $a$ the value
  $(1 / ‖z - a‖^2)$ has a non-zero total weight.
\end{lemma}

\begin{proof}
  The total weight $W$ is the sum of the individual weights for each root $r_i$ of a polynomial $P$:
  $$ W = \sum_{i=1}^{n} \frac{1}{|z - r_i|^2} $$
  This weighting is used in the context where $z$ is a root of $P'$ but not a root of $P$. Therefore, $z \neq r_i$ for all $i=1, \dots, n$.
  The term $|z - r_i|$ represents the Euclidean distance between $z$ and $r_i$. Since $z \neq r_i$, this distance is strictly greater than zero.
  $$ |z - r_i| > 0 $$
  The square of any non-zero real number is strictly positive, so $|z - r_i|^2 > 0$.
  Each term in the sum, $\frac{1}{|z - r_i|^2}$, is the reciprocal of a strictly positive number, and is therefore strictly positive itself.
  The total weight $W$ is a finite sum of strictly positive real numbers. Such a sum must be strictly positive and therefore cannot be zero.
\end{proof}

\begin{lemma}[The derivative root is a weighted average of roots]
  \label{lem:deriv_root_as_weighted_average_of_roots}
  \lean{deriv_root_as_weighted_average_of_roots}
  \leanok
  If z is a root of the derivative of a polynomial p, but not a root of p itself,
  then it can be expressed as a weighted average of the roots of p.
\end{lemma}

\begin{proof}
  \uses{lem:sum_inv_sub_roots_eq_zero, lem:sum_norm_sq_sub_inv_nonzero}
  Starting from the result of Lemma~\ref{lem:sum_inv_sub_roots_eq_zero}:
  $$ \sum_{i=1}^{n} \frac{1}{z - r_i} = 0 $$
  We can rewrite each term in the sum using its complex conjugate:
  $$ \frac{1}{z - r_i} = \frac{\overline{z - r_i}}{|z - r_i|^2} = \frac{\bar{z} - \bar{r_i}}{|z - r_i|^2} $$
  Substituting this back into the sum gives:
  $$ \sum_{i=1}^{n} \frac{\bar{z} - \bar{r_i}}{|z - r_i|^2} = 0 $$
  We can split the sum into two parts:
  $$ \sum_{i=1}^{n} \frac{\bar{z}}{|z - r_i|^2} - \sum_{i=1}^{n} \frac{\bar{r_i}}{|z - r_i|^2} = 0 $$
  Rearranging the equation to solve for $\bar{z}$:
  $$ \bar{z} \sum_{i=1}^{n} \frac{1}{|z - r_i|^2} = \sum_{i=1}^{n} \frac{\bar{r_i}}{|z - r_i|^2} $$
  Taking the complex conjugate of the entire equation (and noting that $|z - r_i|^2$ is a real number) yields:
  $$ z \sum_{i=1}^{n} \frac{1}{|z - r_i|^2} = \sum_{i=1}^{n} \frac{r_i}{|z - r_i|^2} $$
  Let us define positive real weights $w_i = \frac{1}{|z - r_i|^2}$. The equation becomes $z \sum_{i=1}^{n} w_i = \sum_{i=1}^{n} w_i r_i$.
  Solving for $z$, we get:
  $$ z = \frac{\sum_{i=1}^{n} w_i r_i}{\sum_{i=1}^{n} w_i} $$
  This shows that $z$ is a weighted average of the polynomial's roots $r_i$ with positive real coefficients.
\end{proof}

\begin{theorem}[Gauss-Lucas]
  \label{thm:gauss_lucas}
  \lean{Complex.mem_convexHull_roots_of_mem_derivative_roots}
  \leanok
  If P is a polynomial with complex coefficients, all roots of P' belong to the convex hull of the set of zeros of P.
\end{theorem}

\begin{proof}
  \uses{lem:deriv_root_as_weighted_average_of_roots, lem:sum_norm_sq_sub_inv_nonzero}
  Let $z$ be a root of the derivative, $P'(z)=0$. We want to show that $z$ lies in the convex hull of the set of roots of $P$, denoted $R = \{r_1, r_2, \dots, r_n\}$.

  We consider two cases for the root $z$:

  \begin{itemize}
      \item \textbf{Case 1: $z$ is also a root of $P$.}
      If $z$ is one of the roots of $P$, then $z \in R$. A point that belongs to a set of points is, by definition, contained within the convex hull of that set.

      \item \textbf{Case 2: $z$ is not a root of $P$.}
      In this case, the conditions for Lemma~\ref{lem:deriv_root_as_weighted_average_of_roots} are met. We can express $z$ as a weighted average:
      $$ z = \frac{\sum_{i=1}^{n} w_i r_i}{\sum_{i=1}^{n} w_i} $$
      where the weights $w_i = 1/|z - r_i|^2$ are positive real numbers.
      If we let $\lambda_i = \frac{w_i}{\sum_{j=1}^{n} w_j}$, then we can write $z = \sum_{i=1}^{n} \lambda_i r_i$.
      The coefficients $\lambda_i$ are positive and they sum to 1 ($\sum \lambda_i = 1$). This is the definition of a convex combination of the points $r_i$. Any point that is a convex combination of a set of points lies within their convex hull.
  \end{itemize}
  In both possible cases, any root of $P'$ must lie within the convex hull of the roots of $P$.
\end{proof}

