\chapter{Height One Primes and UFDs (Stacks 0AFT)}

This section contains a proof of the fact that a Noetherian domain $R$ is a UFD if and only if every height-$1$ prime ideal of $R$ is principal.
See \url{https://stacks.math.columbia.edu/tag/0AFT} for more details.

\begin{lemma}[Height-0 primes are $\bot$ in a domain]
\label{lem:eq_bot_of_primeHeight_zero}
\lean{Ideal.eq_bot_of_primeHeight_eq_zero}
\leanok
In an integral domain, a prime ideal of height $0$ is the zero ideal.
\end{lemma}

\begin{proof}
\leanok
In a domain the only minimal prime is $\bot$, and height $0$ means the ideal is a minimal prime.
\end{proof}

\begin{lemma}[Height-1 primes are nonzero in a domain]
\label{lem:ne_bot_of_primeHeight_one}
\lean{Ideal.ne_bot_of_primeHeight_eq_one}
\leanok
In an integral domain, a prime ideal of height $1$ is nonzero.
\end{lemma}

\begin{proof}
\leanok
\uses{lem:eq_bot_of_primeHeight_zero}
If $\mathfrak{p} = \bot$ then $\operatorname{height}(\mathfrak{p}) = 0 \neq 1$.
\end{proof}

\begin{lemma}[Unique prime of height 1 above a nonzero prime]
\label{lem:eq_of_le_primeHeight_one}
\lean{Ideal.eq_of_isPrime_of_le_of_primeHeight_eq_one}
\leanok
In a domain, if $\mathfrak{p}$ is a nonzero prime ideal contained in a prime $\mathfrak{q}$ of height $1$, then $\mathfrak{p} = \mathfrak{q}$.
\end{lemma}

\begin{proof}
\leanok
\uses{lem:eq_bot_of_primeHeight_zero}
If $\mathfrak{p} \subsetneq \mathfrak{q}$ then $\operatorname{height}(\mathfrak{p}) + 1 \leq \operatorname{height}(\mathfrak{q}) = 1$, forcing $\operatorname{height}(\mathfrak{p}) = 0$, hence $\mathfrak{p} = \bot$ by Lemma~\ref{lem:eq_bot_of_primeHeight_zero}, contradicting $\mathfrak{p} \neq \bot$.
\end{proof}

\begin{lemma}[Forward: height-1 primes are principal in a UFD]
\label{lem:height_one_principal_ufd}
\lean{Ideal.isPrincipal_of_primeHeight_eq_one_of_ufd}
\leanok
In a UFD, every height-$1$ prime ideal is principal.
\end{lemma}

\begin{proof}
\leanok
\uses{lem:ne_bot_of_primeHeight_one, lem:eq_of_le_primeHeight_one}
Since $\mathfrak{p} \neq \bot$ (Lemma~\ref{lem:ne_bot_of_primeHeight_one}), there exists a prime element $x \in \mathfrak{p}$. Then $\operatorname{span}\{x\}$ is a nonzero prime ideal contained in $\mathfrak{p}$. By Lemma~\ref{lem:eq_of_le_primeHeight_one}, $\operatorname{span}\{x\} = \mathfrak{p}$, so $\mathfrak{p}$ is principal.
\end{proof}

\begin{lemma}[Reverse: irreducibles are prime when height-1 primes are principal]
\label{lem:irreducible_is_prime}
\lean{Prime.of_irreducible_of_height_one_principal}
\leanok
In a Noetherian domain where every height-$1$ prime is principal, every irreducible element is prime.
\end{lemma}

\begin{proof}
\leanok
For irreducible $x$, take a minimal prime $\mathfrak{q}$ over $(x)$. By Krull's principal ideal theorem, $\operatorname{height}(\mathfrak{q}) \leq 1$. Since $x \neq 0$, $\mathfrak{q} \neq \bot$, so $\operatorname{height}(\mathfrak{q}) = 1$. By hypothesis $\mathfrak{q} = (y)$. Then $y \mid x$, and irreducibility gives $(x) = (y) = \mathfrak{q}$, a prime ideal, so $x$ is prime.
\end{proof}

\begin{theorem}[UFD iff Height-1 Primes Principal (Stacks 0AFT)]
\label{thm:ufd_iff_height_one_principal}
\lean{Ideal.ufd_iff_height_one_primes_principal}
\leanok
A Noetherian domain $R$ is a UFD if and only if every height-$1$ prime ideal of $R$ is principal.
\end{theorem}

\begin{proof}
\leanok
\uses{lem:height_one_principal_ufd, lem:irreducible_is_prime}
\emph{Forward}: Lemma~\ref{lem:height_one_principal_ufd}.

\emph{Reverse}: By Lemma~\ref{lem:irreducible_is_prime}, every irreducible is prime. Since $R$ is Noetherian, it is a \texttt{WfDvdMonoid}, so every nonzero non-unit has an irreducible factorization. Since all irreducibles are prime, this gives a UFD.
\end{proof}

\chapter{Hinge Theorem}

This section contains a proof of the Hinge Theorem.
See \url{https://en.wikipedia.org/wiki/Hinge_theorem} for more details.

\begin{theorem}[Hinge Theorem with Law of Cosines, Forward]
    \label{thm:hinge_forward}
    \lean{hinge_forward}
    Let $a, b, c_1, c_2$ be positive reals and let $C_1, C_2$ be angles such that $0 \leq C_1, C_2 \leq \pi$.
    If $C_1, C_2$ obey the law of cosines for triangles with sides $a, b, c_1$ and $a, b, c_2$ respectively, and if $C_1 > C_2$, then $c_1 > c_2$.
\end{theorem}

\begin{proof}
    Adding the two equations given by the law of cosines and rearranging, we have:
    \[ c_1^2 - c_2^2 = -2ab(\cos(C_1) - cos(C_2)) \]
    The cosine function is strictly decreasing on the interval $[0, \pi]$. Thus, this value is positive.
    Using the difference of squares factorization, we have:
    \[ (c_1 - c_2)(c_1 + c_2) > 0 \]
    Since $c_1 + c_2 > 0$, we conclude that $c_1 - c_2 > 0$, or $c_1 > c_2$
\end{proof}

\begin{theorem}[Hinge Theorem with Law of Cosines, Backward]
    \label{thm:hinge_backward}
    \lean{hinge_backward}
    Let $a, b, c_1, c_2$ be positive reals and let $C_1, C_2$ be angles such that $0 \leq C_1, C_2 \leq \pi$.
    If $C_1, C_2$ obey the law of cosines for triangles with sides $a, b, c_1$ and $a, b, c_2$ respectively, and if $c_1 > c_2$, then $C_1 > C_2$.
\end{theorem}

\begin{proof}
    Adding the two equations given by the law of cosines and rearranging, we have:
    \[ c_1^2 - c_2^2 = -2ab(\cos(C_1) - cos(C_2)) \]
    Since $c_1 > c_2$, the left side is positive.
    Using the difference of squares factorization, we have:
    \[ (c_1 - c_2)(c_1 + c_2) > 0 \]
    Since $c_1 + c_2 > 0$, we conclude that $-2ab(\cos(C_1) - cos(C_2)) > 0$.
    Dividing both sides by the positive number $-2ab$, we have $\cos(C_1) - \cos(C_2) < 0$, or $\cos(C_1) < \cos(C_2)$.
    The cosine function is strictly decreasing on the interval $[0, \pi]$. Thus, we conclude that $C_1 > C_2$.
\end{proof}

\begin{theorem}[Hinge Theorem with Law of Cosines]
    \label{thm:hinge}
    \uses{thm:hinge_forward, thm:hinge_backward}
    \lean{hinge_iff}
    Let $a, b, c_1, c_2$ be positive reals and let $C_1, C_2$ be angles such that $0 \leq C_1, C_2 \leq \pi$.
    If $C_1, C_2$ obey the law of cosines for triangles with sides $a, b, c_1$ and $a, b, c_2$ respectively, then $c_1 > c_2$ if and only if $C_1 > C_2$.
\end{theorem}

\begin{proof}
    This follows directly from Theorems \ref{thm:hinge_forward} and \ref{thm:hinge_backward}.
\end{proof}

\begin{theorem}[Hinge Theorem]
    \label{thm:hinge_geometry}
    \uses{thm:hinge}
    \lean{hinge_iff_geometric}
    Let $A, B_1, C_1, B_2, C_2$ be points in Euclidean space such that the distances $AB_1$, $AC_1$, $AB_2$, and $AC_2$ are all nonzero.
    Then the distance $B_1C_1$ is greater than the distance $B_2C_2$ if and only if the angle $B_1AC_1$ is greater than the angle $B_2AC_2$.
\end{theorem}

\begin{proof}
    Let $a = AB_1 = AB_2$, $b = AC_1 = AC_2$, $c_1 = B_1C_1$, and $c_2 = B_2C_2$.
    By the law of cosines, we have:
    \[ c_1^2 = a^2 + b^2 - 2ab\cos(\angle B_1AC_1) \]
    \[ c_2^2 = a^2 + b^2 - 2ab\cos(\angle B_2AC_2) \]
    Thus, the conditions of Theorem \ref{thm:hinge} are satisfied, and the result follows.
\end{proof}

