\chapter{Hurwitz's Approximation Theorem}

This section contains a proof of Hurwitz's Approximation Theorem.
See \url{https://en.wikipedia.org/wiki/Hurwitz%27s_theorem_(number_theory)} for more details.


\begin{lemma}[CF of irrational does not terminate]
    \label{lem:hurwitz_cf_not_term}
    \lean{cf_irrational_not_terminatedAt}
    If $\xi$ is irrational, then the generalized continued fraction for $\xi$ does not terminate at any index $n$.
\end{lemma}
\begin{proof}
    If the generalized continued fraction for $\xi$ terminated at $n$, then it would terminate altogether, so we would get a rational $q$ with $\xi = q$, contradicting irrationality.
\end{proof}

\begin{lemma}[CF denominator is positive]
    \label{lem:hurwitz_cf_den_pos}
    \lean{cf_den_pos}
    \uses{lem:hurwitz_cf_not_term}
    If $\xi$ is irrational, then the $n$-th denominator of the generalized continued fraction for $\xi$ is positive.
\end{lemma}
\begin{proof}
    Since $\xi$ is irrational, the CF does not terminate at $n-1$ by Lemma~\ref{lem:hurwitz_cf_not_term}. We have that the $n$th denominator is lower bounded by a Fibonacci number $\mathrm{fib}(n+1) \leq B_n$, and Fibonacci numbers are positive for $n \geq 1$.
\end{proof}

\begin{lemma}[CF denominator recurrence inequality]
    \label{lem:hurwitz_cf_den_rec}
    \lean{cf_den_recurrence_ineq}
    \uses{lem:hurwitz_cf_not_term, lem:hurwitz_cf_den_pos}
    If $\xi$ is irrational and $B_n$ denotes the $n$-th denominator of the generalized continued fraction for $\xi$, then $B_n + B_{n+1} \leq B_{n+2}$ for all $n$.
\end{lemma}
\begin{proof}
    The recurrence $B_{n+2} = a_{n+2} \cdot B_{n+1} + B_n$ holds for continued fractions, where $a_{n+2} \geq 1$ since the partial denominators of the generalized continued fraction for $\xi$ are at least $1$. Thus $B_{n+2} \geq B_{n+1} + B_n$.
\end{proof}

\begin{lemma}[CF denominator skip inequality]
    \label{lem:hurwitz_cf_den_lt_skip}
    \lean{cf_den_lt_skip}
    \uses{lem:hurwitz_cf_den_rec, lem:hurwitz_cf_den_pos}
    If $\xi$ is irrational, then the $n$-th denominator of the generalized continued fraction for $\xi$ is strictly less than the $(n+2)$-th denominator, for all $n$.
\end{lemma}
\begin{proof}
    From the recurrence inequality (Lemma~\ref{lem:hurwitz_cf_den_rec}), $B_n + B_{n+1} \leq B_{n+2}$, and since $B_{n+1} > 0$ by Lemma~\ref{lem:hurwitz_cf_den_pos}, we have $B_n < B_{n+2}$.
\end{proof}

\begin{lemma}[Convergent denominator equals CF denominator]
    \label{lem:hurwitz_conv_den_eq}
    \lean{convergent_den_eq_cf_den}
    \uses{lem:hurwitz_cf_not_term, lem:hurwitz_cf_den_pos}
    If $\xi$ is irrational, then for all $n$, the denominator of the $n$-th convergent equals the $n$-th denominator of the generalized continued fraction for $\xi$ (as real numbers).
\end{lemma}
\begin{proof}
    The convergents are integers-valued fractions $A_n / B_n$. The determinant formula $A_n B_{n+1} - B_n A_{n+1} = (-1)^{n+1}$ shows $\gcd(A_n, B_n) = 1$, so the rational $A_n/B_n$ is already in lowest terms and its denominator is exactly $B_n$.
\end{proof}

\begin{lemma}[Consecutive convergents bracket $\xi$]
    \label{lem:hurwitz_bracket}
    \lean{consecutive_convs_bracket}
    \uses{lem:hurwitz_cf_not_term, lem:hurwitz_cf_den_pos}
    If $\xi$ is irrational, then for all $n$, the product $(\xi - \xi.\mathrm{convergent}(n)) \cdot (\xi - \xi.\mathrm{convergent}(n+1)) < 0$, i.e., consecutive convergents lie on opposite sides of $\xi$.
\end{lemma}
\begin{proof}
    The sign of $\xi - c_n$ is $(-1)^n$ up to a positive factor (involving the fractional part inverse and the CF denominators). Hence consecutive errors alternate in sign, giving a negative product.
\end{proof}

\begin{lemma}[Consecutive convergents difference]
    \label{lem:hurwitz_conv_diff}
    \lean{consecutive_convs_diff}
    \uses{lem:hurwitz_cf_not_term, lem:hurwitz_cf_den_pos}
    If $\xi$ is irrational, then $|{\xi.\mathrm{convergent}(n)} - {\xi.\mathrm{convergent}(n+1)}| = 1 / (B_n \cdot B_{n+1})$ where $B_k$ is the $k$-th denominator of the generalized continued fraction for $\xi$.
\end{lemma}
\begin{proof}
    The determinant formula gives $|A_n B_{n+1} - B_n A_{n+1}| = 1$. Writing the convergents as $A_n/B_n$ and $A_{n+1}/B_{n+1}$, their difference has absolute value $1/(B_n B_{n+1})$.
\end{proof}

\begin{lemma}[Triangle identity for convergents]
    \label{lem:hurwitz_triangle}
    \lean{triangle_identity}
    \uses{lem:hurwitz_bracket, lem:hurwitz_conv_diff}
    If $\xi$ is irrational, then $|\xi - \xi.\mathrm{convergent}(n)| + |\xi - \xi.\mathrm{convergent}(n+1)| = 1/(B_n \cdot B_{n+1})$.
\end{lemma}
\begin{proof}
    Since consecutive convergents bracket $\xi$ (Lemma~\ref{lem:hurwitz_bracket}), the errors $a = \xi - c_n$ and $b = \xi - c_{n+1}$ have opposite signs, so $|a| + |b| = |a - b| = |c_n - c_{n+1}|$. By Lemma~\ref{lem:hurwitz_conv_diff} this equals $1/(B_n B_{n+1})$.
\end{proof}

\begin{lemma}[Quadratic inequality implies bound by golden ratio]
    \label{lem:hurwitz_quad_golden}
    \lean{quadratic_le_golden}
    If $r > 0$ and $r + 1/r \leq \sqrt{5}$, then $r \leq \varphi$ where $\varphi = (1+\sqrt{5})/2$ is the golden ratio.
\end{lemma}
\begin{proof}
    Multiplying $r + 1/r \leq \sqrt{5}$ by $r$ gives $r^2 - \sqrt{5} r + 1 \leq 0$. The roots of $t^2 - \sqrt{5} t + 1 = 0$ are $\varphi$ and $1/\varphi$, so this inequality holds iff $1/\varphi \leq r \leq \varphi$. In particular $r \leq \varphi$. This is confirmed by arithmetic using $(\sqrt{5})^2 = 5$.
\end{proof}

\begin{lemma}[Golden ratio squeeze]
    \label{lem:hurwitz_ratio_squeeze}
    \lean{ratio_squeeze}
    If $r \leq \varphi$ and $r > 0$, then $\varphi \leq 1 + 1/r$.
\end{lemma}
\begin{proof}
    Since $\varphi^2 = \varphi + 1$, we have $\varphi = 1 + 1/\varphi$. Because $r \leq \varphi$, we get $1/r \geq 1/\varphi$, so $1 + 1/r \geq 1 + 1/\varphi = \varphi$.
\end{proof}


\begin{lemma}[Golden ratio cannot be ratio of positive integers]
    \label{lem:hurwitz_golden_not_ratio}
    \lean{golden_ratio_not_int_ratio}
    There are no positive natural numbers $a, b$ with $b/a = \varphi$.
\end{lemma}
\begin{proof}
    If $b/a = \varphi$ with $a, b$ positive integers, then $\varphi = b/a$ is rational (a ratio of integers), contradicting the irrationality of $\varphi$.
\end{proof}

\begin{lemma}[Ratio bound when two consecutive convergents fail Hurwitz]
    \label{lem:hurwitz_ratio_bound}
    \lean{ratio_bound_of_not_hurwitz}
    \uses{lem:hurwitz_cf_den_pos, lem:hurwitz_conv_den_eq, lem:hurwitz_triangle}
    If $\xi$ is irrational and neither $\xi.\mathrm{convergent}(n)$ nor $\xi.\mathrm{convergent}(n+1)$ satisfies the Hurwitz bound $|\xi - q| < 1/(\sqrt{5} \cdot q.\mathrm{den}^2)$, then $B_{n+1}/B_n + B_n/B_{n+1} \leq \sqrt{5}$, where $B_k$ is the $k$-th denominator of the generalized continued fraction for $\xi$.
\end{lemma}
\begin{proof}
    Let $B = B_n$ and $B' = B_{n+1}$. From the failure hypotheses, $|\xi - c_n| \geq 1/(\sqrt{5} B^2)$ and $|\xi - c_{n+1}| \geq 1/(\sqrt{5} B'^2)$. By the triangle identity (Lemma~\ref{lem:hurwitz_triangle}), their sum equals $1/(B B')$, so $1/(B B') \geq 1/(\sqrt{5} B^2) + 1/(\sqrt{5} B'^2)$. Multiplying both sides by $\sqrt{5} B^2 B'^2$ and simplifying yields $B'^2 + B^2 \leq \sqrt{5}(B B')$, i.e., $B'/B + B/B' \leq \sqrt{5}$.
\end{proof}

\begin{lemma}[Denominator ratio bounded by golden ratio when two fail]
    \label{lem:hurwitz_ratio_le_golden}
    \lean{ratio_le_golden_of_not_hurwitz}
    \uses{lem:hurwitz_ratio_bound, lem:hurwitz_cf_den_pos, lem:hurwitz_quad_golden}
    If $\xi$ is irrational and neither $\xi.\mathrm{convergent}(n)$ nor $\xi.\mathrm{convergent}(n+1)$ satisfies the Hurwitz bound, then $B_{n+1}/B_n \leq \varphi$.
\end{lemma}
\begin{proof}
    Let $r = B_{n+1}/B_n$. By Lemma~\ref{lem:hurwitz_ratio_bound}, $r + 1/r \leq \sqrt{5}$. Since $r > 0$, Lemma~\ref{lem:hurwitz_quad_golden} gives $r \leq \varphi$.
\end{proof}

\begin{lemma}[Next ratio bounded below by golden ratio via recurrence]
    \label{lem:hurwitz_ratio_ge_golden}
    \lean{ratio_ge_golden_of_recurrence}
    \uses{lem:hurwitz_cf_den_pos, lem:hurwitz_cf_den_rec, lem:hurwitz_ratio_squeeze}
    If $\xi$ is irrational and $B_{n+1}/B_n \leq \varphi$, then $B_{n+2}/B_{n+1} \geq \varphi$.
\end{lemma}
\begin{proof}
    From the recurrence inequality (Lemma~\ref{lem:hurwitz_cf_den_rec}), $B_{n+2} \geq B_{n+1} + B_n$, so $B_{n+2}/B_{n+1} \geq 1 + B_n/B_{n+1} = 1 + 1/r$ where $r = B_{n+1}/B_n$. Since $r \leq \varphi$, Lemma~\ref{lem:hurwitz_ratio_squeeze} gives $1 + 1/r \geq \varphi$. Hence $B_{n+2}/B_{n+1} \geq \varphi$.
\end{proof}

\begin{lemma}[Denominator ratio bounded above for shifted pair]
    \label{lem:hurwitz_ratio_le_golden_prime}
    \lean{ratio_le_golden_of_not_hurwitz'}
    \uses{lem:hurwitz_ratio_le_golden}
    If $\xi$ is irrational and neither $\xi.\mathrm{convergent}(n+1)$ nor $\xi.\mathrm{convergent}(n+2)$ satisfies the Hurwitz bound, then $B_{n+2}/B_{n+1} \leq \varphi$.
\end{lemma}
\begin{proof}
    Apply Lemma~\ref{lem:hurwitz_ratio_le_golden} with index $n+1$: if neither convergent $n+1$ nor convergent $n+2$ satisfies the bound, then $B_{n+2}/B_{n+1} \leq \varphi$.
\end{proof}

\begin{lemma}[Among three consecutive convergents, one satisfies Hurwitz]
    \label{lem:hurwitz_three_consec}
    \lean{three_consecutive_one_hurwitz}
    \uses{lem:hurwitz_ratio_le_golden, lem:hurwitz_ratio_ge_golden, lem:hurwitz_ratio_le_golden_prime, lem:hurwitz_golden_not_ratio, lem:hurwitz_cf_den_pos}
    If $\xi$ is irrational, then for every $n \in \mathbb{N}$, at least one of $\xi.\mathrm{convergent}(n)$, $\xi.\mathrm{convergent}(n+1)$, $\xi.\mathrm{convergent}(n+2)$ satisfies $|\xi - q| < 1/(\sqrt{5} \cdot q.\mathrm{den}^2)$.
\end{lemma}
\begin{proof}
    Suppose for contradiction that all three fail the bound. By Lemma~\ref{lem:hurwitz_ratio_le_golden} applied to the $(n, n+1)$ pair, $r = B_{n+1}/B_n \leq \varphi$. By Lemma~\ref{lem:hurwitz_ratio_ge_golden}, $r' = B_{n+2}/B_{n+1} \geq \varphi$. By Lemma~\ref{lem:hurwitz_ratio_le_golden_prime} applied to the $(n+1, n+2)$ pair, $r' \leq \varphi$. So $r' = \varphi$ exactly. But $B_{n+1}$ and $B_{n+2}$ are positive integers (the CF denominators are integer-valued), so $B_{n+2}/B_{n+1} = \varphi$ contradicts Lemma~\ref{lem:hurwitz_golden_not_ratio}.
\end{proof}

\begin{lemma}[Convergents are injective]
    \label{lem:hurwitz_conv_injective}
    \lean{convergents_injective}
    \uses{lem:hurwitz_bracket, lem:hurwitz_conv_den_eq, lem:hurwitz_cf_den_lt_skip}
    If $\xi$ is irrational, then the function $n \mapsto \xi.\mathrm{convergent}(n)$ is injective.
\end{lemma}
\begin{proof}
    Suppose $\xi.\mathrm{convergent}(n) = \xi.\mathrm{convergent}(m)$ with $n \neq m$. Consecutive convergents are distinct (from Lemma~\ref{lem:hurwitz_bracket}, they bracket $\xi$ and cannot coincide). For $|n - m| \geq 2$, the CF denominators satisfy $B_n < B_m$ (from Lemma~\ref{lem:hurwitz_cf_den_lt_skip} by induction) but Lemma~\ref{lem:hurwitz_conv_den_eq} implies $B_n = B_m$, a contradiction.
\end{proof}

\begin{lemma}[Hurwitz candidate in each window of three]
    \label{lem:hurwitz_candidate}
    \lean{hurwitz_candidate}
    \uses{lem:hurwitz_three_consec}
    If $\xi$ is irrational, then for every $n \in \mathbb{N}$ there exists $k \in \{3n, 3n+1, 3n+2\}$ such that $\xi.\mathrm{convergent}(k)$ satisfies the Hurwitz bound.
\end{lemma}
\begin{proof}
    Apply Lemma~\ref{lem:hurwitz_three_consec} at index $3n$: one of the three consecutive convergents starting at $3n$ satisfies the bound.
\end{proof}

\begin{lemma}[Infinitely many Hurwitz indices]
    \label{lem:hurwitz_indices_inf}
    \lean{hurwitz_indices_infinite}
    \uses{lem:hurwitz_candidate}
    If $\xi$ is irrational, then the set $\{n \in \mathbb{N} \mid |\xi - \xi.\mathrm{convergent}(n)| < 1/(\sqrt{5} \cdot (\xi.\mathrm{convergent}(n)).\mathrm{den}^2)\}$ is infinite.
\end{lemma}
\begin{proof}
    For any bound $N$, Lemma~\ref{lem:hurwitz_candidate} applied to $n = N+1$ gives a Hurwitz index $k \geq 3(N+1) > N$. So the set has no upper bound and is therefore infinite.
\end{proof}

\begin{lemma}[Infinitely many Hurwitz rationals]
    \label{lem:hurwitz_set_inf}
    \lean{hurwitz_set_infinite}
    \uses{lem:hurwitz_indices_inf, lem:hurwitz_conv_injective}
    If $\xi$ is irrational, then the set $\{q \in \mathbb{Q} \mid |\xi - q| < 1/(\sqrt{5} \cdot q.\mathrm{den}^2)\}$ is infinite.
\end{lemma}
\begin{proof}
    By Lemma~\ref{lem:hurwitz_indices_inf} there are infinitely many indices $n$ whose convergent satisfies the Hurwitz bound. Since convergents are injective (Lemma~\ref{lem:hurwitz_conv_injective}), these give infinitely many distinct rationals in the set. So the Hurwitz set is infinite.
\end{proof}

\begin{theorem}[Hurwitz's Approximation Theorem]
    \label{thm:hurwitz_approximation}
    \lean{hurwitz_approximation}
    \uses{lem:hurwitz_set_inf}
    For every irrational real number $\xi$, the set $\{q \in \mathbb{Q} \mid |\xi - q| < 1/(\sqrt{5} \cdot q.\mathrm{den}^2)\}$ is infinite.
\end{theorem}
\begin{proof}
    This is exactly Lemma~\ref{lem:hurwitz_set_inf}: the set of rationals approximating $\xi$ to within $1/(\sqrt{5} \cdot q.\mathrm{den}^2)$ is infinite.
\end{proof}

\chapter{Inverse Eigenvalue Theorem}

This section contains a proof of the Inverse Eigenvalue Theorem.
See \url{https://en.wikipedia.org/wiki/Inverse_eigenvalue_problem} for more details.

\begin{theorem}
  \label{thm:InverseEigenLinearEquiv}
  \lean{Module.End.inv_eigenvalue_iff}
  \leanok
  Let $M$ be a finite $R$-module where $R$ is a commutative ring and let $f$ be an isomorphism from
  $M$ to itself, then $\lambda \in R^\times$ is an eigenvalue of $f$ if and only if
  $\lambda^{-1}$ is an eigenvalue of $f^{-1}$.
\end{theorem}
\begin{proof}
Suppose $\lambda \in R^\times$ is an eigenvalue of $f$. By definition, there exists a non-zero
vector $v \in M$ such that $f(v) = \lambda \cdot v$. We can apply $f^{-1}$ to both sides of the eigenvalue
equation: $$f^{-1}(f(v)) = f^{-1}(\lambda \cdot v)$$ which implies
$f^{-1}(\lambda \cdot v) = \lambda \cdot f(v) = v$, hence $\lambda^{-1}$ is an eigenvalue of
$f^{-1}$ and vice versa.
\end{proof}


\begin{theorem}
  \label{thm:InverseEigenMatrix}
  \lean{Module.End.inv_eigenvalue_iff}
  \leanok
  Let $A$ be an $n \times n$ matrix over a commutative ring $R$ with an inverse $A^{-1}$, then
  $\lambda \in R^\times$ is an eigenvalue of $A$ if and only if $\lambda^{-1}$ is an eigenvalue
  of $A^{-1}$.
\end{theorem}

\begin{proof}
  \uses{thm:InverseEigenLinearEquiv}
  This follows directly from Theorem~\ref{thm:InverseEigenLinearEquiv} by considering the
  $R$-module $R^n$ and the isomorphism induced by the matrix $A$.

\end{proof}

