\begin{lemma}
    \label{lem:isNilpotent_of_pow_trace_eq_zero}
    \lean{Module.End.isNilpotent_of_pow_trace_eq_zero}
    Given a field $K$ which is characteristic $0$, let $V$ be a finite-dimensional vector space over
    $K$ and $f$ be a $K$-linear endomorphism of $V$. Then $f$ is nilpotent if and only if
    $\mathrm{Tr}(f^i) = 0$ for every integer $1 \leq i \leq n$ where $n$ is the dimension of $V$.
\end{lemma}

\begin{proof}
    It's known (in mathlib) that $f$ is nilpotent iff the characteristic polynomial of $f$ is of the
    form $x^n$ hence the forward direction is clear.
    The backward direction follows from the fact that $Tr(f^i) = \sum_{j} \alpha_j^i$ where
    $\alpha_j$ are all roots of the characteristic polynomial of $f$, hence every $\alpha_j$ is
    zero and we are done.
\end{proof}

\begin{lemma}[Nilpotency of a Product of Endomorphisms]
    \label{lem:nilpotency_of_product}
    \lean{LieAlgebra.isNilpotent_of_isNilpotent_zero_bracket}
    Let $V$ be a finite-dimensional vector space, and let $A$ and $B$ be endomorphisms of $V$.
    Assume that $A$ is nilpotent and that $[A, [A, B]] = 0$. Then the product $AB$ is nilpotent.
\end{lemma}

\begin{proof}
    \uses{lem:isNilpotent_of_pow_trace_eq_zero}
    Let $C = [A, B]$. Since $[A, C] = 0$, we have $[A, BC^p] = [A, B]C^p = C^{p+1}$ for every integer
    $p \geq 0$. Consequently, $\mathrm{Tr}(C^p) = 0$ for $p \geq 1$, which proves that $C$ is nilpotent.
    Now let $\bar{k}$ be an algebraic closure of $k$, and let $\lambda \in \bar{k}$ and
    $x \in V \otimes_k \bar{k}$ be such that $ABx = \lambda x$ and $x \neq 0$. The relation $[[B, A], A] = 0$
    shows that $[B, A^p] = p[B, A]A^{p-1}$ for every integer $p \geq 0$. Let $r$ be the smallest integer
    such that $A^r x = 0$. Then
    $$\lambda A^{r-1}x = A^{r-1}ABx = A^r Bx = B A^r x - [B, A^r]x = -r[B, A]A^{r-1}x.$$
    Since $[B, A] = -C$ is nilpotent and $A^{r-1}x \neq 0$, this proves that $\lambda = 0$.
    Thus, all the eigenvalues of $AB$ are zero, which implies that $AB$ is nilpotent.
\end{proof}

\begin{lemma}[Existence of the Third Triplet Element]
    \label{lem:existence_of_third_element}
    \lean{LieAlgebra.exists_Sl2triple}
    Let $h, x \in \mathfrak{g}$ be such that $[h, x] = 2x$ and $h \in \mathrm{Im}(\mathrm{ad}\,x)$.
    Then there exists an element $y \in \mathfrak{g}$ such that $(x, h, y)$ is either $(0, 0, 0)$
    or an $\mathfrak{sl}_2$-triplet.
\end{lemma}

\begin{proof}
    \uses{lem:nilpotency_of_product}
    Let $\mathfrak{g}' = kh + kx$. Since $x \in [\mathfrak{g}', \mathfrak{g}']$, the endomorphism $\mathrm{ad}_{\mathfrak{g}}\,x$ is nilpotent. Let $\mathfrak{n} = \mathrm{Ker}(\mathrm{ad}\,x)$. Since $[\mathrm{ad}\,h, \mathrm{ad}\,x] = \mathrm{ad}\,[h, x] = 2\,\mathrm{ad}\,x$, we have $(\mathrm{ad}\,h)\mathfrak{n} \subset \mathfrak{n}$.

    Let $z \in \mathfrak{g}$ be such that $h = -[x, z]$. The eigenvalues of $\mathrm{ad}\,h|_{\mathfrak{n}}$ are non-negative integers. Therefore, the restriction of $\mathrm{ad}\,h + 2$ to $\mathfrak{n}$ is invertible.

    Now consider the element $[h, z] + 2z$. We have
    $$[x, [h, z] + 2z] = [[x, h], z] + [h, [x, z]] + 2[x, z] = [-2x, z] + [h, -h] + 2[x, z] = 0.$$
    This means $[h, z] + 2z \in \mathfrak{n}$. Since $\mathrm{ad}\,h + 2$ is invertible on $\mathfrak{n}$, there exists an element $z' \in \mathfrak{n}$ such that $[h, z'] + 2z' = [h, z] + 2z$. Let $y = z - z'$. Then $[h, y] = -2y$. Since $z' \in \mathfrak{n} = \mathrm{Ker}(\mathrm{ad}\,x)$, we have $[x, y] = [x, z - z'] = [x, z] = -h$. Thus, $(x, h, y)$ forms an $\mathfrak{sl}_2$-triplet (or is $(0,0,0)$ if $x,h,y$ are all zero), completing the proof.
\end{proof}

\begin{theorem}[Jacobson-Morozov Theorem]
    \label{thm:jacobson_morozov}
    \lean{Jacobson_Morozov}
    Assume that $\mathfrak{g}$ is a semi-simple Lie algebra. Let $x$ be a non-zero nilpotent element
    of $\mathfrak{g}$. There exist elements $h, y \in \mathfrak{g}$ such that $(x, h, y)$ is an
    $\mathfrak{sl}_2$-triplet.
\end{theorem}

\begin{proof}
    \uses{lem:existence_of_third_element, lem:nilpotency_of_product}
    Let $\Phi$ be the Killing form of $\mathfrak{g}$. Let $\mathfrak{n} = \mathrm{Ker}((\mathrm{ad}\,x)^2)$.
    For any $z \in \mathfrak{n}$, we have
    $[\mathrm{ad}\,x, [\mathrm{ad}\,x, \mathrm{ad}\,z]] = \mathrm{ad}([x, [x, z]]) = 0$.
    Since $\mathrm{ad}\,x$ is nilpotent, Lemma \ref{lem:nilpotency_of_product} implies that
    $(\mathrm{ad}\,x) \circ (\mathrm{ad}\,z)$ is nilpotent. Therefore,
    $\Phi(x, z) = \mathrm{Tr}(\mathrm{ad}\,x \circ \mathrm{ad}\,z) = 0$. This shows that $x$ is
    orthogonal to $\mathfrak{n}$ with respect to the Killing form $\Phi$.
    Since $\Phi$ is non-degenerate and invariant, the orthogonal complement of $\mathfrak{n}$ is
    the image of $(\mathrm{ad}\,x)^2$. Thus, $x$ must be in the image of $(\mathrm{ad}\,x)^2$.
    This means there exists an element $y' \in \mathfrak{g}$ such that $x = [x, [x, y']]$.
    Let $h = -2[x, y']$. Then we have $[h, x] = -2[[x, y'], x] = 2[x, [x, y']] = 2x$. Also,
    $h = [x, -2y'] \in \mathrm{Im}(\mathrm{ad}\,x)$. The conditions of Lemma
    \ref{lem:existence_of_third_element} are now satisfied for $h$ and $x$.
    Since $x$ is non-zero, the triplet cannot be $(0,0,0)$. Therefore, there exists an element
    $y \in \mathfrak{g}$ such that $(x, h, y)$ is an $\mathfrak{sl}_2$-triplet.
\end{proof}

\chapter{Jones' Lemma}

This section contains a proof of Jones' Lemma.
See \url{https://en.wikipedia.org/wiki/Jones%27_lemma} for more details.

\begin{theorem}
  \label{them:jones}
  \lean{jones}
  Let $X$ be a normal and separable space. Let $Y$ be a discrete and closed subspace of $X$.
  Then $2^{|Y|} \leq 2^{\aleph_0}$.
\end{theorem}
\begin{proof}
  Let $D$ be a countable dense subset of $X$. Since $Y$ is discrete and closed, any $A \subset Y$
  is closed.
  Since $X$ is normal, for any $A \subseteq Y$, there exists two disjoint open sets $U_A, V_A$
  such that $A \subseteq U_A$ and $Y \setminus A \subseteq V_A$.
  Therefore, if $A, B \subseteq Y$ and $A \neq B$, then $\bar{U_A} \neq \bar{U_B}$.
  For any $A \subseteq Y$, we define $C_A = U_A \cap D$.
  Since $D$ is dense, we have $\bar{U_A} = \bar{U_A \cap D} = \bar{C_A}$ for $A \subseteq Y$.
  Therefore, if $A, B \subseteq Y$ and $A \neq B$, then $C_A \neq C_B$.
  That means, the map $A \mapsto C_A$ is an injection from the power set of $Y$ to
  the power set of $D$.
  Therefore, $2^{|Y|} \leq 2^{|D|} \leq 2^{\aleph_0}$.
\end{proof}

