\chapter{Kolmogorov's Three Series Theorem, necessity part}

This section contains a proof of the necessity direction of Kolmogorov's Three Series Theorem.
See \url{https://en.wikipedia.org/wiki/Kolmogorov's_three-series_theorem}
and \emph{Williams: "Probability with Martingales" (Theorem 12.5)} for more details.

Below, the convergence of a series $\sum_{n \in \N} x_n$ of real numbers
always means
\emph{conditional convergence}, i.e., the existence of the limit
\begin{align*}
  \lim_{N \to \infty} \sum_{n=0}^{N} x_n
\end{align*}
of its partial sums. (For measure theory purposes, by contrast,
\emph{absolute convergence} is a more commonly used notion;
it amounts to integrability with respect to the counting measure.)

\begin{lemma}[Compensator martingale]
  \label{lem:compensator_martingale}
  %\uses{}
  \lean{martingale_sq_sum_sub_sum_integral_sq}
  \leanok
  Let $(X_n)_{n \in \N}$ be a sequence of independent, square-integrable,
  zero-mean real-valued random variables.
  Define $M_n = \sum_{i=0}^{n-1} X_i$ for $n \in \N$.
  %Let $(M_n)_{n \in \N}$ be a martingale with respect to a
  %filtration $(\PRsigma_n)_{n \in \N}$, such that for all $n$,
  %the increment $M_{n+1} - M_n$ is square-integrable (in $L^2$).
  Then defining the sequence $(s_n)_{n \in \N}$
  \begin{align*}
    s_n \; = \; \sum_{i=0}^{n-1} \mathrm{Var}(X_n) ,
  \end{align*}
  and the process $(N_n)_{n \in \N}$
  \begin{align*}
    N_n \; = \; M_n^2 - s_n ,
  \end{align*}
  we have that $(N_n)_{n \in \N}$ is a martingale with respect to the
  natural filtration $(\PRsigma_n)_{n \in \N}$ of the sequence $(X_n)_{n \in \N}$.
\end{lemma}
\begin{proof}
  \uses{lem:martingale_of_partial_sums}
  % \leanok
  By Lemma~\ref{lem:martingale_of_partial_sums},
  $(M_n)_{n \in \N}$ is a martingale with respect to
  $(\PRsigma_n)_{n \in \N}$.

  Note, first, that we have
  \begin{align*}
    \EV \big[ (M_{n+1} - M_n)^2 \; \big| \; \PRsigma_n \big]
    \; = \; \EV\big[ X_n^2 \; \big| \; \PRsigma_n \big]
    \; = \; \EV[X_n^2]
    \; = \; \mathrm{Var}(X_n) ,
  \end{align*}
  by construction of $M$, by independence
  of $X_n$ from $\PRsigma_n = \sigma(X_0,\ldots,X_{n-1})$,
  and by the assumption $\EV[X_n]=0$.

  Since $M_{n}$ is $\PRsigma_n$-measurable, we have
  \begin{align*}
    \EV \big[ (M_{n+1} - M_n)^2 \; \big| \; \PRsigma_n \big]
    \; = \; & \EV \big[ M_{n+1}^2 - 2 M_{n+1} M_{n} + M_n^2 \; \big| \; \PRsigma_n \big] \\
    \; = \; & \EV \big[ M_{n+1}^2 \big| \; \PRsigma_n \big]
            - 2 M_{n} \, \underbrace{\EV \big[ M_{n+1} \big| \; \PRsigma_n \big]}_{= M_n}
            + M_n^2 \\
    \; = \; & \EV \big[ M_{n+1}^2 \big| \; \PRsigma_n \big] - M_n^2 .
  \end{align*}
  By unraveling definitions and rearranging, we get the martingale
  property of the process $(N_n)_{n \in \N}$:
  \begin{align*}
    \EV \big[ N_{n+1} \; \big| \; \PRsigma_n \big]
    \; = \; & \EV \big[ M_{n+1}^2 \; \big| \; \PRsigma_n \big]
              - s_{n+1}
              %- \underbrace{s_{n+1}}_{= s_n + \mathrm{Var}(X_n)}
              \\
    \; = \; & \Big( M_n^2 + \EV \big[ (M_{n+1} - M_n)^2 \; \big| \; \PRsigma_n \big] \Big)
              - \big( s_{n} + \mathrm{Var}(X_n) \big) \\
    \; = \; & M_n^2 - s_{n} \\
    \; = \; & N_n .
  \end{align*}
\end{proof}

\begin{lemma}[Summable variances of bounded independent zero-mean variables]
  \label{lem:summable_variance_independent_bounded_zero_mean}
  %\uses{}
  \lean{tsum_evariance_ne_top_of_exists_ae_tendsto_of_forall_integral_zero_of_forall_bounded}
  \leanok
  Let $K \in [0,+\infty)$ and let $(X_n)_{n \in \N}$ be a sequence of independent real-valued
  random variables such that
  $|X_n| \le K$ almost surely and $\EV[X_n]=0$ for each $n \in \N$.
  Suppose that $\sum_n X_n$ converges almost surely.
  Then we have
  \begin{align*}
    \sum_n \mathrm{Var}(X_n) \; < \; \infty .
  \end{align*}
\end{lemma}
\begin{proof}
  \uses{lem:martingale_of_partial_sums, lem:compensator_martingale}
  % \leanok
  Denote, for $n \in \N$,
  \begin{align*}
    s_n = \sum_{i=1}^{n-1} \mathrm{Var}(X_i) ,
  \end{align*}
  and $s_\infty = \sum_i \mathrm{Var}(X_i)$.
  We must prove that $s_\infty < +\infty$.

  By Lemma~\ref{lem:martingale_of_partial_sums},
  the process $(M_n)_{n \in \N}$ defined by
  \begin{align*}
    M_n \; := \; \sum_{i=0}^{n-1} X_i
  \end{align*}
  is a martingale with respect to the natural filtration $(\PRsigma_n)_{n \in \N}$
  of the sequence $(X_n)_{n \in \N}$.

  From the assumption that $\sum_{i} X_i$ converges almost surely
  we get that $(M_n)_{n \in \N}$ in particular is bounded
  almost surely.
  Defining, for $c \in \R$, the stopping time
  \begin{align*}
    T_c \; := \; \inf \big\{ n \in \N \; \big| \; |M_n| > c \big\} ,
  \end{align*}
  the almost sure boundedness implies that for some sufficiently large $c$,
  we have $\PR [T_c = \infty] > 0$.
  Fix such a value $c \in [0,+\infty)$.

  By Lemma~\ref{lem:compensator_martingale}, the process $(N_n)_{n \in \N}$ defined by
  \begin{align*}
    N_n \; := \; M_n^2 - s_n
  \end{align*}
  is a martingale, so in particular
  \begin{align*}
    0 \; = \; & \EV[N_{n \wedge T_c}] - \EV[N_0]
    \; = \; \EV[N_{n \wedge T_c}]
    \; = \; \EV[M^2_{n \wedge T_c}] - \EV[s_{n \wedge T_c}] .
  \end{align*}
  By the almost sure bound $|X_i| \le K$, we have that
  $|M_n^{T_c}| \le c + K$ almost surely, for any $n$, and we get
  in particular that
  \begin{align*}
    \EV[s_{n \wedge T_c}] = \EV[M^2_{n \wedge T_c}] \le (c + K)^2 ,
  \end{align*}
  for any $n$.
  But since we chose $c$ so that $\PR[T_c = \infty] > 0$,
  with positive probability we have $s_{n \wedge T_c} \nearrow s_\infty$.
  This would contradict $\EV[s_{n \wedge T_c}] \le (c + K)^2$
  if $s_\infty = +\infty$. We thus conclude the desired $s_\infty < +\infty$.
\end{proof}

It turns out that the assumption of zero-mean is not necessary above.
\begin{lemma}[Summable variances of bounded independent variables]
  \label{lem:summable_variance_independent_bounded}
  %\uses{}
  \lean{tsum_evariance_ne_top_of_exists_ae_tendsto_of_forall_bounded}
  \leanok
  Let $K \in [0,+\infty)$ and let $(X_n)_{n \in \N}$ be a sequence of independent
  real-valued random variables such that
  $|X_n| \le K$ almost surely for each $n \in \N$.
  Suppose that $\sum_n X_n$ converges almost surely.
  Then we have that $\sum_n \EV [X_n]$ converges and
  $\sum_n \mathrm{Var}(X_n) \; < \; \infty$.
\end{lemma}
\begin{proof}
  \uses{lem:summable_variance_independent_bounded_zero_mean}
  % \leanok
  The proof uses a construction of two independent copies of the
  sequence $(X_n)_{n \in \N}$.
  To construct the copies, it suffices to take the product of the
  underlying probability space with itself, and equip it with the
  product measure.

  So let $(X^{(1)}_n)_{n \in \N}$ and $(X^{(2)}_n)_{n \in \N}$ be independent,
  following the same distribution as $(X_n)_{n \in \N}$.

  Denote $Z_n = X^{(1)}_n - X^{(2)}_n$, for $n \in \N$.

  Note that both series $\sum_n X^{(1)}_n$ and $\sum_n X^{(2)}_n$
  converge almost surely, and therefore almost surely they both converge simultaneously.
  Therefore the series $\sum_n Z_n$ of the differences also
  converges almost surely.

  Also almost surely both $X^{(1)}_n \le K$ and $|X^{(2)}_n| \le K$
  for all $n$. Thus clearly $|Z_n| \le 2 K$ almost surely.
  Moreover, we have
  \begin{align*}
    \EV[Z_n] = \EV[X^{(1)}_n] - \EV[X^{(2)}_n] = \EV[X_n] - \EV[X_n] = 0
  \end{align*}
  and (by independence)
  \begin{align*}
    \mathrm{Var}(Z_n)
    \; = \; \mathrm{Var}(X^{(1)}_n - X^{(2)}_n)
    \; = \; \mathrm{Var}(X^{(1)}_n) + \mathrm{Var}(X^{(2)}_n)
    \; = \; 2 \, \mathrm{Var}(X_n) .
  \end{align*}
  Finally, the members of the sequence $(Z_n)_{n \in \N}$ are independent.

  Lemma~\ref{lem:summable_variance_independent_bounded_zero_mean}
  now applies to $(Z_n)_{n \in \N}$, and yields that
  $\sum_n \mathrm{Var}(Z_n) \; < \; \infty$, which in view of
  $\mathrm{Var}(Z_n) = 2 \, \mathrm{Var}(X_n)$ implies
  \begin{align*}
    \sum_n \mathrm{Var}(X_n) \; < \; \infty ,
  \end{align*}
  which is one of the two parts of our assertion.

  Denote
  \begin{align*}
    Y_n \; := \; X_n - \EV[X_n] ,
  \end{align*}
  and construct a martingale $(M_n)_{n \in \N}$ by
  \begin{align*}
    M_n \; := \; \sum_{i=0}^{n-1} Y_i .
  \end{align*}
  From Lemma~\ref{lem:martingale_of_partial_sums_L2_norm}
  and $\sum_n \mathrm{Var}(Y_n) = \sum_n \mathrm{Var}(X_n) \; < \; \infty$
  we see that $(M_n)_{n \in \N}$ are bounded in $L^2$.
  In particular, the martingale convergence theorem
  gives almost sure limit for $M_n$ as $n \to \infty$.
  This means that
  \begin{align*}
    \sum_{n} Y_n \; = \; \sum_{n} \big( X_n - \EV[X_n] \big)
  \end{align*}
  converges almost surely.
  Since $\sum_n X_n$ was assumed to converge almost surely,
  we get that also $\sum_n \EV[X_n] = \sum_n X_n - \sum_n (X_n - \EV[X_n])$
  converges almost surely. This is the other part of the assertion.
\end{proof}

\begin{lemma}[Kolmogorov's Three Series, necessity 1]
  \label{lem:kolmogorov_three_series_necessity_a}
  %\uses{}
  \lean{kolmogorov_three_series_necessity_a}
  \leanok
  Let $(X_n)_{n \in \N}$ be a sequence of independent real-valued random variables
  such that the series $\sum_{n} X_n$ converges almost surely.
  Then for any $K > 0$, we have $\sum_{n} \PR(|X_n| > K) \, < \, \infty$.
\end{lemma}
\begin{proof}
  % \uses{}
  % \leanok
  Fix $K>0$.
  From the assumed almost sure convergence of $\sum_n X_n$, we get in
  particular that the terms of the series tend to zero almost surely,
  i.e., that $X_n \to 0$ almost surely. In particular, almost surely,
  $|X_n| > K$ for only finitely many $n$.
  From the (contrapositive of the) Borel-Cantelli lemma for independent
  events we therefore get that $\sum_{n} \PR(|X_n| > K)$ must converge.
\end{proof}

\begin{lemma}[Kolmogorov's Three Series, necessity 2]
  \label{lem:kolmogorov_three_series_necessity_b}
  %\uses{}
  \lean{kolmogorov_three_series_necessity_b}
  \leanok
  Let $(X_n)_{n \in \N}$ be a sequence of independent real-valued random variables
  such that the series $\sum_{n} X_n$ converges almost surely.
  Then for any $K > 0$, the series
  $\sum_{n} \EV \big[ X_n \, \indicOf{|X_n| \le K} \big]$
  converges, and moreover
  $\sum_n \mathrm{Var}(X_n) \; < \; \infty$.
\end{lemma}
\begin{proof}
  \uses{lem:summable_variance_independent_bounded}
  % \leanok
  Fix $K>0$.
  From the assumed almost sure convergence of $\sum_n X_n$, we get in
  particular that the terms of the series tend to zero almost surely,
  i.e., that $X_n \to 0$ almost surely. In particular, almost surely,
  $|X_n| > K$ for only finitely many $n$, and
  therefore
  $X_n = X_n \, \indicOf{|X_n| \le K}$ except for finitely many $n$.
  Therefore the convergence of $\sum_n X_n$ implies the
  convergence of $\sum_n X_n \, \indicOf{|X_n| \le K}$.
  Lemma~\ref{lem:summable_variance_independent_bounded}
  now implies both of the assertions.
\end{proof}

\begin{theorem}[Kolmogorov's Three Series, necessity]
  \label{thm:kolmogorov_three_series_necessity}
  %\uses{}
  \lean{kolmogorov_three_series_necessity}
  \leanok
  Let $(X_n)_{n \in \N}$ be a sequence of independent real-valued random variables
  such that the series $\sum_{n} X_n$ converges almost surely.
  Then for any $K > 0$, the following three properties hold:
  \begin{enumerate}
    \item We have $\sum_{n} \PR(|X_n| > K) \, < \, \infty$.
    \item The series $\sum_{n} \EV \big[ X_n \, \indicOf{|X_n| \le K} \big]$ converges.
    \item We have $\sum_{n} \mathrm{Var} \big( X_n \, \indicOf{|X_n| \le K} \big) \, < \, \infty$.
  \end{enumerate}
\end{theorem}
\begin{proof}
  \uses{lem:kolmogorov_three_series_necessity_a,
        lem:kolmogorov_three_series_necessity_b}
  This is just a combination of
  Lemmas~\ref{lem:kolmogorov_three_series_necessity_a}
  and~\ref{lem:kolmogorov_three_series_necessity_b}.
\end{proof}

