informal_proof:
\chapter{Kolmogorov's Three Series Theorem, sufficiency part}

This section contains a proof of the sufficiency direction of Kolmogorov's Three Series Theorem.
See \url{https://en.wikipedia.org/wiki/Kolmogorov's_three-series_theorem}
and \emph{Williams: "Probability with Martingales" (Theorem 12.5)} for more details.

Below, the convergence of a series $\sum_{n \in \N} x_n$ of real numbers
always means
\emph{conditional convergence}, i.e., the existence of the limit
\begin{align*}
  \lim_{N \to \infty} \sum_{n=0}^{N} x_n
\end{align*}
of its partial sums. (For measure theory purposes, by contrast,
\emph{absolute convergence} is a more commonly used notion;
it amounts to integrability with respect to the counting measure.)

\begin{lemma}[Series differing only at finitely many terms]
  \label{lem:series_of_finitely_differing_terms}
  %\uses{}
  \lean{Filter.EventuallyEq.tendsto_sum_range_add_finsum_of_cofinite}
  \leanok
  Let $(x_n)_{n \in \N}$ and $(y_n)_{n \in \N}$ be sequences of real numbers
  such that $x_n = y_n$ for all but finitely many $n \in \N$.
  Then the series $\sum_n x_n$ converges if and only if the
  series $\sum_n y_n$ converges, and in that case, the sums
  of these series are related by
  \begin{align*}
    \sum_n x_n = \sum_n y_n + \sum_{n \; : \; x_n \ne y_n} (x_n - y_n) ,
  \end{align*}
  where the last sum only has finitely many nonzero terms.
\end{lemma}
\begin{proof}
  % \uses{}
  \leanok
  By assumption, there exists an $N_0 \in \N$ such that
  $x_n = y_n$ for all $n \ge N_0$. Then the partial sums
  with $N \ge N_0$ evidently satisfy
  \begin{align*}
    \sum_{n=0}^N x_n = \sum_{n=0}^N y_n + \sum_{n \; : \; x_n \ne y_n} (x_n - y_n) .
  \end{align*}
  From here it is clear that the existence of the limits of partial sums
  for the two series are equivalent, and their difference is the
  rightmost finite sum.
\end{proof}

\begin{lemma}[Martingale of partial sums]
  \label{lem:martingale_of_partial_sums}
  %\uses{}
  \lean{sum_terms_mgale}
  \leanok
  Let $(Y_i)_{i \in \N}$ be a sequence of independent real-valued random variables
  of mean zero, $\EV[Y_i] = 0$ for all $i$.
  Then the process $(M_n)_{n \in \N}$ defined by
  \begin{align*}
    M_n \; := \; \sum_{i=0}^{n-1} Y_i
  \end{align*}
  is a martingale with respect to the natural filtration $(\PRsigma_n)_{n \in \N}$
  of the sequence $(Y_n)_{n \in \N}$ defined by
  $\PRsigma_n = \sigma(Y_0, \ldots, Y_{n-1})$ for $n \in \N$.
\end{lemma}
\begin{proof}
  % \uses{}
  \leanok
  Adaptedness and integrability of $M_n$ are clear.

  Let $n \in \N$.
  By adaptedness, we have $\EV[M_n \, | \, \PRsigma_n] = M_n$.
  By independence of $(Y_n)_{n \in \N}$,
  we have that $Y_n$ is independent of $\PRsigma_n$, and therefore
  $\EV[Y_n \, | \, \PRsigma_n] = \EV[Y_n]$.
  The martingale property of $(M_n)_{n \in \N}$ follows from these and the zero-mean
  property $\EV[Y_n] = 0$, since
  \begin{align*}
    \EV[M_{n+1} \, | \, \PRsigma_n]
    \; = \; & \EV[M_n + Y_n \, | \, \PRsigma_n] \\
    \; = \; & M_n + \underbrace{\EV[Y_n \, | \, \PRsigma_n]}_{= \EV[Y_n] = 0} \; = \; M_n .
  \end{align*}
\end{proof}

\begin{lemma}[$L^2$ norm of martingale of partial sums]
  \label{lem:martingale_of_partial_sums_L2_norm}
  %\uses{lem:martingale_of_partial_sums}
  \lean{eLpNorm_two_sq_sum_terms_eq_sum_evariance}
  \leanok
  Let $(Y_i)_{i \in \N}$ be a sequence of independent square-integrable
  real-valued random variables of mean zero, $\EV[Y_i] = 0$ for all $i$.
  %Then the martingale $(M_n)_{n \in \N}$ defined by
  Then the $L^2$-norm squared of
  \begin{align*}
    M_n \; := \; \sum_{i=0}^{n-1} Y_i
  \end{align*}
  %has $L^2$-norms given by
  is given by
  \begin{align*}
    \|M_n\|_2^2 \; = \; \EV[M_n^2] \; = \; \sum_{i=0}^{n-1} \mathrm{Var}[Y_i] .
  \end{align*}
\end{lemma}
\begin{proof}
  % \uses{}
  \leanok
  Since $M_n$ is itself clearly zero-mean, we have $\EV[M_n^2] = \mathrm{Var}[M_n]$.
  Furthermore, since $M_n = \sum_{i=0}^{n-1} Y_i$ with independent terms $Y_i$, we have
  $\mathrm{Var}[M_n] = \sum_{i=0}^{n-1} \mathrm{Var}[Y_i]$.
\end{proof}

\begin{theorem}[Kolmogorov's Three Series, sufficiency]
  \label{thm:kolmogorov_three_series_sufficiency}
  %\uses{}
  \lean{kolmogorov_three_series_sufficiency}
  \leanok
  Let $(X_n)_{n \in \N}$ be a sequence of independent real-valued random variables.
  Suppose that there exists a $K > 0$ such that the following three properties hold:
  \begin{enumerate}
    \item We have $\sum_{n} \PR(|X_n| > K) \, < \, \infty$.
    \item The series $\sum_{n} \EV \big[ X_n \, \indicOf{|X_n| \le K} \big]$ converges.
    \item We have $\sum_{n} \mathrm{Var} \big( X_n \, \indicOf{|X_n| \le K} \big) \, < \, \infty$.
  \end{enumerate}
  Then the series $\sum_{n} X_n$ converges almost surely.
\end{theorem}
\begin{proof}
  \uses{lem:series_of_finitely_differing_terms, lem:martingale_of_partial_sums,
        lem:martingale_of_partial_sums_L2_norm}
  \leanok
  Denote $X_n^K := X_n \, \indicOf{|X_n| \le K}$ for brevity.

  Note first that by (1.)
  \begin{align*}
    \sum_n \PR \big[ X_n \ne X_n^K \big] \; \le \; \sum_n \PR \big[ |X_n| > K \big] \; < \; \infty .
  \end{align*}
  It follows from the first Borel-Cantelli lemma that, almost surely,
  $X_n = X_n^K$ for all but finitely many $n \in \N$, i.e., there
  exists a (random, almost surely finite) $N$ such that
  \begin{align*}
  X_n = X_n^K \qquad \text{ for all $n \ge N$.}
  \end{align*}
  Therefore it suffices to prove that $\sum_{n} X_n^K$ converges almost surely.

  Denote $Y_n^K = X_n^K - \EV[X_n^K]$.
  By (2.) it is enough to prove that the series
  $\sum_{n} Y_n^K = \sum_n \big( X_n^K - \EV[X_n^K] \big)$ converges almost surely.

  The sequence $(Y_n^K)_{n \in \N}$ is a sequence of independent, integrable,
  zero-mean random variables, so the process $(M_n)_{n \in \N}$ defined by
  \begin{align*}
    M_n \; := \; \sum_{i=0}^{n-1} Y_i^K
  \end{align*}
  is a martingale, and
  \begin{align*}
    \EV[M_n^2] \; = \; \mathrm{Var}[M_n] \; = \; & \sum_{i=0}^{n-1} \mathrm{Var}[Y_i^K]
    = \; \sum_{i=0}^{n-1} \mathrm{Var}[X_i^K] .
  \end{align*}
  By assumption (3.), the last expression is bounded uniformly in $n$.
  Therefore $(M_n)_{n \in \N}$ is a martingale bounded in $L^2$,
  and so by the Martingale Convergence Theorem, it converges almost surely (and in $L^2$).
  Thus the series $\sum_n Y_n^K$ converges almost surely, and the proof is complete.
\end{proof}

