\chapter{Kraft's Theorem}

This section contains a proof of Kraft's Theorem.
See \url{https://en.wikipedia.org/wiki/Kraft%E2%80%93McMillan_inequality} for more details.

Let $\sigma$ be a finite nonempty set, which we call the \emph{alphabet}.
We write $D = |\sigma|$ for the size of the alphabet.

\begin{definition}[Code]
  \label{def:Kraft_Code}
  \lean{Kraft.Code}
  \leanok
  A \emph{code} $C$ over the alphabet $\sigma$ is a finite set of finite strings
  over $\sigma$. The elements of $C$ are called \emph{codewords}.
\end{definition}

\begin{definition}[Prefix-free code]
  \label{def:Prefix_Free_Code}
  \lean{Kraft.PrefixFree}
  \uses{def:Kraft_Code}
  \leanok
  A code $C$ is \emph{prefix-free} if no codeword is a proper prefix of another:
  whenever $w_1, w_2 \in C$ and $w_1$ is a prefix of $w_2$, then $w_1 = w_2$.
\end{definition}

\begin{definition}[Kraft sum]
  \label{def:Kraft_Sum_List}
  \lean{Kraft.kraftSum}
  \leanok
  The \emph{Kraft sum} of a list of natural numbers $l_1, \ldots, l_m$
  with respect to an alphabet $\sigma$ of size $D = |\sigma|$ is
  \[
    K(l_1, \ldots, l_m) = \sum_{i=1}^{m} D^{-l_i}.
  \]
  For a code $C$ over an alphabet of size $D$, we write
  $K(C) = K(|w_1|, \ldots, |w_m|)$ where $w_1, \ldots, w_m$ are the
  codewords of $C$ and $|w_i|$ denotes the length of $w_i$.
\end{definition}

\begin{lemma}[Extensions are disjoint]
  \label{lem:extensions-disjoint}
  \lean{Kraft.extensions_disjoint}
  \uses{def:Kraft_Code, def:Prefix_Free_Code}
  \leanok
  Let $C$ be a prefix-free code. For any $n \in \mathbb{N}$ and distinct
  codewords $w_1, w_2 \in C$, the sets of their extensions to length $n$
  are disjoint:
  \[
    \{v \in \sigma^n : w_1 \text{ is a prefix of } v\}
    \cap
    \{v \in \sigma^n : w_2 \text{ is a prefix of } v\}
    = \emptyset.
  \]
\end{lemma}

\begin{proof}
  \leanok
  If $v$ has both $w_1$ and $w_2$ as prefixes, then one of $w_1, w_2$
  must be a prefix of the other (since both are prefixes of the same
  string $v$). But $C$ is prefix-free, so this forces $w_1 = w_2$,
  contradicting the assumption that they are distinct.
\end{proof}

\begin{lemma}[Counting blocked strings]
  \label{lem:count-blocked}
  \lean{Kraft.card_blocked_eq}
  \uses{def:Kraft_Code, def:Prefix_Free_Code}
  \leanok
  Let $C$ be a prefix-free code with all codeword lengths at most $n$.
  The number of strings of length $n$ that have some codeword of $C$
  as a prefix is exactly
  \[
    \sum_{w \in C} D^{n - |w|}.
  \]
\end{lemma}

\begin{proof}
  \uses{lem:extensions-disjoint}
  \leanok
  Each codeword $w \in C$ of length $|w| \leq n$ can be extended in
  $D^{n - |w|}$ ways to a string of length $n$. By
  Lemma~\ref{lem:extensions-disjoint}, these extension sets are pairwise
  disjoint, so the total count is $\sum_{w \in C} D^{n - |w|}$.
\end{proof}

The proof constructs the code greedily, adding codewords one at a time
from longest to shortest. The key ingredient is the following counting
lemma, which guarantees that a free codeword always exists.

\begin{lemma}[Existence of a free string]
  \label{lem:free-string}
  \lean{Kraft.exists_free_string}
  \uses{def:Kraft_Code, def:Prefix_Free_Code}
  \leanok
  Let $C$ be a prefix-free code with all codeword lengths at most $n$. If
  \[
    \sum_{w \in C} D^{-|w|} + D^{-n} \leq 1,
  \]
  then there exists a string of length $n$ that is not blocked by $C$
  (i.e., no codeword in $C$ is a prefix of it and it is not a prefix
  of any codeword in $C$).
\end{lemma}

\begin{proof}
  \uses{lem:count-blocked}
  \leanok
  By Lemma~\ref{lem:count-blocked}, the number of strings of length $n$ that
  have some codeword as a prefix is $\sum_{w \in C} D^{n - |w|}$.
  Multiplying the Kraft inequality by $D^n$ gives
  \[
    \sum_{w \in C} D^{n - |w|} + 1 \leq D^n,
  \]
  so $\sum_{w \in C} D^{n - |w|} < D^n$. Since there are $D^n$ strings
  of length $n$ in total, at least one string $v$ of length $n$ has no
  codeword as a prefix.

  It remains to check that $v$ is not a prefix of any codeword $c \in C$.
  Since $|v| = n \geq |c|$, the relation $v$ is a prefix of $c$ forces
  $|v| \leq |c|$, hence $|v| = |c|$, and so $v = c$. But then $c$ is
  a prefix of $v$, which contradicts the fact that no codeword is a prefix
  of $v$.
\end{proof}

\begin{lemma}[Preserving prefix-freeness]
  \label{lem:insert-prefix-free}
  \lean{Kraft.prefixFree_insert}
  \uses{def:Kraft_Code, def:Prefix_Free_Code}
  \leanok
  Let $C$ be a prefix-free code and let $w$ be a string not blocked by $C$
  and not already in $C$. Then $C \cup \{w\}$ is prefix-free.
\end{lemma}

\begin{proof}
  \leanok
  Let $w_1, w_2 \in C \cup \{w\}$ with $w_1$ a prefix of $w_2$.
  If both belong to $C$, prefix-freeness of $C$ gives $w_1 = w_2$.
  If $w_1 = w$ and $w_2 \in C$, then $w$ is a prefix of $w_2$, so $w$
  is blocked by $C$, a contradiction.
  If $w_1 \in C$ and $w_2 = w$, then $w_1$ is a prefix of $w$, so
  again $w$ is blocked, a contradiction.
\end{proof}

\begin{theorem}[Kraft]
  \label{thm:kraft}
  \lean{Kraft.kraft}
  \uses{def:Kraft_Code, def:Prefix_Free_Code, def:Kraft_Sum_List}
  \leanok
  Let $\sigma$ be a finite nonempty alphabet of size $D = |\sigma|$,
  and let $l_1, \ldots, l_m$ be natural numbers satisfying
  \[
    \sum_{i=1}^{m} D^{-l_i} \leq 1.
  \]
  Then there exists a prefix-free code $C$ over $\sigma$ whose codeword
  lengths are exactly $l_1, \ldots, l_m$ (as a multiset).
\end{theorem}

\begin{proof}
  \uses{lem:free-string, lem:insert-prefix-free}
  \leanok
  Sort the lengths in nonincreasing order: $l_1 \geq l_2 \geq \cdots \geq l_m$.
  This is a permutation of the original list, so the Kraft sum and the
  multiset of lengths are unchanged.

  We build the code by induction on $m$. If $m = 0$, the empty code works.
  For the inductive step, suppose that we have lengths $l_1 \geq l_2 \geq \cdots
  \geq l_m$ with $\sum D^{-l_i} \leq 1$.

  \medskip\noindent\textbf{Inductive hypothesis.}
  By the inductive hypothesis applied to $l_2, \ldots, l_m$ (whose Kraft
  sum is at most 1 since we dropped a nonneg\-ative term), there exists a
  prefix-free code $C'$ with codeword lengths $l_2, \ldots, l_m$.

  \medskip\noindent\textbf{All existing codewords are shorter.}
  Since $l_1 \geq l_i$ for all $i \geq 2$ (by sorting), every codeword
  in $C'$ has length at most $l_1$.

  \medskip\noindent\textbf{A free string exists.}
  The Kraft sum of $C'$ plus $D^{-l_1}$ equals $\sum_{i=1}^{m} D^{-l_i}
  \leq 1$. By Lemma~\ref{lem:free-string}, there exists a string $w$ of
  length $l_1$ that is not blocked by $C'$.

  \medskip\noindent\textbf{Insert and conclude.}
  By Lemma~\ref{lem:insert-prefix-free}, $C = C' \cup \{w\}$ is
  prefix-free, and its codeword lengths are $l_1, l_2, \ldots, l_m$.
\end{proof}

