\chapter{The LCM Lower Bound Theorem}

This section contains a proof of the theorem that for sufficiently large $n$, the LCM of the first $n$ positive integers is greater than $2^n$. This proof is based on the Beta integral and properties of binomial coefficients. It is based on a proof from M. Nair, "On Chebyshev-type inequalities for primes", Amer. Math. Monthly 89 (1982).
See \url{https://academicweb.nd.edu/~andyp/notes/AKS.pdf} for more details.

\begin{lemma}[Beta Integral as Sum]
  \label{lem:betaIntegral_eq_sum}
  \lean{Complex.betaIntegral_eq_sum}
  \leanok
  The beta integral can be expressed as a sum involving binomial coefficients and reciprocals:
  \[ B(m, j+1) = \int_0^1 x^{m-1}(1-x)^j dx = \sum_{k=0}^{j} (-1)^k \binom{j}{k} \frac{1}{m+k} \]
\end{lemma}

\begin{proof}
The proof expands $(1-x)^j$ using the binomial theorem and integrates term-by-term:
\[ B(m, j+1) = \int_0^1 x^{m-1}(1-x)^j dx = \int_0^1 \sum_{k=0}^{j} (-1)^k \binom{j}{k} \frac{1}{m+k} \]
Each integral $\int_0^1 x^{m+k-1} dx = \frac{1}{m+k}$ is evaluated by taking the antiderivative as a polynomial.
\end{proof}

\begin{lemma}[Binomial Coefficient Divisibility]
  \label{lem:mul_choose_dvd_LCM}
  \lean{mul_choose_dvd_LCM}
  \leanok
  For natural numbers $m, j$ with $m > 0$, we have:
  \[ m \binom{m+j}{m} \mid \text{LCM}(m+j) \]
  Where $\text{LCM}(m+j)$ is the least common multiple of the integers from $1$ to $m+j$.
\end{lemma}

\begin{proof}
  \uses{lem:betaIntegral_eq_sum}
The proof relates the Beta integral to two different expressions using Lemma~\ref{lem:betaIntegral_eq_sum}.
First, using the Gamma function:
\[ B(m, j+1) = \frac{1}{m \binom{m+j}{m}} \]
Second, from Lemma~\ref{lem:betaIntegral_eq_sum}:
\[ B(m, j+1) = \sum_{k=0}^{j} (-1)^k \binom{j}{k} \frac{1}{m+k} \]
Equating these expressions and multiplying by $\text{LCM}(m+j)$ shows that the left-hand side is an integer,
since each term on the right is an integer (as $m+k \le m+j$ implies $m+k \mid \text{LCM}(m+j)$).
\end{proof}

\begin{lemma}[Odd LCM Lower Bound]
  \label{lem:bound_odd_LCM}
  \lean{bound_odd_LCM}
  \leanok
  For any natural number $n \ge 4$:
  \[ (2n+1) 4^n \le \text{LCM}(2n+1) \]
\end{lemma}

\begin{proof}
  \uses{lem:mul_choose_dvd_LCM}
From Lemma~\ref{lem:mul_choose_dvd_LCM}, we obtain two divisibility relations:
\begin{enumerate}
    \item $n \binom{2n}{n} \mid \text{LCM}(2n)$, which implies $n \binom{2n}{n} \mid \text{LCM}(2n+1)$
    \item $(2n+1) \binom{2n}{n} \mid \text{LCM}(2n+1)$ (using the binomial identity)
\end{enumerate}
Since $n$ and $2n+1$ are coprime, we have $n(2n+1)\binom{2n}{n} \mid \text{LCM}(2n+1)$.
The result follows from the inequality $4^n < n\binom{2n}{n}$ for $n \ge 1$.
\end{proof}

\begin{lemma}[LCM Lower Bound for Large Numbers]
  \label{lem:LCM_lower_bound_9_le}
  \lean{LCM_lower_bound_9_le}
  \leanok
  For any natural number $n \ge 9$, we have $2^n \le \text{LCM}(n)$.
\end{lemma}

\begin{proof}
  \uses{lem:bound_odd_LCM}
For $n \ge 9$, we write $n$ as either $2k+1$ or $2k+2$ for some $k \ge 4$.
In both cases, we use Lemma~\ref{lem:bound_odd_LCM} and the monotonicity of LCM
to show that $\text{LCM}(n) \ge (2k+1)4^k \ge 2^n$.
\end{proof}

\begin{theorem}[LCM Lower Bound]
  \label{thm:LCM_lower_bound}
  \lean{Nat.LCM_lower_bound}
  \leanok
  For any natural number $n \ge 7$, we have $2^n \le \text{LCM}(n)$.
\end{theorem}

\begin{proof}
  \uses{lem:LCM_lower_bound_9_le}
  For $n \ge 9$, we apply Lemma~\ref{lem:LCM_lower_bound_9_le}.
  For $n = 7$ and $n = 8$, the inequality is verified by direct computation:
  $\text{LCM}(7) = 420 > 128 = 2^7$ and $\text{LCM}(8) = 840 > 256 = 2^8$.
\end{proof}

