\chapter{Mittag-Leffler}

This section contains a proof of the Mittag-Leffler condition for inverse systems.
See \url{https://stacks.math.columbia.edu/tag/0594} for more details.

\begin{lemma}
\label{lemma-ML-limit-nonempty}
\lean{nonempty_limit_of_nonempty_obj_of_MiLe}
\leanok
Let $(A_ i, \varphi _{ji})$ be a directed inverse system over $I$. Suppose $I$ is countable. If $(A_ i, \varphi _{ji})$ is Mittag-Leffler and the $A_ i$ are nonempty, then $\mathop{\mathrm{lim}}\nolimits A_ i$ is nonempty.
\end{lemma}

\begin{proof}
\leanok
Let $i_1, i_2, i_3, \ldots $ be an enumeration of the elements of $I$. Define inductively a sequence of elements $j_ n \in I$ for $n = 1, 2, 3, \ldots $ by the conditions: $j_1 = i_1$, and $j_ n \geq i_ n$ and $j_ n \geq j_ m$ for $m < n$. Then the sequence $j_ n$ is increasing and forms a cofinal subset of $I$. Hence we may assume $I =\{ 1, 2, 3, \ldots \} $.
So by Example 10.86.2 we are reduced to showing that the limit of an inverse system of nonempty sets with surjective maps indexed by the positive integers is nonempty. This follows from the axiom of choice. $\square$
\end{proof}

\begin{theorem}
\label{lemma-ML-exact-sequence}
\lean{IsMittagLeffler.mapShortExact}
