\chapter{Mycielski's theorem}

This section contains a proof of the theorem, due to Tutte, Zykov, and Mycielski, that there exist triangle-free graphs with arbitrarily large chromatic number.
See \url{https://en.wikipedia.org/wiki/Graph_coloring#Graphs_with_high_chromatic_number} for more details.


\begin{definition}
  \label{def:mycielskian}
  \lean{SimpleGraph.mycielskian}
  Given a graph $G$, the \textit{Mycielskian} of $G$ is the graph $\mu(G)$ defined as follows:
  The vertex set consists of
  \begin{itemize}
    \item A vertex $v_i$ for each vertex $v_i$ of $G$,
    \item A vertex $u_i$ for each vertex $v_i$ of $G$, and
    \item A vertex $w$.
  \end{itemize}
  The edge set consists of
  \begin{itemize}
    \item An edge $v_i v_j$ for each edge $v_i v_j$ of $G$,
    \item An edge $v_i u_j$ for each edge $v_i v_j$ of $G$,
    \item An edge $u_i w$ for each vertex $v_i$ of $G$.
  \end{itemize}
\end{definition}

\begin{lemma}
  \label{lem:mycielskian-triangle-free}
  \lean{SimpleGraph.mycielskian_cliqueFree}
  \uses{def:mycielskian}
  If $G$ is a triangle-free graph, then $\mu(G)$ is also triangle-free.
\end{lemma}

\begin{proof}
  Suppose for the sake of contradiction that $\mu(G)$ contains a triangle.
  Since $w$ is only adjacent to the vertices $u_i$, it cannot be part of the triangle.
  Therefore, the triangle must consist of vertices from the sets $\{v_i\}$ and $\{u_i\}$.
  If the tirangle consists of three vertices from the set $\{v_i\}$, then it corresponds to a triangle in $G$, which is a contradiction.
  If the triangle consists of two vertices $\{v_i, v_j\}$ and one vertex from the set $\{u_k\}$, then since the edges between the vertices $v_i$ and $u_j$ correspond to edges in $G$, this also corresponds to a triangle $v_i v_j v_k$ in $G$, which is a contradiction.
  The triangle cannot consist of two or more vertices from the set $\{u_i\}$, since there are no edges between vertices in the set $\{u_i\}$.
  Thus, $\mu(G)$ is triangle-free.
\end{proof}

\begin{lemma}
  \label{lem:mycielskian-chromatic-number}
  \lean{SimpleGraph.mycielskian_colorable_pred}
  \uses{def:mycielskian}
  If $G$ is a triangle-free graph with chromatic number $n$, then $\mu(G)$ has chromatic number at least $n+1$.
\end{lemma}

\begin{proof}
  Suppose for the sake of contradiction that $\mu(G)$ can be colored with $n$ colors by a coloring $c$.
  Without loss of generality, we can assume that $w$ is colored with color $n$.
  Therefore the vertices $u_i$ must be colored with colors from the set $\{1, 2, \ldots, n-1\}$.
  We now define a coloring $c'$ of $G$ with $n-1$ colors as follows:
  \begin{itemize}
    \item For each vertex $v_i$ of $G$, if coloring of $c(v_i)$ in $\mu(G)$ is not $k$, then we color $c'(v_i) = c(v_i)$ in $G$ with this color.
    \item If the coloring $c(v_i)$ in $\mu(G)$ is $k$, then we color $c'(v_i)$ equal to $v(u_i)$ in $\mu(G)$.
  \end{itemize}
  This is then a coloring of $G$ with $n-1$ colors, since $k$ is not used.
  Moreover, it is a proper coloring, since if $v_i$ and $v_j$ are adjacent in $G$,
  \begin{itemize}
    \item If the colorings $c(v_i)$ and $c(v_j)$ in $\mu(G)$ are both not $k$, then $c(v_i) = c'(v_i) \neq c'(v_j) = c(v_j)$, since $v_i, v_j$ are adjacent in $\mu(G)$.
    \item If (WLOG) the coloring $c(v_i)$ in $\mu(G)$ is $k$ and the coloring $c(v_j)$ in $\mu(G)$ is not $k$,
    then $c'(v_i) = c(u_i) \neq c(v_j) = c'(v_j)$, since $u_i, v_j$ are adjacent in $\mu(G)$.
    \item If the colorings $c(v_i)$ and $c(v_j)$ in $\mu(G)$ are both $k$, then we contradict the fact that $v_i$ and $v_j$ are adjacent and thus cannot be colored with the same color $k$.
  \end{itemize}
  Thus we have a proper coloring of $G$ with $n-1$ colors, which contradicts the fact that $G$ has chromatic number $n$.

\end{proof}

\begin{theorem}[Mycielski's theorem]
  \label{thm:mycielski}
  \lean{SimpleGraph.mycielski}
  \uses{lem:mycielskian-triangle-free, lem:mycielskian-chromatic-number}
  For any $n$, there exists a triangle-free graph with chromatic number at least $n$.
\end{theorem}

\begin{proof}
  By induction on $n$.
  For $n=0$, we can take an empty graph, which is triangle-free and has chromatic number $0$.
  Given a triangle-free graph $G$ with chromatic number at least $n$, we can take $\mu(G)$, which is triangle-free and has chromatic number at least $n+1$.
\end{proof}

