\chapter{Weird Numbers that are Multiples of Prime Powers}

This section contains a proof of a theorem about weird numbers that are multiples of prime powers.
See \url{https://mathoverflow.net/questions/505954/on-the-non-squarefree-odd-part-of-a-weird-number} for more details.

\begin{definition}[odd part of a number]
  \label{def:odd_part}
  \lean{Nat.oddPart}
  The odd part of a natural number $n$ is $n$ divided by the largest power of $2$ which divides $n$.
\end{definition}

\begin{theorem}[Positive multiples of abundant numbers are abundant]
  \label{thm:abundant_multiple}
  \lean{Abundant.mul_of_pos}
  For any abundant number $n$ and any positive integer $m$, the number $nm$ is abundant.
\end{theorem}

\begin{proof}
  A number is abundant if the sum of its proper divisors is larger than the number itself.
  The proper divisors of $nm$ include all numbers of the form $d m$ where $d$ is a proper divisor of $n$.
  The sum of these divisors is $m$ times the sum of the proper divisors of $n$,
  which is larger than $n$ since $n$ is abundant.
  Thus the sum of the proper divisors of $nm$ is larger than $nm$,
  so $nm$ is abundant.
\end{proof}

\begin{theorem}[Product of weird number with prime]
  \label{thm:weird_multiple}
  \lean{Weird.mul_prime_large}
  For any prime $p$, and weird number $n$ (with $k$-free part $a$),
  if $p$ is larger than $\sigma_1(a)$, the number $np$ is weird.
\end{theorem}

\begin{proof}
  \uses{thm:abundant_multiple}

  Given the assumptions, suppose that $np$ were not weird.
  Since $np$ is a positive multiple of the abundant number $n$, it is itself abundant by Theorem~\ref{thm:abundant_multiple}.
  Thus $np$ must be pseudoperfect; there is a subset $S$ of these factors which sum to $np$.

  Consider that the factors of the number $np$ will be of the form $dp^e$ where $d | a$ and $0 \le e \le k+1$.
  Consider the subset $S_1$ of elements of $S$ of the form $dp^{e}$ for positive $e$.
  The members of $S_1$ do not comprise all of $S$ and themselves sum to $np$, or else the corresponding subset $S_1 / p$ of divisors of $n$ would sum to $n$ and $n$ would be pseudoperfect and therefore not weird.
  Thus $S_1$ sums to less than $np^k$ (so that the total is not too large),
  and since each member of the set is a multiple of $p$, they sum a multiple of $p$ less than $np$,
  and the subset of elements of $S$ with $e = 0$ must therefore sum to at least $p$.
  But the sum of all divisors of this form comes to $\sigma_1(a) (1 + p + \dots + p^{k-1}) = \sigma_1(n) \frac{p^k - 1}{p - 1}$.
  For $p$ at least $\sigma_1(n) + 1$, we have $\sigma_1(n) \frac{p^k - 1}{p - 1} \le p^k - 1 < p^k$,
  so $p^k$ will be larger than this sum, which is a contradiction.

\end{proof}

\begin{theorem}[Product of weird number with prime power]
  \label{thm:weird_multiple_pow}
  \lean{Weird.mul_prime_pow_large}
  For any prime $p$, and $p$-free weird number $n$,
  if $p$ is larger than $\sigma_1(n)$, the number $np^k$ is weird for any nonnegative integer $k$.
\end{theorem}

\begin{proof}
  \uses{thm:weird_multiple}

  The proof follows by induction on $k$.

  In the base case $k = 0$, the statement reduces to the weirdness of $n$ itself, which is given.

  In the inductive step, assume the statement holds for $k$, and consider $k+1$.
  By the inductive hypothesis, $ap^k$ is weird.
  Applying Theorem~\ref{thm:weird_multiple} with $np^k$ in place of $n$ and $p$ in place of $p$,
  we note that the $k$-free part of $ap^k$ is still $a$, and
  we conclude that $np^{k+1}$ is weird.

\end{proof}

\begin{theorem}[Infinitely many weird numbers with non-squarefree odd part]
  \label{thm:weird_non_squarefree_odd_part}
  \lean{weird_squarefree_infinite}
  \uses{def:odd_part}
  There are infinitely many weird numbers with non-squarefree odd part.
\end{theorem}

\begin{proof}
  \uses{thm:weird_multiple_pow}
  From Theorem~\ref{thm:weird_multiple_pow}, for any $N$,
  taking $k = 2$ and $n = 70$ (a weird number)
  gives infinitely many weird numbers of the form $70 p^2$, where $p$ is prime sufficiently large compared to $N$.
  Each such number has a non-squarefree odd part, since $p^2$ is divisible by this odd part.
\end{proof}

\chapter{Ore's theorem}

This section contains a (stub of a) proof of Ore's theorem.
See \url{https://en.wikipedia.org/wiki/Ore's_theorem} for more details.

\begin{lemma}
  \label{ore-maximal-hamiltonian-cycle-free-graph}
  \lean{ore_maximal_hamiltonian_cycle_free_graph}
  If $G$ is a finite simple graph on $n \geq 3$ vertices that is not Hamiltonian, but adding any edge to $G$ creates a Hamiltonian graph,
  then $\deg v + \deg w \leq n - 1$ for any pair of distinct non-adjacent vertices $v$ and $w$.
\end{lemma}

\begin{proof}
  Let $v$ and $w$ be any distinct non-adjacent vertices in $G$.
  Since adding the edge $vw$ creates a Hamiltonian graph, there is a Hamiltonian cycle in $G + vw$ that contains the edge $vw$.
  Removing the edge $vw$ from this cycle gives a Hamiltonian path in $G$ with endpoints $v$ and $w$.
  Let the vertices of this path be $v = v_0, v_1, \ldots, v_{n-1} = w$ in order.
  For any $v_i, v_{i+1}$, we cannot have that both $v_i$ is adjacent to $w$ and $v_{i+1}$ is adjacent to $v$, since then we could construct a Hamiltonian cycle in $G$ by going from $v$ to $v_i$, then to $w$, then to $v_{i+1}$ backwards through the path, and then back to $v$.
  Therefore,reorganizing the sum of the degrees of $v$ and $w$ by these edges, we get that $\deg v + \deg w$ is at most the number of vertices in the path, which is $n - 1$.
\end{proof}

\begin{theorem}[Ore's theorem]
  \label{ore-theorem}
  \lean{ore_theorem}
  \uses{ore-maximal-hamiltonian-cycle-free-graph}
  If $G$ is a finite simple graph on $n \geq 3$ vertices such that $\deg v + \deg w \geq n$ for every pair of distinct non-adjacent vertices $v$ and $w$, then $G$ is Hamiltonian.
\end{theorem}

\begin{proof}
  By contraposition, it suffices to show that if $G$ is not Hamiltonian,
  then there exist distinct non-adjacent vertices $v$ and $w$ such that $\deg v + \deg w \leq n - 1$.
  This follows from Lemma~\ref{ore-maximal-hamiltonian-cycle-free-graph},
  since if $G$ is not Hamiltonian,
  we can add edges to $G$ that do not create a Hamiltonian graph until we get a maximal Hamiltonian-cycle-free graph,
  and then apply the lemma to that graph, at which point any distinct non-adjacent vertices $v$ and $w$ that we get from the lemma are also non-adjacent in $G$, and have lower degree in $G$ than they do in the maximal Hamiltonian-cycle-free graph, so they also satisfy $\deg v + \deg w \leq n - 1$ in $G$.
\end{proof}

