\chapter{The Prékopa-Leindler Inequality (dimension 1)}

This section contains a proof of the Prékopa-Leindler inequality.
See \url{https://en.wikipedia.org/wiki/Pr%C3%A9kopa%E2%80%93Leindler_inequality} for more details.

\section{Brunn-Minkowski Inequality in Dimension 1}

\begin{lemma}[One-dimensional Brunn-Minkowski inequality]
    \label{lem:one_dim_BMInequality}
    \lean{one_dim_BMInequality}
    Let $A, B, C$ be nonempty measurable sets in $\mathbb{R}$ such that $A + B \subseteq C$. Then
    \[
    \text{vol}(A) + \text{vol}(B) \le \text{vol}(C).
    \]
\end{lemma}
\begin{proof}
    The proof proceeds by several reductions. First, if either $A$ or $B$ has infinite measure, the result follows from monotonicity.

    For the finite case, we reduce to compact sets by approximation using mathlib lemmas. Given $\varepsilon > 0$, find compact sets $S \subseteq A$ and $T \subseteq B$ such that $\text{vol}(A \setminus S) < \varepsilon/2$ and $\text{vol}(B \setminus T) < \varepsilon/2$. Then
    \[
    \text{vol}(A) < \text{vol}(S) + \varepsilon/2, \quad \text{vol}(B) < \text{vol}(T) + \varepsilon/2.
    \]

    For compact sets, we use a direct geometric argument. Define $A_t = \inf B +_v A$ and $B_t = \sup A +_v B$. These sets are disjoint except at a single point, so $\text{vol}(A_t \cap B_t) = 0$. Since both are translates contained in $C$, we have
    \[
    \text{vol}(A_t) + \text{vol}(B_t) = \text{vol}(A_t \cup B_t) \le \text{vol}(C).
    \]
    By translation invariance, $\text{vol}(A_t) = \text{vol}(A)$ and $\text{vol}(B_t) = \text{vol}(B)$.
\end{proof}

\begin{lemma}[Brunn-Minkowski for null-measurable sets]
    \label{lem:one_dim_BMInequality_of_nullmeasurable}
    \lean{one_dim_BMInequality_of_nullmeasurable}
    \uses{lem:one_dim_BMInequality}
    The Brunn-Minkowski inequality holds for nonempty null-measurable sets in $\mathbb{R}$.
\end{lemma}
\begin{proof}
    For null-measurable sets $A, B$, find measurable subsets $A_m \subseteq A$ and $B_m \subseteq B$ that agree with $A$ and $B$ almost everywhere. Apply Lemma~\ref{lem:one_dim_BMInequality} to $A_m$ and $B_m$, and use the fact that null-measurable sets have the same measure as their measurable cores.
\end{proof}

\section{Definitions and Basic Properties}

\begin{definition}[Prékopa-Leindler condition]
    \label{def:PL_dim1_cond}
    \lean{PL_dim1_cond}
    For functions $f, g, h : \mathbb{R} \to \mathbb{R}$ and $t \in [0,1]$, we say the \emph{Prékopa-Leindler condition} holds if
    \[
    f(x)^{1-t} \cdot g(y)^t \le h(x + y)
    \]
    for all $x, y \in \mathbb{R}$.
\end{definition}

\begin{lemma}[Swapping in PL condition]
    \label{lem:PL_dim1_cond_swap}
    \lean{PL_dim1_cond_swap}
    \uses{def:PL_dim1_cond}
    The PL condition is symmetric: if $f, g, h$ satisfy the condition for parameter $t$, then $g, f, h$ satisfy it for parameter $1-t$.
\end{lemma}
\begin{proof}
    This follows from commutativity of addition and multiplication: $f(x)^{1-t} g(y)^t = g(y)^t f(x)^{1-t}$ and $x + y = y + x$.
\end{proof}

\begin{definition}[Prékopa-Leindler conclusion]
    \label{def:PL_dim1_conclusion}
    \lean{PL_dim1_conclusion}
    For functions $f, g, h : \mathbb{R} \to \mathbb{R}$ and $t \in [0,1]$, the \emph{Prékopa-Leindler conclusion} states
    \[
    \left(\int f\right)^{1-t} \left(\int g\right)^t \le (1-t)^{1-t} t^t \int h.
    \]
\end{definition}

\begin{lemma}[Swapping in PL conclusion]
    \label{lem:PL_dim1_conclusion_swap}
    \lean{PL_dim1_conclusion_swap}
    \uses{def:PL_dim1_conclusion}
    The PL conclusion is symmetric with respect to swapping $f \leftrightarrow g$ and $t \leftrightarrow 1-t$.
\end{lemma}
\begin{proof}
    Direct verification using commutativity of multiplication.
\end{proof}

\begin{definition}[Essentially bounded function]
    \label{def:IsEssBdd}
    \lean{IsEssBdd}
    A function $f$ is \emph{essentially bounded} with respect to measure $\mu$ if it is bounded above almost everywhere.
\end{definition}

\section{Normalized Functions}

\begin{lemma}[Volume inequality for normalized superlevel sets]
    \label{lem:fgh_nor_splsets_vol_le}
    \lean{fgh_nor_splsets_vol_le}
    \uses{def:PL_dim1_cond, lem:one_dim_BMInequality_of_nullmeasurable}
    Under appropriate normalization and boundedness conditions, the volumes of superlevel sets of normalized functions satisfy a Brunn-Minkowski type inequality.
\end{lemma}
\begin{proof}
    This combines the superlevel subset property (Lemma~\ref{lem:superlevel_subset}) with the one-dimensional Brunn-Minkowski inequality (Lemma~\ref{lem:one_dim_BMInequality_of_nullmeasurable}). The normalization ensures that we work with functions whose essential suprema are well-behaved.
\end{proof}

\section{Main Theorem and Its Variants}

\begin{lemma}[Pr\'ekopa-Leindler for essentially bounded functions]
    \label{lem:Prekopa_leindler_dim1_essBdd}
    \lean{prekopa_leindler_dim1_essBdd}
    \uses{def:PL_dim1_cond, def:PL_dim1_conclusion, lem:fgh_nor_splsets_vol_le}
    The Pr\'ekopa-Leindler inequality holds when both $f$ and $g$ are essentially bounded.
\end{lemma}
\begin{proof}
    The proof uses the layer cake representation and the normalized volume inequality. We normalize $f$ and $g$ by their essential suprema, apply the volume inequality to superlevel sets, and integrate using the layer cake formula. The weighted arithmetic-geometric mean inequality provides the final step.
\end{proof}

\begin{lemma}[Extension from bounded $g$]
    \label{lem:Prekopa_leindler_dim1_from_g_essBdd}
    \lean{prekopa_leindler_dim1_from_g_essBdd}
    \uses{def:PL_dim1_cond, def:PL_dim1_conclusion}
    If Pr\'ekopa-Leindler holds for all essentially bounded $g$, then it holds for all integrable $g$.
\end{lemma}
\begin{proof}
    Approximate $g$ by truncated functions $g_n = \min(g, n)$. These are essentially bounded, so the inequality holds for each $g_n$. Take the limit as $n \to \infty$ using monotone convergence.
\end{proof}

\begin{lemma}[Extension from bounded $f$]
    \label{lem:Prekopa_leindler_dim1_from_f_essBdd}
    \lean{prekopa_leindler_dim1_from_f_essBdd}
    \uses{def:PL_dim1_cond, def:PL_dim1_conclusion, lem:PL_dim1_cond_swap, lem:PL_dim1_conclusion_swap, lem:Prekopa_leindler_dim1_from_g_essBdd}
    If Pr\'ekopa-Leindler holds for all essentially bounded $f$, then it holds for all integrable $f$.
\end{lemma}
\begin{proof}
    Similar to the previous lemma, using the symmetry property (Lemma~\ref{lem:PL_dim1_cond_swap}).
\end{proof}

\begin{lemma}[Prékopa-Leindler with bounded $f$]
    \label{lem:prekopa_leindler_dim1_f_essBdd}
    \lean{prekopa_leindler_dim1_f_essBdd}
    \uses{def:IsEssBdd, def:PL_dim1_cond, def:PL_dim1_conclusion, lem:Prekopa_leindler_dim1_from_g_essBdd, lem:Prekopa_leindler_dim1_essBdd}
    The Prékopa-Leindler inequality holds when $f$ is essentially bounded.
\end{lemma}
\begin{proof}
    Combine Lemma~\ref{lem:Prekopa_leindler_dim1_essBdd} with Lemma~\ref{lem:Prekopa_leindler_dim1_from_g_essBdd}.
\end{proof}

\begin{theorem}[Main Theorem: Prékopa-Leindler inequality in dimension 1]
    \label{lem:PL_ineq_dim1}
    \lean{prekopa_leindler_dim1}
    \uses{def:PL_dim1_cond, def:PL_dim1_conclusion, lem:Prekopa_leindler_dim1_from_f_essBdd, lem:prekopa_leindler_dim1_f_essBdd}
    Let $0 < \lambda < 1$ and let $f, g, h$ be nonnegative integrable functions on $\mathbb{R}$ satisfying
    \[ h\big((1-\lambda)x + \lambda y\big) \;\ge\; f(x)^{1-\lambda} g(y)^{\lambda} \tag{10}\]
    for all $x,y \in \mathbb{R}$. Then
    \[
    \int_{\mathbb{R}} h(x)\,dx \;\ge\;
    \left( \int_{\mathbb{R}} f(x)\,dx \right)^{1-\lambda}
    \left( \int_{\mathbb{R}} g(x)\,dx \right)^{\lambda}.
    \tag{12}
    \]
\end{theorem}
\begin{proof}
    If $\int_{\mathbb{R}} f(x)\,dx = 0$ or $\int_{\mathbb{R}} g(x)\,dx = 0$ the Prékopa–Leindler inequality (12) holds trivially. We thus assume $\int_{\mathbb{R}} f(x)\,dx = F > 0$ and $\int_{\mathbb{R}} g(x)\,dx = G > 0$.
    Define the auxiliary functions $u,v : [0,1] \to \mathbb{R}$ such that $u(t)$ and $v(t)$ are the smallest numbers satisfying
    \[
    \frac{1}{F}\int_{-\infty}^{u(t)} f(x)\,dx
    = \frac{1}{G}\int_{-\infty}^{v(t)} g(x)\,dx
    = t.
    \tag{13}
    \]
    Since $f$ and $g$ are nonnegative, $u$ and $v$ are strictly increasing functions and hence are differentiable almost everywhere. Note that $u$ and $v$ do not have to be continuous everywhere. Taking the derivative of (13) with respect to $t$ gives for almost every $t$:
    \[
    \frac{f(u(t))u'(t)}{F} = \frac{g(v(t))v'(t)}{G} = 1.
    \tag{14}
    \]
    Let $w(t) = (1-\lambda)u(t) + \lambda v(t)$. By (14), for almost every $t \in (0,1)$ we have $f(u(t)) \neq 0 \neq g(v(t))$, and thus also
    \[
    \begin{aligned}
    w'(t) &= (1-\lambda)u'(t) + \lambda v'(t) \\
    &\ge u'(t)^{1-\lambda} v'(t)^{\lambda} \\
    &= \left( \frac{F}{f(u(t))} \right)^{1-\lambda}
      \left( \frac{G}{g(v(t))} \right)^{\lambda},
    \end{aligned}
    \tag{15}
    \]
    where we used Young’s inequality in the first step and (14) in the second step.
    By assumption (10), (15), $h \ge 0$ and $w$ being strictly increasing we have
    \[
    \int_{\mathbb{R}} h(x)\,dx
    \;\ge\; \int_{0}^{1} h(w(t))w'(t)\,dt
    \]
    \[
    \;\ge\; \int_{0}^{1} f(u(t))^{1-\lambda} g(v(t))^{\lambda}
    \left( \frac{F}{f(u(t))} \right)^{1-\lambda}
    \left( \frac{G}{g(v(t))} \right)^{\lambda} dt
    \]
    \[
    = F^{1-\lambda} G^{\lambda}
    = \left(\int_{\mathbb{R}} f(x)\,dx\right)^{1-\lambda}
      \left(\int_{\mathbb{R}} g(x)\,dx\right)^{\lambda}.
    \]
\end{proof}

