\chapter{Closed Form for Smallest Period of Pseudo-Arithmetic Progression}

This section contains a proof of the closed-form identity for A179382, the number of odd residues in a pseudo-arithmetic progression.
See \url{https://mathoverflow.net/questions/507658/closed-form-for-a179382} for more details.

% TODO some lemmas here could be golfed away for succinctness


\begin{lemma}[Residue bound]
    \label{lem:pap_residue_lt}
    \lean{residue_lt}
    For all $j, n : \mathbb{N}$, $2^j \bmod (2n+1) < 2n+1$.
\end{lemma}
\begin{proof}
    This follows from positivity of $2n+1$.
\end{proof}

\begin{lemma}[Double residue bound]
    \label{lem:pap_two_mul_residue_lt}
    \lean{two_mul_residue_lt}
    \uses{lem:pap_residue_lt}
    For all $j, n : \mathbb{N}$, $2 \cdot (2^j \bmod (2n+1)) < 2 \cdot (2n+1)$.
\end{lemma}
\begin{proof}
    Multiply the residue bound from the previous lemma by 2 on both sides.
\end{proof}

\begin{lemma}[Division algorithm for doubled residue]
    \label{lem:pap_div_algo_two_mul_residue}
    \lean{div_algo_two_mul_residue}
    For all $j, n : \mathbb{N}$,
    \[
        2 \cdot (2^j \bmod (2n+1)) = (2n+1) \cdot \Bigl\lfloor \tfrac{2 \cdot (2^j \bmod (2n+1))}{2n+1} \Bigr\rfloor + \bigl(2 \cdot (2^j \bmod (2n+1))\bigr) \bmod (2n+1).
    \]
\end{lemma}
\begin{proof}
    This is the Euclidean division identity applied to $2 \cdot (2^j \bmod (2n+1))$ divided by $2n+1$.
\end{proof}

\begin{lemma}[Quotient is at most one]
    \label{lem:pap_quotient_le_one}
    \lean{quotient_le_one}
    \uses{lem:pap_two_mul_residue_lt}
    For all $j, n : \mathbb{N}$, $\lfloor 2 \cdot (2^j \bmod (2n+1)) / (2n+1) \rfloor \leq 1$.
\end{lemma}
\begin{proof}
    Since $2 \cdot (2^j \bmod (2n+1)) < 2 \cdot (2n+1)$, the quotient under division by $2n+1$ is strictly less than 2, hence at most 1.
\end{proof}

\begin{lemma}[Double-residue mod equals next residue]
    \label{lem:pap_two_mul_residue_mod}
    \lean{two_mul_residue_mod}
    For all $j, n : \mathbb{N}$,
    \[
        \bigl(2 \cdot (2^j \bmod (2n+1))\bigr) \bmod (2n+1) = 2^{j+1} \bmod (2n+1).
    \]
\end{lemma}
\begin{proof}
    Use $2^{j+1} = 2 \cdot 2^j$ and the multiplicativity of the modulo operation.
\end{proof}

\begin{lemma}[Quotient equals parity: case less than]
    \label{lem:pap_quotient_eq_parity_case_lt}
    \lean{quotient_eq_parity_case_lt}
    For $j, n : \mathbb{N}$ with $n > 0$ and $2 \cdot (2^j \bmod (2n+1)) < 2n+1$,
    \[
        \Bigl\lfloor \tfrac{2 \cdot (2^j \bmod (2n+1))}{2n+1} \Bigr\rfloor
        = \bigl(2 \cdot (2^j \bmod (2n+1))\bigr) \bmod (2n+1) \bmod 2.
    \]
\end{lemma}
\begin{proof}
    When $2r_j < 2n+1$, the quotient is 0, and the remainder equals $2r_j$. Since $r_j$ is a natural number, $2r_j$ is even, so $2r_j \bmod 2 = 0$. Both sides equal 0.
\end{proof}

\begin{lemma}[Quotient equals parity: case at least]
    \label{lem:pap_quotient_eq_parity_case_ge}
    \lean{quotient_eq_parity_case_ge}
    \uses{lem:pap_two_mul_residue_lt, lem:pap_quotient_le_one}
    For $j, n : \mathbb{N}$ with $n > 0$ and $2n+1 \leq 2 \cdot (2^j \bmod (2n+1))$,
    \[
        \Bigl\lfloor \tfrac{2 \cdot (2^j \bmod (2n+1))}{2n+1} \Bigr\rfloor
        = \bigl(2 \cdot (2^j \bmod (2n+1))\bigr) \bmod (2n+1) \bmod 2.
    \]
\end{lemma}
\begin{proof}
    When $2n+1 \leq 2r_j < 2(2n+1)$, the quotient equals 1. The remainder is $2r_j - (2n+1)$, which is even minus odd, hence odd, so its parity is 1. Both sides equal 1.
\end{proof}

\begin{lemma}[Quotient equals parity of next residue]
    \label{lem:pap_quotient_eq_parity}
    \lean{quotient_eq_parity}
    \uses{lem:pap_quotient_eq_parity_case_lt, lem:pap_quotient_eq_parity_case_ge}
    For all $j, n : \mathbb{N}$ with $n > 0$,
    \[
        \Bigl\lfloor \tfrac{2 \cdot (2^j \bmod (2n+1))}{2n+1} \Bigr\rfloor
        = \bigl(2 \cdot (2^j \bmod (2n+1))\bigr) \bmod (2n+1) \bmod 2.
    \]
\end{lemma}
\begin{proof}
    Split on whether $2 \cdot (2^j \bmod (2n+1)) < 2n+1$ or $\geq 2n+1$, applying the two case lemmas.
\end{proof}

\begin{lemma}[The period set is nonempty]
    \label{lem:pap_order_set_nonempty}
    \lean{order_set_nonempty}
    For $n > 0$, the set $\{m \in \mathbb{N} \mid 0 < m \text{ and } (2n+1) \mid 2^m - 1\}$ is nonempty.
\end{lemma}
\begin{proof}
    Since $\gcd(2, 2n+1) = 1$ (as $2n+1$ is odd), the element 2 is a unit in $\mathbb{Z}/(2n+1)\mathbb{Z}$. The order of this unit is positive and satisfies $2^{\mathrm{ord}} \equiv 1 \pmod{2n+1}$, placing it in the set.
\end{proof}

\begin{lemma}[$a(n)$ is positive]
    \label{lem:pap_a_pos}
    \lean{a_pos}
    \uses{lem:pap_order_set_nonempty}
    For $n > 0$, $0 < a(n)$.
\end{lemma}
\begin{proof}
    Because the period set is nonempty, the infimum exists and belongs to the set and therefore satisfies the positivity condition.
\end{proof}

\begin{lemma}[$2^{a(n)} \equiv 1 \pmod{2n+1}$]
    \label{lem:pap_pow_a_mod_eq_one}
    \lean{pow_a_mod_eq_one}
    \uses{lem:pap_order_set_nonempty}
    For $n > 0$, $2^{a(n)} \bmod (2n+1) = 1$.
\end{lemma}
\begin{proof}
    $a(n)$ belongs to the period set, so $(2n+1) \mid 2^{a(n)} - 1$. Since $2^{a(n)} \geq 1$, this divisibility gives $2^{a(n)} \equiv 1 \pmod{2n+1}$.
\end{proof}

\begin{lemma}[Shifted sum equality]
    \label{lem:pap_sum_shift_eq}
    \lean{sum_shift_eq}
    For $k > 0$ and any $f : \mathbb{N} \to \mathbb{N}$ with $f(k) = f(0)$,
    \[
        \sum_{j=0}^{k-1} f(j+1) = \sum_{j=0}^{k-1} f(j).
    \]
\end{lemma}
\begin{proof}
    Reindex to write both sums in terms of $\sum_{j=0}^{k} f(j)$, then use $f(k) = f(0)$ to equate the boundary terms.
\end{proof}

\begin{lemma}[Residue sum is shift-invariant]
    \label{lem:pap_sum_residue_shift}
    \lean{sum_residue_shift}
    \uses{lem:pap_a_pos, lem:pap_pow_a_mod_eq_one, lem:pap_sum_shift_eq}
    For $n > 0$,
    \[
        \sum_{j=0}^{a(n)-1} \bigl(2^{j+1} \bmod (2n+1)\bigr) = \sum_{j=0}^{a(n)-1} \bigl(2^j \bmod (2n+1)\bigr).
    \]
\end{lemma}
\begin{proof}
    Apply the shifted sum lemma with $f(j) = 2^j \bmod (2n+1)$ and $k = a(n)$. The boundary condition $f(a(n)) = f(0)$ follows from $2^{a(n)} \bmod (2n+1) = 1 = 2^0 \bmod (2n+1)$.
\end{proof}

\begin{lemma}[Parity sum is shift-invariant]
    \label{lem:pap_sum_parity_shift}
    \lean{sum_parity_shift}
    \uses{lem:pap_a_pos, lem:pap_pow_a_mod_eq_one, lem:pap_sum_shift_eq}
    For $n > 0$,
    \[
        \sum_{j=0}^{a(n)-1} \bigl(2^{j+1} \bmod (2n+1)\bigr) \bmod 2
        = \sum_{j=0}^{a(n)-1} \bigl(2^j \bmod (2n+1)\bigr) \bmod 2.
    \]
\end{lemma}
\begin{proof}
    Apply the shifted sum lemma with $f(j) = (2^j \bmod (2n+1)) \bmod 2$. The boundary condition holds because $2^{a(n)} \bmod (2n+1) = 1$ and $2^0 \bmod (2n+1) = 1$, so both parities are 1.
\end{proof}

\begin{lemma}[Summed division algorithm]
    \label{lem:pap_sum_two_mul_residue}
    \lean{sum_two_mul_residue}
    \uses{lem:pap_div_algo_two_mul_residue}
    For $n > 0$,
    \[
        \sum_{j=0}^{a(n)-1} 2 \cdot (2^j \bmod (2n+1))
        = (2n+1) \cdot \sum_{j=0}^{a(n)-1} \Bigl\lfloor \tfrac{2 \cdot (2^j \bmod (2n+1))}{2n+1} \Bigr\rfloor
          + \sum_{j=0}^{a(n)-1} \bigl(2 \cdot (2^j \bmod (2n+1))\bigr) \bmod (2n+1).
    \]
\end{lemma}
\begin{proof}
    Sum the division algorithm identity over $j = 0, \ldots, a(n)-1$, factor the constant $(2n+1)$ out of the first sum, and apply linearity of summation.
\end{proof}

\begin{lemma}[Factor 2 from residue sum]
    \label{lem:pap_sum_two_mul_residue_lhs}
    \lean{sum_two_mul_residue_lhs}
    For all $n : \mathbb{N}$,
    \[
        \sum_{j=0}^{a(n)-1} 2 \cdot (2^j \bmod (2n+1)) = 2 \cdot \sum_{j=0}^{a(n)-1} \bigl(2^j \bmod (2n+1)\bigr).
    \]
\end{lemma}
\begin{proof}
    Factor the constant 2 out of the sum.
\end{proof}

\begin{lemma}[$b(n+1)$ unfolds to parity sum]
    \label{lem:pap_b_unfold}
    \lean{b_unfold}
    For $n \geq 1$,
    \[
        b(n+1) = \sum_{j \in \mathrm{range}(a(n))} \bigl(2^j \bmod (2n+1)\bigr) \bmod 2.
    \]
\end{lemma}
\begin{proof}
    Write $n = k+1$ for $k \geq 0$. Then $n+1 = k+2$, which matches the third pattern branch of the definition of $A179382$, giving the stated sum.
\end{proof}

\begin{lemma}[Quotient sum equals shifted parity sum]
    \label{lem:pap_sum_quotient_eq_sum_parity}
    \lean{sum_quotient_eq_sum_parity}
    \uses{lem:pap_quotient_eq_parity, lem:pap_two_mul_residue_mod}
    For $n > 0$,
    \[
        \sum_{j=0}^{a(n)-1} \Bigl\lfloor \tfrac{2 \cdot (2^j \bmod (2n+1))}{2n+1} \Bigr\rfloor
        = \sum_{j=0}^{a(n)-1} \bigl(2^{j+1} \bmod (2n+1)\bigr) \bmod 2.
    \]
\end{lemma}
\begin{proof}
    For each $j$, apply the quotient-parity lemma and then substitute $(2 \cdot (2^j \bmod (2n+1))) \bmod (2n+1) = 2^{j+1} \bmod (2n+1)$ using the double-residue mod lemma.
\end{proof}

\begin{lemma}[Quotient sum equals $b(n+1)$]
    \label{lem:pap_sum_quotient_eq_b}
    \lean{sum_quotient_eq_b}
    \uses{lem:pap_sum_quotient_eq_sum_parity, lem:pap_sum_parity_shift, lem:pap_b_unfold}
    For $n > 0$,
    \[
        \sum_{j=0}^{a(n)-1} \Bigl\lfloor \tfrac{2 \cdot (2^j \bmod (2n+1))}{2n+1} \Bigr\rfloor = b(n+1).
    \]
\end{lemma}
\begin{proof}
    Chain the equality through the shifted parity sum lemma and the unfolding of $b(n+1)$.
\end{proof}

\begin{lemma}[Double-mod residue sum equals residue sum]
    \label{lem:pap_sum_two_mul_mod_eq_sum_residue}
    \lean{sum_two_mul_mod_eq_sum_residue}
    \uses{lem:pap_two_mul_residue_mod, lem:pap_sum_residue_shift}
    For $n > 0$,
    \[
        \sum_{j=0}^{a(n)-1} \bigl(2 \cdot (2^j \bmod (2n+1))\bigr) \bmod (2n+1)
        = \sum_{j=0}^{a(n)-1} \bigl(2^j \bmod (2n+1)\bigr).
    \]
\end{lemma}
\begin{proof}
    Rewrite each term using the double-residue mod lemma to obtain $\sum 2^{j+1} \bmod (2n+1)$, then apply the shift-invariance of the residue sum.
\end{proof}

\begin{lemma}[Core natural number identity]
    \label{lem:pap_nat_identity}
    \lean{nat_identity}
    \uses{lem:pap_sum_two_mul_residue, lem:pap_sum_two_mul_residue_lhs, lem:pap_sum_quotient_eq_b, lem:pap_sum_two_mul_mod_eq_sum_residue}
    For $n > 0$,
    \[
        (2n+1) \cdot b(n+1) = \sum_{j=0}^{a(n)-1} \bigl(2^j \bmod (2n+1)\bigr).
    \]
\end{lemma}
\begin{proof}
    Set $S = \sum_{j} r_j$ where $r_j = 2^j \bmod (2n+1)$. The summed division algorithm gives $2S = (2n+1) \cdot b(n+1) + S$. Subtracting $S$ from both sides yields the identity.
\end{proof}

\begin{theorem}[Smallest period divisor identity]
    \label{thm:pap_smallest_period_div}
    \lean{smallest_period_div}
    \uses{lem:pap_nat_identity}
    For $n > 0$,
    \[
        \bigl(b(n+1) : \mathbb{R}\bigr)
        = (2n+1)^{-1} \cdot \sum_{j=0}^{a(n)-1} \bigl(2^j \bmod (2n+1)\bigr),
    \]
    where $a(n) = A002326(n) = \inf\{m > 0 : (2n+1) \mid 2^m - 1\}$ and $b = A179382$.
\end{theorem}
\begin{proof}
    From the core natural number identity, $(2n+1) \cdot b(n+1) = \sum r_j$ in $\mathbb{N}$. Cast to $\mathbb{R}$, then divide both sides by the nonzero value $(2n+1 : \mathbb{R})$ using the real cast non-zero lemma.
\end{proof}

