\chapter{Rising Sun Lemma}

This section contains a proof of the Rising Sun Lemma.
See \url{https://en.wikipedia.org/wiki/Rising_sun_lemma} for more details.

\begin{definition}[Shadow set S]
    \label{def:S_def}
    \lean{S}
    For real numbers $a < b$ and a function $g : \mathbb{R} \to \mathbb{R}$, define
    \[
      S(a,b,g) = \{ x \in [a,b] \mid \exists\, y \in [a,b],\; x < y \text{ and } g(x) < g(y) \}.
    \]
\end{definition}

\begin{definition}[Rising set E]
    \label{def:E_def}
    \lean{E}
    \uses{def:S_def}
    Define $E(a,b,g) = (a,b) \cap S(a,b,g)$, the set of points in the open interval $(a,b)$ that are ``shadowed'' from the right.
\end{definition}

\begin{lemma}[E is a subset of the open interval]
    \label{lem:E_subset_Ioo}
    \lean{E_subset_Ioo}
    \uses{def:E_def}
    $E(a,b,g) \subseteq (a,b)$.
\end{lemma}
\begin{proof}
    Immediate from the definition $E = (a,b) \cap S(a,b,g) \subseteq (a,b)$.
\end{proof}

\begin{lemma}[Witness for membership in E]
    \label{lem:E_mem_witness}
    \lean{E_mem_witness}
    \uses{def:E_def}
    If $x \in E(a,b,g)$ then there exists $y \in [a,b]$ with $x < y$ and $g(x) < g(y)$.
\end{lemma}
\begin{proof}
    Direct from the definition: $x \in E$ means $x \in (a,b)$ and $x \in S$, and $x \in S$ gives the desired witness $y$.
\end{proof}

\begin{lemma}[E is open]
    \label{lem:E_isOpen}
    \lean{E_isOpen}
    \uses{def:E_def, lem:E_subset_Ioo}
    If $g$ is continuous and $a < b$, then $E(a,b,g)$ is open.
\end{lemma}
\begin{proof}
    We write $E = \bigcup_{y \in [a,b]} \bigl((a,y) \cap \{x \mid g(x) < g(y)\}\bigr)$.
    Each set $(a,y)$ is open and each preimage $\{x \mid g(x) < g(y)\}$ is open by continuity of $g$.
    A union of open sets is open.
\end{proof}

\begin{lemma}[Nonempty open preconnected bounded subset of R is an open interval]
    \label{lem:open_preconnected_subset_Ioo_eq_Ioo}
    \lean{open_preconnected_subset_Ioo_eq_Ioo}
    If $C \subseteq (a,b)$ is nonempty, open, and preconnected, then $C = (\inf C, \sup C)$.
\end{lemma}
\begin{proof}
    Since $C \subseteq (a,b)$, it is bounded above and below.
    The set $C$ is connected, hence order-connected, so it contains the open interval $(\inf C, \sup C)$.
    For the reverse inclusion, if $\inf C \in C$ then openness gives a point of $C$ strictly below $\inf C$, a contradiction; likewise $\sup C \notin C$.
    Thus $C = (\inf C, \sup C)$.
\end{proof}

\begin{lemma}[Infimum of a component is at least a]
    \label{lem:component_sInf_ge}
    \lean{component_sInf_ge}
    \uses{lem:E_subset_Ioo}
    If $C$ is nonempty and $C \subseteq E(a,b,g)$, then $a \le \inf C$.
\end{lemma}
\begin{proof}
    Every element of $C$ is in $E \subseteq (a,b)$, so every element exceeds $a$. Hence $a \le \inf C$.
\end{proof}

\begin{lemma}[Supremum of a component is at most b]
    \label{lem:component_sSup_le}
    \lean{component_sSup_le}
    \uses{lem:E_subset_Ioo}
    If $C$ is nonempty and $C \subseteq E(a,b,g)$, then $\sup C \le b$.
\end{lemma}
\begin{proof}
    Every element of $C$ is in $E \subseteq (a,b)$, so every element is less than $b$. Hence $\sup C \le b$.
\end{proof}

\begin{lemma}[Infimum strictly less than supremum for nonempty open preconnected bounded set]
    \label{lem:component_sInf_lt_sSup}
    \lean{component_sInf_lt_sSup}
    If $C \subseteq (a,b)$ is nonempty, open, and preconnected, then $\inf C < \sup C$.
\end{lemma}
\begin{proof}
    Take $x \in C$. Since $C$ is open, there is an interval $(l,u) \ni x$ contained in $C$.
    Pick $y \in (x,u) \subset C$ and $z \in (l,x) \subset C$.
    Then $\inf C \le z < y \le \sup C$, giving $\inf C < \sup C$.
\end{proof}

\begin{lemma}[Components of E are countable]
    \label{lem:E_components_countable}
    \lean{E_components_countable}
    \uses{lem:E_isOpen}
    The collection of distinct nonempty connected components of $E(a,b,g)$ is countable.
\end{lemma}
\begin{proof}
    The components are pairwise disjoint (distinct connected components are disjoint) and each is open and nonempty.
    Such a family in the separable space $\mathbb{R}$ is countable.
\end{proof}

\begin{lemma}[E equals the union of its connected components]
    \label{lem:E_eq_iUnion_connectedComponents}
    \lean{E_eq_iUnion_connectedComponents}
    $E(a,b,g) = \bigcup_{x \in E} \mathrm{connectedComponentIn}(E(a,b,g), x)$.
\end{lemma}
\begin{proof}
    Every $x \in E$ belongs to its own connected component, and every connected component is a subset of $E$.
\end{proof}

\begin{lemma}[Right endpoint is not in E]
    \label{lem:right_endpoint_not_in_E}
    \lean{right_endpoint_not_in_E}
    \uses{lem:E_isOpen}
    Let $(c,d)$ be a connected component of $E(a,b,g)$ with $a \le c$, $d \le b$. Then $d \notin E(a,b,g)$.
\end{lemma}
\begin{proof}
    Suppose $d \in E$. Since $E$ is open (Lemma~\ref{lem:E_isOpen}), the connected component of $d$ in $E$ is an open neighborhood of $d$.
    Then the component of any point $m \in (c,d)$ near $d$ would equal the component of $d$, placing $d$ inside the open interval $(c,d)$—a contradiction since $d \notin (c,d)$.
\end{proof}

\begin{lemma}[Right endpoint is not in S when d < b]
    \label{lem:right_endpoint_not_in_S}
    \lean{right_endpoint_not_in_S}
    \uses{lem:right_endpoint_not_in_E, lem:E_subset_Ioo}
    Under the same hypotheses, if $d < b$, then for all $y \in [a,b]$ with $d < y$, $g(d) \ge g(y)$.
\end{lemma}
\begin{proof}
    Since $d \in (a,b)$ (as $d > c \ge a$ and $d < b$) and $d \notin E$ (Lemma~\ref{lem:right_endpoint_not_in_E}), we have $d \notin S$.
    So there is no $y > d$ in $[a,b]$ with $g(d) < g(y)$, i.e., $g(d) \ge g(y)$ for all such $y$.
\end{proof}

\begin{lemma}[Right endpoint dominates to the right]
    \label{lem:right_endpoint_dominates}
    \lean{right_endpoint_dominates}
    \uses{lem:right_endpoint_not_in_S}
    Under the same hypotheses, for all $y \in [d,b]$, $g(d) \ge g(y)$.
\end{lemma}
\begin{proof}
    For $y = d$ the inequality is trivial. For $y > d$, if $d < b$ apply Lemma~\ref{lem:right_endpoint_not_in_S}. If $d = b$ there is no $y \in [d,b]$ with $y > d$, so the result holds vacuously.
\end{proof}

\begin{lemma}[The maximizer on {[x,d]} is the right endpoint d]
    \label{lem:maximizer_eq_right_endpoint}
    \lean{maximizer_eq_right_endpoint}
    \uses{lem:E_mem_witness, lem:right_endpoint_dominates}
    Let $x \in (c,d)$ and let $z \in [x,d]$ be a maximizer of $g$ on $[x,d]$. Then $z = d$.
\end{lemma}
\begin{proof}
    Suppose $z \ne d$, so $z < d$. Then $z \in (c,d) \subseteq E$, so by Lemma~\ref{lem:E_mem_witness} there exists $y \in [a,b]$ with $z < y$ and $g(z) < g(y)$.
    If $y \le d$, this contradicts $z$ being a maximizer on $[x,d]$ (since $y \in [z,d] \subseteq [x,d]$).
    If $y > d$, then $g(d) \ge g(y) > g(z)$ by Lemma~\ref{lem:right_endpoint_dominates}, so $g(d) > g(z)$, contradicting maximality at $z$ since $d \in [x,d]$.
\end{proof}

\begin{lemma}[Property 5: g(x) < g(d) for x in the component]
    \label{lem:g_lt_g_right_endpoint}
    \lean{g_lt_g_right_endpoint}
    \uses{lem:E_mem_witness, lem:maximizer_eq_right_endpoint, lem:right_endpoint_dominates}
    For $x \in (c,d)$, $g(x) < g(d)$.
\end{lemma}
\begin{proof}
    Since $x \in E$, Lemma~\ref{lem:E_mem_witness} gives $y \in [a,b]$ with $x < y$ and $g(x) < g(y)$.
    The extreme value theorem gives a maximizer $z \in [x,d]$ of $g$; by Lemma~\ref{lem:maximizer_eq_right_endpoint}, $z = d$.
    If $y \le d$: $g(x) < g(y) \le g(d)$.
    If $y > d$: $g(x) < g(y) \le g(d)$ by Lemma~\ref{lem:right_endpoint_dominates}.
    In both cases $g(x) < g(d)$.
\end{proof}

\begin{lemma}[Left endpoint is not in E]
    \label{lem:left_endpoint_not_in_E}
    \lean{left_endpoint_not_in_E}
    \uses{lem:E_isOpen}
    Under the same component hypotheses, $c \notin E(a,b,g)$.
\end{lemma}
\begin{proof}
    Suppose $c \in E$. Since $E$ is open (Lemma~\ref{lem:E_isOpen}), the connected component of $c$ contains an open neighborhood of $c$.
    A point $m \in (c, c+\varepsilon)$ in that neighborhood would share the same component as $c$, so the component of $m$ (which equals $(c,d)$) would contain $c$—but $c \notin (c,d)$, a contradiction.
\end{proof}

\begin{lemma}[Left endpoint not in S implies dominance]
    \label{lem:left_not_in_S_imp_ge}
    \lean{left_not_in_S_imp_ge}
    \uses{lem:E_subset_Ioo}
    If $c \ne a$ and $c \notin E$, then for all $y \in [a,b]$ with $c < y$, $g(c) \ge g(y)$.
\end{lemma}
\begin{proof}
    Since $c \ne a$ and $c \in (a, b)$ (as $a \le c < d \le b$ and $c \ne a$), if $c \notin E$ then $c \notin S$.
    So there is no $y > c$ in $[a,b]$ with $g(c) < g(y)$, giving $g(c) \ge g(y)$ for all such $y$.
\end{proof}

\begin{lemma}[g(c) is at least g(d) when c is not a]
    \label{lem:g_left_ge_g_right}
    \lean{g_left_ge_g_right}
    \uses{lem:left_not_in_S_imp_ge}
    If $c \ne a$ and $c \notin E$, then $g(c) \ge g(d)$.
\end{lemma}
\begin{proof}
    Apply Lemma~\ref{lem:left_not_in_S_imp_ge} with $y = d \in [a,b]$ and $c < d$.
\end{proof}

\begin{lemma}[g(c) is at most g(d) by continuity]
    \label{lem:g_left_le_g_right}
    \lean{g_left_le_g_right}
    \uses{lem:g_lt_g_right_endpoint}
    $g(c) \le g(d)$.
\end{lemma}
\begin{proof}
    By Lemma~\ref{lem:g_lt_g_right_endpoint}, $g(x) < g(d)$ for all $x \in (c,d)$.
    By continuity of $g$ at $c$ and the right-limit, $g(c) = \lim_{x \to c^+} g(x) \le g(d)$.
\end{proof}

\begin{lemma}[Property 3: g(c) = g(d) when c is not a]
    \label{lem:left_ne_a_imp_g_eq}
    \lean{left_ne_a_imp_g_eq}
    \uses{lem:left_endpoint_not_in_E, lem:g_left_le_g_right, lem:g_left_ge_g_right}
    If $c \ne a$, then $g(c) = g(d)$.
\end{lemma}
\begin{proof}
    By Lemma~\ref{lem:left_endpoint_not_in_E}, $c \notin E$.
    By Lemma~\ref{lem:g_left_ge_g_right}, $g(c) \ge g(d)$.
    By Lemma~\ref{lem:g_left_le_g_right}, $g(c) \le g(d)$.
    Therefore $g(c) = g(d)$.
\end{proof}

\begin{lemma}[g(a) is at most g(d) by continuity from the right]
    \label{lem:g_a_le_g_right}
    \lean{g_a_le_g_right}
    \uses{lem:g_lt_g_right_endpoint}
    If $c = a$, then $g(a) \le g(d)$.
\end{lemma}
\begin{proof}
    For all $x \in (a,d) = (c,d)$, $g(x) < g(d)$ by Lemma~\ref{lem:g_lt_g_right_endpoint}.
    By continuity of $g$ at $a$ and the right-limit, $g(a) \le g(d)$.
\end{proof}

\begin{lemma}[Property 4: g(a) < g(d) when c = a and a is in S]
    \label{lem:left_eq_a_imp_g_lt}
    \lean{left_eq_a_imp_g_lt}
    \uses{lem:g_lt_g_right_endpoint, lem:g_a_le_g_right, lem:right_endpoint_dominates}
    If $c = a$ and $a \in S(a,b,g)$, then $g(a) < g(d)$.
\end{lemma}
\begin{proof}
    Since $a \in S$, there exists $y \in [a,b]$ with $a < y$ and $g(a) < g(y)$.
    By Lemma~\ref{lem:g_a_le_g_right}, $g(a) \le g(d)$.
    For strict inequality: if $y \le d$, then either $y = d$ giving $g(a) < g(d)$ directly, or $y \in (a,d) = (c,d)$ giving $g(a) < g(y) < g(d)$ by Lemma~\ref{lem:g_lt_g_right_endpoint}.
    If $y > d$, then $g(d) \ge g(y) > g(a)$ by Lemma~\ref{lem:right_endpoint_dominates}.
\end{proof}

\begin{lemma}[Build the collection of component intervals]
    \label{lem:build_component_intervals}
    \lean{build_component_intervals}
    \uses{lem:E_isOpen, lem:open_preconnected_subset_Ioo_eq_Ioo, lem:component_sInf_ge, lem:component_sSup_le, lem:component_sInf_lt_sSup, lem:E_components_countable, lem:E_subset_Ioo, lem:E_eq_iUnion_connectedComponents}
    There exists a countable set $I \subseteq \mathbb{R} \times \mathbb{R}$ of pairs $(c,d)$ with $a \le c < d \le b$, such that the intervals $(c,d)$ are pairwise disjoint, their union equals $E(a,b,g)$, each interval $(c,d) \subseteq E(a,b,g)$, and for each $x \in (c,d)$, the connected component of $x$ in $E$ equals $(c,d)$.
\end{lemma}
\begin{proof}
    For each point $x \in E$, its connected component $C_x = \mathrm{connectedComponentIn}(E, x)$ is nonempty, open, preconnected, and contained in $(a,b)$ (Lemma~\ref{lem:E_subset_Ioo}).
    By Lemma~\ref{lem:open_preconnected_subset_Ioo_eq_Ioo}, $C_x = (\inf C_x, \sup C_x)$.
    The infimum is $\ge a$ (Lemma~\ref{lem:component_sInf_ge}), the supremum is $\le b$ (Lemma~\ref{lem:component_sSup_le}), and $\inf C_x < \sup C_x$ (Lemma~\ref{lem:component_sInf_lt_sSup}).
    Setting $I = \{(\inf C_x, \sup C_x) \mid x \in E\}$, pairwise disjointness follows from distinct components being disjoint, the union property from Lemma~\ref{lem:E_eq_iUnion_connectedComponents}, and countability from Lemma~\ref{lem:E_components_countable}.
\end{proof}

\begin{lemma}[Assemble the enumeration from the component collection]
    \label{lem:risingsun_of_components}
    \lean{risingsun_of_components}
    \uses{lem:build_component_intervals}
    Given a countable pairwise-disjoint collection $I$ of intervals covering $E$, satisfying Properties 3, 4, and 5, there exists $k : \mathbb{N} \to \mathbb{R} \times \mathbb{R}$ enumerating the intervals (with degenerate pairs for unused indices) satisfying all five properties of the Rising Sun Lemma.
\end{lemma}
\begin{proof}
    Since $I$ is countable, it is encodable. Define $k(n)$ to be the $n$-th element of $I$ under the encoding, or the default pair $(a+1, a+1)$ for indices without a preimage.
    Degenerate pairs produce empty intervals, so pairwise disjointness, the union, and the three properties are verified by case analysis on whether $k(n)$ comes from $I$ or is the default.
\end{proof}

\begin{theorem}[Rising Sun Lemma]
    \label{thm:risingsun}
    \lean{risingsun}
    \uses{lem:build_component_intervals, lem:risingsun_of_components, lem:left_ne_a_imp_g_eq, lem:left_eq_a_imp_g_lt, lem:g_lt_g_right_endpoint}
    Let $a < b$ be real numbers and let $g : \mathbb{R} \to \mathbb{R}$ be continuous. With $S(a,b,g)$ and $E(a,b,g)$ as defined above, there exists $k : \mathbb{N} \to \mathbb{R} \times \mathbb{R}$ such that for all $i \ne j$:
    \begin{enumerate}
      \item The intervals $(k(i)_1, k(i)_2)$ and $(k(j)_1, k(j)_2)$ are disjoint.
      \item $E(a,b,g) = \bigcup_n (k(n)_1, k(n)_2)$.
      \item For each $n$, if $k(n)_1 \ne a$ then $g(k(n)_1) = g(k(n)_2)$.
      \item For each $n$, if $k(n)_1 = a$ and $a \in S(a,b,g)$ then $g(a) < g(k(n)_2)$.
      \item For each $n$ and $x \in (k(n)_1, k(n)_2)$, $g(x) < g(k(n)_2)$.
    \end{enumerate}
\end{theorem}
\begin{proof}
    Build the collection $I$ of component intervals using Lemma~\ref{lem:build_component_intervals}.
    Property 3 for each component $(c,d) \in I$ with $c \ne a$ follows from Lemma~\ref{lem:left_ne_a_imp_g_eq}.
    Property 4 for components with $c = a$ follows from Lemma~\ref{lem:left_eq_a_imp_g_lt}.
    Property 5 for each $x \in (c,d)$ follows from Lemma~\ref{lem:g_lt_g_right_endpoint}.
    Assemble the enumeration $k$ using Lemma~\ref{lem:risingsun_of_components}.
\end{proof}

