\chapter{Rouché--Capelli Theorem}

This section contains a proof of the Rouché--Capelli theorem, which characterizes solvability of a linear system $Ax = b$ in terms of matrix ranks.
See \url{https://en.wikipedia.org/wiki/Rouch\%C3\%A9\%E2\%80\%93Capelli_theorem} for background.

\begin{definition}[System of Linear Equations]
    \label{def:SystemOfLinearEquations}
    \lean{SystemOfLinearEquations}
    A system of $m$ linear equations in $n$ unknowns is a pair $(A, b)$ where $A$ is an $m \times n$
    coefficient matrix over a field $K$ and $b : \mathrm{Fin}\,m \to K$ is the constant vector.
\end{definition}

\begin{definition}[Augmented Matrix]
    \label{def:AugmentedMatrix}
    \lean{AugmentedMatrix}
    \uses{def:SystemOfLinearEquations}
    For a system $(A, b)$, the augmented matrix $[A \mid b]$ is the $m \times (n+1)$ matrix whose
    first $n$ columns are those of $A$ and whose last column is $b$.
\end{definition}

\begin{definition}[Column Space]
    \label{def:ColumnSpace}
    \lean{ColumnSpace}
    The column space of an $m \times n$ matrix $A$ over a field $K$ is the submodule
    $\mathrm{span}_K\bigl(\mathrm{range}(\lambda j.\,A^T j)\bigr)$ of $K^m$.
\end{definition}

\begin{definition}[Matrix Rank]
    \label{def:MatrixRank}
    \lean{MatrixRank}
    \uses{def:ColumnSpace}
    The rank of a matrix $A$ is the $K$-dimension of its column space:
    $\mathrm{rank}(A) = \mathrm{finrank}_K(\mathrm{ColumnSpace}(A))$.
\end{definition}

\begin{lemma}[mulVec as Linear Combination]
    \label{lem:mulVec_as_linear_combination}
    \lean{mulVec_as_linear_combination}
    For any matrix $A$ and vector $x$, the matrix-vector product $A \cdot x$ equals
    $\sum_{j} x_j \cdot A^T j$, i.e.\ scalar multiples of the transpose rows.
\end{lemma}
\begin{proof}
    Rewrite the matrix vector multiplication as a sum and observe that
    $\mathrm{MulOpposite.op}(x_j) \cdot A^T j = x_j \cdot A^T j$
    because $K$ is a commutative field.
\end{proof}

\begin{lemma}[Solvability as Column Space Membership]
    \label{lem:solvability_as_column_space_membership}
    \lean{solvability_as_column_space_membership}
    \uses{def:ColumnSpace, lem:mulVec_as_linear_combination}
    The system $Ax = b$ has a solution if and only if $b \in \mathrm{ColumnSpace}(A)$.
\end{lemma}
\begin{proof}
    Apply the fact that an element lies in the span iff it can be written as sum over that span.
    which gives $b \in \mathrm{span}_K(\mathrm{range}(A^T))$ iff there exist coefficients
    $c_j$ with $\sum_j c_j \cdot A^T j = b$. Both directions then follow from
    Lemma~\ref{lem:mulVec_as_linear_combination} identifying $A \cdot x$ with $\sum_j x_j \cdot A^T j$.
\end{proof}

\begin{lemma}[Augmented Range Subset]
    \label{lem:augmented_range_subset}
    \lean{augmented_range_subset}
    \uses{def:AugmentedMatrix, def:SystemOfLinearEquations}
    The range of the transpose columns of the augmented matrix is contained in
    the range of the transpose columns of $A$ union $\{b\}$.
\end{lemma}
\begin{proof}
    Every column of $[A \mid b]^T$ is either a column of $A^T$ (for non-last indices) or equals $b$.
    Apply \texttt{Fin.lastCases} to split on these two cases.
\end{proof}

\begin{lemma}[Augmented Range Superset]
    \label{lem:augmented_range_superset}
    \lean{augmented_range_superset}
    \uses{def:AugmentedMatrix, def:SystemOfLinearEquations}
    The range of transpose columns of $A$ union $\{b\}$ is contained in
    the range of transpose columns of the augmented matrix.
\end{lemma}
\begin{proof}
    Each column of $A$ appears in $[A \mid b]^T$ at a cast index, and $b$ appears at the last index.
\end{proof}

\begin{lemma}[Augmented Column Space Equality]
    \label{lem:augmented_column_space_eq}
    \lean{augmented_column_space_eq}
    \uses{def:ColumnSpace, def:AugmentedMatrix, def:SystemOfLinearEquations, lem:augmented_range_subset, lem:augmented_range_superset}
    The column space of the augmented matrix equals
    $\mathrm{span}_K\bigl(\mathrm{range}(A^T) \cup \{b\}\bigr)$.
\end{lemma}
\begin{proof}
    By \texttt{Submodule.span\_mono} applied to Lemma~\ref{lem:augmented_range_subset} and
    Lemma~\ref{lem:augmented_range_superset}, the two spans are each contained in the other,
    so they are equal by antisymmetry.
\end{proof}

\begin{lemma}[Column Space Monotone under Augmentation]
    \label{lem:column_space_le_augmented}
    \lean{column_space_le_augmented}
    \uses{def:ColumnSpace, def:AugmentedMatrix, def:SystemOfLinearEquations}
    The column space of $A$ is a subspace of the column space of the augmented matrix:
    $\mathrm{ColumnSpace}(A) \le \mathrm{ColumnSpace}([A \mid b])$.
\end{lemma}
\begin{proof}
    Apply \texttt{Submodule.span\_mono}: every generator $A^T j$ of $\mathrm{ColumnSpace}(A)$
    appears as $([A \mid b])^T(\mathrm{castSucc}(j))$,
    so the generator set is included.
\end{proof}

\begin{lemma}[b Lies in Augmented Column Space]
    \label{lem:b_mem_augmented_column_space}
    \lean{b_mem_augmented_column_space}
    \uses{def:ColumnSpace, def:AugmentedMatrix, def:SystemOfLinearEquations}
    The vector $b$ belongs to the column space of the augmented matrix.
\end{lemma}
\begin{proof}
    We have $b = ([A \mid b])^T(\mathrm{last}\,n)$,
    so $b$ lies in the range of the transpose columns of $[A \mid b]$ and hence in
    $\mathrm{ColumnSpace}([A \mid b])$ by \texttt{Submodule.subset\_span}.
\end{proof}

\begin{lemma}[Column Space of Augmented Matrix when b in ColumnSpace A]
    \label{lem:column_space_augmented_of_mem}
    \lean{column_space_augmented_of_mem}
    \uses{def:ColumnSpace, def:AugmentedMatrix, def:SystemOfLinearEquations, lem:augmented_column_space_eq}
    If $b \in \mathrm{ColumnSpace}(A)$, then $\mathrm{ColumnSpace}([A \mid b]) = \mathrm{ColumnSpace}(A)$.
\end{lemma}
\begin{proof}
    By Lemma~\ref{lem:augmented_column_space_eq},
    $\mathrm{ColumnSpace}([A \mid b]) = \mathrm{span}_K(\mathrm{range}(A^T) \cup \{b\})$.
    Since $b \in \mathrm{ColumnSpace}(A) = \mathrm{span}_K(\mathrm{range}(A^T))$,
    The fact that adding an element of the span does not increase the span gives
    $\mathrm{span}_K(\mathrm{range}(A^T) \cup \{b\}) = \mathrm{span}_K(\mathrm{range}(A^T)) = \mathrm{ColumnSpace}(A)$.
\end{proof}

\begin{lemma}[Rank Equality from Column Space Membership (Forward)]
    \label{lem:rank_eq_of_mem_column_space}
    \lean{rank_eq_of_mem_column_space}
    \uses{def:MatrixRank, lem:column_space_augmented_of_mem}
    If $b \in \mathrm{ColumnSpace}(A)$, then $\mathrm{rank}(A) = \mathrm{rank}([A \mid b])$.
\end{lemma}
\begin{proof}
    Apply Lemma~\ref{lem:column_space_augmented_of_mem}:
    since $\mathrm{ColumnSpace}([A \mid b]) = \mathrm{ColumnSpace}(A)$, their finranks are equal.
\end{proof}

\begin{lemma}[Column Space Equality from Rank Equality]
    \label{lem:column_space_eq_of_rank_eq}
    \lean{column_space_eq_of_rank_eq}
    \uses{def:MatrixRank, lem:column_space_le_augmented}
    If $\mathrm{rank}(A) = \mathrm{rank}([A \mid b])$, then $\mathrm{ColumnSpace}(A) = \mathrm{ColumnSpace}([A \mid b])$.
\end{lemma}
\begin{proof}
    By Lemma~\ref{lem:column_space_le_augmented} and the equal finranks these are equal.
\end{proof}

\begin{lemma}[Column Space Membership from Rank Equality (Backward)]
    \label{lem:mem_column_space_of_rank_eq}
    \lean{mem_column_space_of_rank_eq}
    \uses{lem:column_space_eq_of_rank_eq, lem:b_mem_augmented_column_space}
    If $\mathrm{rank}(A) = \mathrm{rank}([A \mid b])$, then $b \in \mathrm{ColumnSpace}(A)$.
\end{lemma}
\begin{proof}
    By Lemma~\ref{lem:column_space_eq_of_rank_eq}, $\mathrm{ColumnSpace}(A) = \mathrm{ColumnSpace}([A \mid b])$.
    By Lemma~\ref{lem:b_mem_augmented_column_space}, $b \in \mathrm{ColumnSpace}([A \mid b])$,
    so $b \in \mathrm{ColumnSpace}(A)$ after rewriting.
\end{proof}

\begin{lemma}[Rank Equality Condition]
    \label{lem:rank_equality_condition}
    \lean{rank_equality_condition}
    \uses{lem:rank_eq_of_mem_column_space, lem:mem_column_space_of_rank_eq}
    $b \in \mathrm{ColumnSpace}(A)$ if and only if $\mathrm{rank}(A) = \mathrm{rank}([A \mid b])$.
\end{lemma}
\begin{proof}
    This follows from Lemma~\ref{lem:rank_eq_of_mem_column_space} (forward direction) and
    Lemma~\ref{lem:mem_column_space_of_rank_eq} (backward direction).
\end{proof}

\begin{theorem}[Rouché--Capelli]
    \label{thm:rouche_capelli}
    \lean{rouche_capelli}
    \uses{lem:solvability_as_column_space_membership, lem:rank_equality_condition}
    A system of linear equations $Ax = b$ is consistent (has at least one solution) if and only if
    $\mathrm{rank}(A) = \mathrm{rank}([A \mid b])$.
\end{theorem}
\begin{proof}
    Chain the two equivalences:
    \begin{align*}
        (\exists x,\, Ax = b)
        &\iff b \in \mathrm{ColumnSpace}(A)
            && \text{(Lemma~\ref{lem:solvability_as_column_space_membership})} \\
        &\iff \mathrm{rank}(A) = \mathrm{rank}([A \mid b])
            && \text{(Lemma~\ref{lem:rank_equality_condition})}
    \end{align*}
\end{proof}

\chapter{Schur's theorem}

This section contains a (stub of a) proof of Schur's theorem.
See \url{https://en.wikipedia.org/wiki/Schur's_theorem} for more details.


\begin{theorem}[Ramsey's theorem for monochromatic triangles]
  \label{thm:ramsey}
  \lean{ramsey}
  For any positive integer \(r\), there exists a positive integer \(n_r\) such that for every \(r\)-coloring of the edges of the complete graph \(K_{n_r}\), there exists a monochromatic triangle.
\end{theorem}

\begin{proof}
  We proceed by induction on \(r\).
  For \(r = 1\), we have \(n_r = 3\) since a single color will always yield a monochromatic triangle in \(K_3\).
  Given $n_r$ such that for every \(r\)-coloring of the edges of \(K_{n_r}\), there exists a monochromatic triangle, consider \(n_{r+1} = TODO \). Let $c$ be an \((r+1)\)-coloring of the edges of \(K_{n_{r+1}}\).
  Consider an arbitrary vertex $x$ of this graph, and let \(A_i\) be the set of vertices connected to this vertex by edges of color \(i\) for \(i = 1, 2, \ldots, r+1\).
  There exists an index \(i\) such that \(|A_i| \geq n_r\).
  Because otherwise, we would have \(|A_1| + |A_2| + \cdots + |A_{r+1}| \leq (r+1) n_r\), which contradicts the fact that the total number of vertices is \((r+1) n_r + 1\).
  Either
  \begin{itemize}
    \item Of the edges between the vertices in \(A_i\), at least of them is colored \(i\), in which case we have a monochromatic triangle formed by the vertex $x$ and the endpoints of that edge, or
    \item All the edges between the vertices in \(A_i\) are colored with the $n$ colors different from \(i\), in which case we have a monochromatic triangle in the subgraph induced by \(A_i\) by the induction hypothesis.
  \end{itemize}
\end{proof}

\begin{theorem}[Schur's theorem]
  \label{thm:schur}
  \lean{schur}
  \uses{thm:ramsey}
  For any positive integer \(r\), there exists a positive integer \(n_r\) such that for every \(r\)-coloring of the set \(\{1, 2, \ldots, n_r\}\), there exist three integers \(x, y, z\) of the same color such that \(x + y = z\).
\end{theorem}

\begin{proof}
  Consider $n_r$ as in the previous theorem. We define $c$ to be an \(r\)-coloring of the edge set of the complete graph on \(\{1, 2, \ldots, n_r\}\), where the color of the edge \(\{x, y\}\) is the color of the integer \(|x - y|\).
  By the previous theorem, there exist three vertices \(a < b < c\) such that the edges \(\{a, b\}\), \(\{b, c\}\), and \(\{a, c\}\) are of the same color.
  This means that the integers \(x = b - a\), \(y = c - b\), and \(z = c - a\) are of the same color, and we have \((b - a) + (c - b) = c - a\).
\end{proof}

\chapter{Sinkhorn's theorem}

This section contains a proof of Sinkhorn's theorem.
See \url{https://en.wikipedia.org/wiki/Sinkhorn's_theorem} for more details.

\begin{theorem}
  \label{thm:sinkhorn_uniqueness}
  \lean{sinkhorn_uniqueness}
  Suppose that $A$ is an $N \times N$ matrix $A$ with all positive entries. Suppose there are
  $d_1, d_2, d'_1, d'_2 \in \mathbb{R}^N$ all have positive entries such that
  $\mathrm{diag}(d_1) * A * \mathrm{diag}(d_2)$ and $\mathrm{diag}(d'_1) * A * \mathrm{diag}(d'_2)$ are both doubly stochastic.
  Then there is a constant $c > 0$ such that $d'_1 = c * d_1$ and $d'_2 = d_2 / c$.
\end{theorem}
\begin{proof}
  Let $P = \mathrm{diag}(d_1) * A * \mathrm{diag}(d_2)$. Let $b_1 = d_1'/d_1$ and $b_2 = d_2'/d_2$ where division is coordinate-wise. Then both $P$ and $\mathrm{diag}(b_1) * A * \mathrm{diag}(b_2)$ are doubly stochastic.
  For each $i$, $1/b_{1i}$ is a convex combination of the entries of $b_2$. So
  \begin{displaymath}
    \min(b_2) \leq 1/b_{1i} \leq \max(b_2).
  \end{displaymath}
  Similarly, for any $j$,
  \begin{displaymath}
    \min(b_1) \leq 1/b_{2j} \leq \max(b_1).
  \end{displaymath}
  Let $\min(b_1) = b_{1i_0}$ and $\max(b_2) = b_{2j_0}$. Then we must have $b_{1i_0}b_{2j_0}=1$.
  Again since $1/b_{1i_0}$ is a convex combination of the entries of $b_2$, every $b_{2j}$ must be equal to $b_{2j_0} = 1/b_{1i_0}$. Similarly, every $b_{1i}$ must be equal to $b_{1i_0}$.
  Let $c = b_{11}$. Then $c$ satisfies the conclusion of the lemma.
\end{proof}

\begin{definition}
  \label{def:RCseq}
  \lean{RCseq}
  Given an $N \times N$ matrix $A$ with all positive entries, we define the row-column normalization sequence,
  \begin{displaymath}
    \mathrm{RCseq}(A):\mathbb{N} \to \mathbb{R}^N \times \mathbb{R}^N,
  \end{displaymath}
  by recursion.
  \begin{enumerate}
    \item $\mathrm{RCseq}(A)(0) = (1_N, \mathrm{colSum}(A)^{-1})$, where $1_N = (1, \dots, 1)$
      denotes the vector with all-one entries, $\mathrm{colSum}(A)$ denotes the vector consisting
      of all the column sums of $A$, $x^{-1}$ denotes $(x_1^{-1}, \dots, x_N^{-1})$ for
      $x = (x_1, \dots, x_N) \in \mathbb{R}^N$.
    \item Suppose that $\mathrm{RCseq}(A)(n) = (d, e)$ has been defined. Let
      $A' = \mathrm{diag}(d) * A * \mathrm{diag}(e)$. Let $d' = \mathrm{rowSum}(A')^{-1}$ where
      $\mathrm{rowSum}(A')$ denotes the vector consisting of all the row sums of $A'$. Let
      $e' = \mathrm{colSum}(\mathrm{diag}(d') * A')^{-1}$.
      Then $\mathrm{RCseq}(A)(n+1) = (d' * d, e * e')$, where $*$ denotes pointwise multiplication.
  \end{enumerate}
\end{definition}

\begin{definition}
  \label{def:RCseqLeft}
  \lean{RCseqLeft}
  \uses{def:RCseq}
  For $n \in \mathbb{N}$, $\mathrm{RCseqLeft}(A)(n)$ denotes the left component of
  $\mathrm{RCseq}(A)(n)$, i.e.,
  \begin{displaymath}
    \mathrm{RCseq}(A)(n) = (\mathrm{RCseqLeft}(A)(n), \mathrm{RCseqRight}(A)(n)).
  \end{displaymath}
\end{definition}

\begin{definition}
  \label{def:RCseqRight}
  \lean{RCseqRight}
  \uses{def:RCseq}
  For $n \in \mathbb{N}$, $\mathrm{RCseqRight}(A)(n)$ denotes the right component of
  $\mathrm{RCseq}(A)(n)$, i.e.,
  \begin{displaymath}
    \mathrm{RCseq}(A)(n) = (\mathrm{RCseqLeft}(A)(n), \mathrm{RCseqRight}(A)(n)).
  \end{displaymath}
\end{definition}

\begin{definition}
  \label{def:colOneSeq}
  \lean{colOneSeq}
  \uses{def:RCseqLeft}
  \uses{def:RCseqRight}
  For $n \in \mathbb{N}$, define
  \begin{displaymath}
    \mathrm{colOneSeq}(A)(n) = \mathrm{diag}(\mathrm{RCseqLeft(A)(n)}) * A * \mathrm{diag}(\mathrm{RCseqRight(A)(n)}).
  \end{displaymath}
\end{definition}

\begin{definition}
  \label{def:rowOneSeq}
  \lean{rowOneSeq}
  \uses{def:RCseqLeft}
  \uses{def:RCseqRight}
  For $n \in \mathbb{N}$, define
  \begin{displaymath}
    \mathrm{rowOneSeq}(A)(n) = \mathrm{diag}(\mathrm{RCseqLeft(A)(n+1)}) * A * \mathrm{diag}(\mathrm{RCseqRight(A)(n)}).
  \end{displaymath}
\end{definition}

\begin{definition}
  \label{def:rowSums}
  \lean{rowSums}
  \uses{def:colOneSeq}
  For $n \in \mathbb{N}$, define
  \begin{displaymath}
    \mathrm{rowSums}(A)(n) = \mathrm{rowSum}(\mathrm{colOneSeq}(A)(n)),
  \end{displaymath}
  the vector of row sums of $\mathrm{colOneSeq}(A)(n)$.
\end{definition}

\begin{definition}
  \label{def:colSums}
  \lean{colSums}
  \uses{def:rowOneSeq}
  For $n \in \mathbb{N}$, define
  \begin{displaymath}
    \mathrm{colSums}(A)(n) = \mathrm{colSum}(\mathrm{rowOneSeq}(A)(n)),
  \end{displaymath}
  the vector of column sums of $\mathrm{rowOneSeq}(A)(n)$.
\end{definition}

\begin{lemma}
  \label{lem:colSum_one}
  \lean{colSum_one}
  \uses{def:colOneSeq}
  Suppose that $A$ is an $N \times N$ matrix $A$ with all positive entries.
  Then for any $n$, $\mathrm{colSum}(\mathrm{colOneSeq}(A)(n)) = 1_N$.
\end{lemma}
\begin{proof}
  Simply unravel the definitions.
\end{proof}

\begin{lemma}
  \label{lem:rowSum_one}
  \lean{rowSum_one}
  \uses{def:rowOneSeq}
  Suppose that $A$ is an $N \times N$ matrix $A$ with all positive entries.
  Then for any $n$, $\mathrm{rowSum}(\mathrm{rowOneSeq}(A)(n)) = 1_N$.
\end{lemma}
\begin{proof}
  Simply unravel the definitions.
\end{proof}

\begin{lemma}
  \label{lem:colOne_to_rowOne}
  \lean{colOne_to_rowOne}
  \uses{def:colOneSeq}
  \uses{def:rowOneSeq}
  \uses{def:rowSums}
  Suppose that $A$ is an $N \times N$ matrix $A$ with all positive entries.
  Then $\mathrm{rowOneSeq}(A)(n) = \mathrm{diag}(\mathrm{rowSums}(A)(n)^{-1}) * \mathrm{colOneSeq}(A)(n)$.
\end{lemma}
\begin{proof}
  Simply unravel the definitions.
\end{proof}

\begin{lemma}
  \label{lem:rowOne_to_colOne}
  \lean{rowOne_to_colOne}
  \uses{def:colOneSeq}
  \uses{def:rowOneSeq}
  \uses{def:colSums}
  Suppose that $A$ is an $N \times N$ matrix $A$ with all positive entries.
  Then $\mathrm{colOneSeq}(A)(n+1) = \mathrm{diag}(\mathrm{colSums}(A)(n)^{-1}) * \mathrm{rowOneSeq}(A)(n)$.
\end{lemma}
\begin{proof}
  Simply unravel the definitions.
\end{proof}

\begin{lemma}
  \label{lem:rowSums_colSums_bound}
  \lean{rowSums_colSums_bound}
  \uses{def:rowSums}
  \uses{def:colSums}
  \uses{lem:colSum_one}
  \uses{lem:rowSum_one}
  Suppose that $A$ is an $N \times N$ matrix $A$ with all positive entries.
  Let $\min(\cdot)$ and $\max(\cdot)$ denote the minimum and maximum entry of a vector in $\mathbb{R}^N$, respectively. Then
  \begin{displaymath}
    \min(\mathrm{rowSums}(A)(n)) \leq 1 \leq \max(\mathrm{rowSums}(A)(n))
  \end{displaymath}
  and
  \begin{displaymath}
    \min(\mathrm{colSums}(A)(n)) \leq 1 \leq \max(\mathrm{colSums}(A)(n)).
  \end{displaymath}
\end{lemma}
\begin{proof}
  The first one follows from
  \begin{displaymath}
    \sum_{i=1}^N \mathrm{rowSums}(A)(n)_i = \sum_{i=1}^N \mathrm{colSums}(A)(n)_i = \sum_{i=1}^N 1 = N
  \end{displaymath}
  where the second equality follows from~\ref{lem:colSum_one}.
  Similarly for the second, using~\ref{lem:rowSum_one}.
\end{proof}

\begin{lemma}
  \label{lem:rowSums_colSums_min_max_monotone_antitone}
  \lean{rowSums_colSums_min_max_monotone_antitone}
  \uses{def:rowSums}
  \uses{def:colSums}
  \uses{lem:colSum_one}
  \uses{lem:rowSum_one}
  \uses{lem:colOne_to_rowOne}
  \uses{lem:rowOne_to_colOne}
  Suppose that $A$ is an $N \times N$ matrix $A$ with all positive entries.
  Then the functions $n \mapsto \min(\mathrm{rowSums}(A)(n))$ and $n \mapsto \min(\mathrm{colSums}(A)(n))$ are increasing. The functions $n \mapsto \max(\mathrm{rowSums}(A)(n))$ and $n \mapsto \max(\mathrm{colSums}(A)(n))$ are decreasing.
\end{lemma}
\begin{proof}
  By Lemmas~\ref{lem:colSum_one} and~\ref{lem:colOne_to_rowOne}, every entry of
  $\mathrm{colSums}(A)(n)$ is a convex combination of the entries of $rowSums(A)(n)^{-1}$.
  By Lemmas~\ref{lem:rowSum_one} and~\ref{lem:rowOne_to_colOne}, every entry of
  $\mathrm{rowSums}(A)(n+1)$ is a convex combination of the entries of $colSums(A)(n)^{-1}$.
  Therefore, every entry of $\mathrm{rowSums}(A)(n+1)$ must be in between
  $\min(\mathrm{rowSums}(A)(n))$ and $\max(\mathrm{rowSums}(A)(n))$.

  By Lemmas~\ref{lem:rowSum_one} and~\ref{lem:rowOne_to_colOne}, every entry of
  $\mathrm{rowSums}(A)(n+1)$ is a convex combination of the entries of $colSums(A)(n)^{-1}$.
  By Lemmas~\ref{lem:colSum_one} and~\ref{lem:colOne_to_rowOne}, every entry of
  $\mathrm{colSums}(A)(n+1)$ is a convex combination of the entries of $rowSums(A)(n+1)^{-1}$.
  Therefore, every entry of $\mathrm{colSums}(A)(n+1)$ must be in between
  $\min(\mathrm{colSums}(A)(n))$ and $\max(\mathrm{colSums}(A)(n))$.
\end{proof}

\begin{lemma}
  \label{lem:entry_lower_bound}
  \lean{entry_lower_bound}
  \uses{def:colOneSeq}
  \uses{def:RCseqLeft}
  \uses{def:RCseqRight}
  \uses{def:rowSums}
  \uses{lem:colSum_one}
  \uses{lem:rowSums_colSums_min_max_monotone_antitone}
  Suppose that $A$ is an $N \times N$ matrix $A$ with all positive entries.
  Then there is a fixed $\mu > 0$ such that for every $n$, every entry of $\mathrm{colOneSeq}(A)(n)$
  is $\geq \mu$.
\end{lemma}
\begin{proof}
  Let $A = (a_ij)$ and let $a$ be its minimal entry. Let $x_n = RCseqLeft(A)(n)$ and let
  $y_n = RCseqRight(A)(n)$.
  Let $\lambda_n = \mathrm{rowSums}(A)(n)$. Let $\lambda = \min(\lambda_1)$. By
  Lemma~\ref{lem:rowSums_colSums_min_max_monotone_antitone}, $\lambda \leq \lambda_{n,i}$.
  By Lemma~\ref{lem:colSum_one}, $\sum_i x_{ni}a_{ij}y_{nj} = 1$. So
  \begin{displaymath}
    y_nj = 1 / \sum_i a_{ij}x_{ni} \leq 1 / a_{ij}x_{ni} \leq 1 / a x_{ni}
  \end{displaymath}
  for all $i, j$. Thus, in particular $y_{nj} \leq 1 / a \max (x_n)$.
  Since
  \begin{displaymath}
    \sum_j x_{ni} a_{ij} y_{nj} = \lambda_{n,i} \geq \lambda,
  \end{displaymath}
  it follows that
  \begin{displaymath}
    x_{n,i} \geq \lambda / \sum_j a_{ij} y_{nj} \geq a \lambda \max(x_n) / N.
  \end{displaymath}
  Also $y_{n,j} = 1 / \sum_i a_{ij}x_{ni} \geq 1 / N \max(x_n)$ and we see that
  \begin{displaymath}
    \mathrm{colOneSeq}(A)(n)_ij = x_{ni} a_{ij} y_{nj} \geq a \lambda / N^2.
  \end{displaymath}
  We set $\mu = a \lambda / N^2$ and every entry of $\mathrm{colOneSeq}(A)(n)$ is therefore
  $\geq \mu$.
\end{proof}

\begin{lemma}
  \label{lem:colSums_tendsTo_one}
  \lean{colSums_tendsTo_one}
  \uses{def:colSums}
  \uses{def:rowSums}
  \uses{def:colOneSeq}
  \uses{lem:rowSums_colSums_bound}
  \uses{lem:rowSums_colSums_min_max_monotone_antitone}
  \uses{lem:entry_lower_bound}
  Suppose that $A$ is an $N \times N$ matrix $A$ with all positive entries.
  Then $\lim_{n \to \infty} \mathrm{colSums}(A)(n) = 1_N$.
\end{lemma}
\begin{proof}
  Let $\lambda_n = \mathrm{colSums}(A)(n)$ and $\delta_n = \mathrm{rowSums}(A)(n)$.
  By Lemmas~\ref{lem:rowSums_colSums_bound} and~\ref{lem:rowSums_colSums_min_max_monotone_antitone},
  $\max(\lambda_n) \to 1 + c$ where $c \geq 0$. Set $\max(\lambda_n) = 1 + c_n$.
  For any $j$, set $\mu_j = \sum_{i : \lambda_{ni} \leq 1} colOneSeq(A)(n)_{ij}$ and set
  $\mu_j' = \sum_{i : \lambda_{ni} > 1} colOneSeq(A)(n)_{ij}$. Then
  \begin{displaymath}
    \delta_{nj} \geq \mu_j + \frac{1}{1 + c_n} \mu_j' = \frac{1 + c_n \mu_j}{1 + c_n} \geq
    \frac{1 + c_n a_n}{1 + c_n}
  \end{displaymath}
  where $a_n$ denotes the minimum entry of $\mathrm{colSums}(A)(n)$. Then if
  $\max(\lambda_{n+1})=\lambda_{n+1, \lambda_0}$,
  \begin{displaymath}
    1 + c \leq \lambda_{n+1, i_0} = \sum_j \mathrm{rowSums}(A)(n)_{i_0j}/\lambda_{ni_0}\delta_{nj}
    \leq (1 + c_n) / (1 + c_n a_n).
  \end{displaymath}
  If $c > 0$, then
  \begin{displaymath}
    (1 + c_n)/(1 + c_n a_n) \leq (1 + c_n) / (1 + c \mu)
  \end{displaymath}
  where $\mu$ is obtained from Lemma~\ref{lem:entry_lower_bound}.
  So $1 + c \leq (1 + c_n) / (1 + c \mu)$ and by taking limit $n \to \infty$, we get a contradiction.
  Thus $c=0$ and $\max(\lambda_n) \to 1$. Since $\sum_i \lambda_{n,i} = N$, $\lambda_n \to 1_N$.
\end{proof}


\begin{lemma}
  \label{lem:rowSums_tendsTo_one}
  \lean{rowSums_tendsTo_one}
  \uses{def:rowSums}
  \uses{lem:rowSum_one}
  \uses{lem:rowOne_to_colOne}
  \uses{lem:colSums_tendsTo_one}
  Suppose that $A$ is an $N \times N$ matrix $A$ with all positive entries.
  Then $\lim_{n \to \infty} \mathrm{rowSums}(A)(n) = 1_N$.
\end{lemma}
\begin{proof}
  By Lemmas~\ref{lem:rowSum_one} and~\ref{lem:rowOne_to_colOne}, every entry of
  $\mathrm{rowSums}(A)(n+1)$ is a convex combination of the entries of $colSums(A)(n)^{-1}$.
  The lemma thus follows from Lemma~\ref{lem:colSums_tendsTo_one},
\end{proof}

\begin{lemma}
  \label{lem:rescale}
  \lean{rescale}
  Suppose that $A$ is an $N \times N$ matrix $A$ with all positive entries.
  Suppose that $x_n, y_n \in \mathbb{R}^N$ for $n \in \mathbb{N}$ are vectors with all positive
  entries.
  Suppose that for any $i, j$, $x_{n, i} y_{n, j}$ converges to a positive limit.
  Then there exists $x'_n, y'_n \in \mathbb{R}^N$ such that for any $i, j$,
  $x'_{n,i}y'_{n,j} = x_{n,i}y_{n,j}$ for any $n$ and both
  $x'_{n,i}, y'_{n,j}$ converge to positive limits.
\end{lemma}
\begin{proof}
  Let $x'_{n,i} = x_{n,i} / x_{n,1}$ and $y'_{n,j} = y_{n,j} x_{n,1}$.
  Then $x'_{n,i}y'_{n,j} = x_{n,i}y_{n,j}$.
  $y'_{n,j}$ converges to a positive limit by assumption.
  Since $x'_{n,i} = x_{n,i}y_{n,1} / x_{n,1}y_{n,1}$ and both $x_{n,i}y_{n,1}$ and $x_{n,1}y_{n,1}$
  converge to a positive limit by assumption, $x'_{n,i}$ also converge to a positive limit.
\end{proof}

\begin{theorem}
  \label{thm:sinkhorn_existence}
  \lean{sinkhorn_existence}
  \uses{def:colOneSeq}
  \uses{def:RCseqLeft}
  \uses{def:RCseqRight}
  \uses{def:rowSums}
  \uses{lem:colSum_one}
  \uses{lem:rescale}
  \uses{lem:entry_lower_bound}
  \uses{lem:rowSums_tendsTo_one}
  \uses{thm:sinkhorn_uniqueness}
  Suppose that $A$ is an $N \times N$ matrix $A$ with all positive entries. Then there are
  $d_1, d_2 \in \mathbb{R}^N$ with all positive entries such that $\mathrm{diag}(d_1) * A * \mathrm{diag}(d_2)$ is
  doubly stochastic.
\end{theorem}
\begin{proof}
  Let $\mu>0$ be obtained from Lemma~\ref{lem:entry_lower_bound}. Then for every $n$, every entry of $\mathrm{colOneSeq}(A)(n)$ is $\geq \mu$. Also by Lemma~\ref{lem:colSum_one}, every entry of $\mathrm{colOneSeq}(A)(n)$ is $\leq 1$.
  Let $x_n = RCseqLeft(A)(n)$ and $y_n = RCseqRight(A)(n)$. Then for each $i,j$, $x_{n,i}y_{n,j}$
  is bounded and has a positive lower bound. By compactness, there is a subsequence
  $(x_{n_k}, y_{n_k})_k$ such that each $x_{n_k,i}y_{n_k,j}$ converges to a positive limit.
  By Lemma~\ref{lem:rescale}, there is $(x'_{k}, y'_{k})_k$ such that
  $x'_{ki}y'_{kj} = x_{n_k,i}y_{n_k,j}$ and $d_1, d_2 \in \mathbb{R}^N$ such that $d_1, d_2$
  have positive entries and $(x'_k, y'_k) \to (d_1, d_2)$.
  Let $A = (a_ij)$.
  The sum of the $i$th row of $\mathrm{diag}(d_1) * A * \mathrm{diag}(d_2)$ is
  \begin{displaymath}
    \sum_i d_{1i} a_{ij} d_{2j} = \lim_{k \to \infty} \sum_i x'_{ki} a_{ij} y'_{kj}
      = \lim_{k \to \infty} \sum_i x_{n_k,i} a_{ij} y_{n_k,j}
      = \lim_{k \to \infty} \mathrm{rowSums}(A)(n_k)_i = 1
  \end{displaymath}
  where the last equality follows from Lemma~\ref{lem:colSums_tendsTo_one}.
  Similarly, every column sum of $\mathrm{diag}(d_1) * A * \mathrm{diag}(d_2)$ is 1 using
  Lemma~\ref{lem:rowSums_tendsTo_one}.
\end{proof}

\chapter{Sinkhorn's theorem}

This section contains a proof of Sinkhorn's theorem.
See \url{https://en.wikipedia.org/wiki/Sinkhorn's_theorem} for more details.

\begin{theorem}
  \label{thm:sinkhorn_uniqueness}
  \lean{sinkhorn_uniqueness}
  Suppose that $A$ is an $N \times N$ matrix $A$ with all positive entries. Suppose there are
  $d_1, d_2, d'_1, d'_2 \in \mathbb{R}^N$ all have positive entries such that
  $\mathrm{diag}(d_1) * A * \mathrm{diag}(d_2)$ and $\mathrm{diag}(d'_1) * A * \mathrm{diag}(d'_2)$ are both doubly stochastic.
  Then there is a constant $c > 0$ such that $d'_1 = c * d_1$ and $d'_2 = d_2 / c$.
\end{theorem}
\begin{proof}
  Let $P = \mathrm{diag}(d_1) * A * \mathrm{diag}(d_2)$. Let $b_1 = d_1'/d_1$ and $b_2 = d_2'/d_2$ where division is coordinate-wise. Then both $P$ and $\mathrm{diag}(b_1) * A * \mathrm{diag}(b_2)$ are doubly stochastic.
  For each $i$, $1/b_{1i}$ is a convex combination of the entries of $b_2$. So
  \begin{displaymath}
    \min(b_2) \leq 1/b_{1i} \leq \max(b_2).
  \end{displaymath}
  Similarly, for any $j$,
  \begin{displaymath}
    \min(b_1) \leq 1/b_{2j} \leq \max(b_1).
  \end{displaymath}
  Let $\min(b_1) = b_{1i_0}$ and $\max(b_2) = b_{2j_0}$. Then we must have $b_{1i_0}b_{2j_0}=1$.
  Again since $1/b_{1i_0}$ is a convex combination of the entries of $b_2$, every $b_{2j}$ must be equal to $b_{2j_0} = 1/b_{1i_0}$. Similarly, every $b_{1i}$ must be equal to $b_{1i_0}$.
  Let $c = b_{11}$. Then $c$ satisfies the conclusion of the lemma.
\end{proof}

\begin{definition}
  \label{def:RCseq}
  \lean{RCseq}
  Given an $N \times N$ matrix $A$ with all positive entries, we define the row-column normalization sequence,
  \begin{displaymath}
    \mathrm{RCseq}(A):\mathbb{N} \to \mathbb{R}^N \times \mathbb{R}^N,
  \end{displaymath}
  by recursion.
  \begin{enumerate}
    \item $\mathrm{RCseq}(A)(0) = (1_N, \mathrm{colSum}(A)^{-1})$, where $1_N = (1, \dots, 1)$
      denotes the vector with all-one entries, $\mathrm{colSum}(A)$ denotes the vector consisting
      of all the column sums of $A$, $x^{-1}$ denotes $(x_1^{-1}, \dots, x_N^{-1})$ for
      $x = (x_1, \dots, x_N) \in \mathbb{R}^N$.
    \item Suppose that $\mathrm{RCseq}(A)(n) = (d, e)$ has been defined. Let
      $A' = \mathrm{diag}(d) * A * \mathrm{diag}(e)$. Let $d' = \mathrm{rowSum}(A')^{-1}$ where
      $\mathrm{rowSum}(A')$ denotes the vector consisting of all the row sums of $A'$. Let
      $e' = \mathrm{colSum}(\mathrm{diag}(d') * A')^{-1}$.
      Then $\mathrm{RCseq}(A)(n+1) = (d' * d, e * e')$, where $*$ denotes pointwise multiplication.
  \end{enumerate}
\end{definition}

\begin{definition}
  \label{def:RCseqLeft}
  \lean{RCseqLeft}
  \uses{def:RCseq}
  For $n \in \mathbb{N}$, $\mathrm{RCseqLeft}(A)(n)$ denotes the left component of
  $\mathrm{RCseq}(A)(n)$, i.e.,
  \begin{displaymath}
    \mathrm{RCseq}(A)(n) = (\mathrm{RCseqLeft}(A)(n), \mathrm{RCseqRight}(A)(n)).
  \end{displaymath}
\end{definition}

\begin{definition}
  \label{def:RCseqRight}
  \lean{RCseqRight}
  \uses{def:RCseq}
  For $n \in \mathbb{N}$, $\mathrm{RCseqRight}(A)(n)$ denotes the right component of
  $\mathrm{RCseq}(A)(n)$, i.e.,
  \begin{displaymath}
    \mathrm{RCseq}(A)(n) = (\mathrm{RCseqLeft}(A)(n), \mathrm{RCseqRight}(A)(n)).
  \end{displaymath}
\end{definition}

\begin{definition}
  \label{def:colOneSeq}
  \lean{colOneSeq}
  \uses{def:RCseqLeft}
  \uses{def:RCseqRight}
  For $n \in \mathbb{N}$, define
  \begin{displaymath}
    \mathrm{colOneSeq}(A)(n) = \mathrm{diag}(\mathrm{RCseqLeft(A)(n)}) * A * \mathrm{diag}(\mathrm{RCseqRight(A)(n)}).
  \end{displaymath}
\end{definition}

\begin{definition}
  \label{def:rowOneSeq}
  \lean{rowOneSeq}
  \uses{def:RCseqLeft}
  \uses{def:RCseqRight}
  For $n \in \mathbb{N}$, define
  \begin{displaymath}
    \mathrm{rowOneSeq}(A)(n) = \mathrm{diag}(\mathrm{RCseqLeft(A)(n+1)}) * A * \mathrm{diag}(\mathrm{RCseqRight(A)(n)}).
  \end{displaymath}
\end{definition}

\begin{definition}
  \label{def:rowSums}
  \lean{rowSums}
  \uses{def:colOneSeq}
  For $n \in \mathbb{N}$, define
  \begin{displaymath}
    \mathrm{rowSums}(A)(n) = \mathrm{rowSum}(\mathrm{colOneSeq}(A)(n)),
  \end{displaymath}
  the vector of row sums of $\mathrm{colOneSeq}(A)(n)$.
\end{definition}

\begin{definition}
  \label{def:colSums}
  \lean{colSums}
  \uses{def:rowOneSeq}
  For $n \in \mathbb{N}$, define
  \begin{displaymath}
    \mathrm{colSums}(A)(n) = \mathrm{colSum}(\mathrm{rowOneSeq}(A)(n)),
  \end{displaymath}
  the vector of column sums of $\mathrm{rowOneSeq}(A)(n)$.
\end{definition}

\begin{lemma}
  \label{lem:colSum_one}
  \lean{colSum_one}
  \uses{def:colOneSeq}
  Suppose that $A$ is an $N \times N$ matrix $A$ with all positive entries.
  Then for any $n$, $\mathrm{colSum}(\mathrm{colOneSeq}(A)(n)) = 1_N$.
\end{lemma}
\begin{proof}
  Simply unravel the definitions.
\end{proof}

\begin{lemma}
  \label{lem:rowSum_one}
  \lean{rowSum_one}
  \uses{def:rowOneSeq}
  Suppose that $A$ is an $N \times N$ matrix $A$ with all positive entries.
  Then for any $n$, $\mathrm{rowSum}(\mathrm{rowOneSeq}(A)(n)) = 1_N$.
\end{lemma}
\begin{proof}
  Simply unravel the definitions.
\end{proof}

\begin{lemma}
  \label{lem:colOne_to_rowOne}
  \lean{colOne_to_rowOne}
  \uses{def:colOneSeq}
  \uses{def:rowOneSeq}
  \uses{def:rowSums}
  Suppose that $A$ is an $N \times N$ matrix $A$ with all positive entries.
  Then $\mathrm{rowOneSeq}(A)(n) = \mathrm{diag}(\mathrm{rowSums}(A)(n)^{-1}) * \mathrm{colOneSeq}(A)(n)$.
\end{lemma}
\begin{proof}
  Simply unravel the definitions.
\end{proof}

\begin{lemma}
  \label{lem:rowOne_to_colOne}
  \lean{rowOne_to_colOne}
  \uses{def:colOneSeq}
  \uses{def:rowOneSeq}
  \uses{def:colSums}
  Suppose that $A$ is an $N \times N$ matrix $A$ with all positive entries.
  Then $\mathrm{colOneSeq}(A)(n+1) = \mathrm{diag}(\mathrm{colSums}(A)(n)^{-1}) * \mathrm{rowOneSeq}(A)(n)$.
\end{lemma}
\begin{proof}
  Simply unravel the definitions.
\end{proof}

\begin{lemma}
  \label{lem:rowSums_colSums_bound}
  \lean{rowSums_colSums_bound}
  \uses{def:rowSums}
  \uses{def:colSums}
  \uses{lem:colSum_one}
  \uses{lem:rowSum_one}
  Suppose that $A$ is an $N \times N$ matrix $A$ with all positive entries.
  Let $\min(\cdot)$ and $\max(\cdot)$ denote the minimum and maximum entry of a vector in $\mathbb{R}^N$, respectively. Then
  \begin{displaymath}
    \min(\mathrm{rowSums}(A)(n)) \leq 1 \leq \max(\mathrm{rowSums}(A)(n))
  \end{displaymath}
  and
  \begin{displaymath}
    \min(\mathrm{colSums}(A)(n)) \leq 1 \leq \max(\mathrm{colSums}(A)(n)).
  \end{displaymath}
\end{lemma}
\begin{proof}
  The first one follows from
  \begin{displaymath}
    \sum_{i=1}^N \mathrm{rowSums}(A)(n)_i = \sum_{i=1}^N \mathrm{colSums}(A)(n)_i = \sum_{i=1}^N 1 = N
  \end{displaymath}
  where the second equality follows from~\ref{lem:colSum_one}.
  Similarly for the second, using~\ref{lem:rowSum_one}.
\end{proof}

\begin{lemma}
  \label{lem:rowSums_colSums_min_max_monotone_antitone}
  \lean{rowSums_colSums_min_max_monotone_antitone}
  \uses{def:rowSums}
  \uses{def:colSums}
  \uses{lem:colSum_one}
  \uses{lem:rowSum_one}
  \uses{lem:colOne_to_rowOne}
  \uses{lem:rowOne_to_colOne}
  Suppose that $A$ is an $N \times N$ matrix $A$ with all positive entries.
  Then the functions $n \mapsto \min(\mathrm{rowSums}(A)(n))$ and $n \mapsto \min(\mathrm{colSums}(A)(n))$ are increasing. The functions $n \mapsto \max(\mathrm{rowSums}(A)(n))$ and $n \mapsto \max(\mathrm{colSums}(A)(n))$ are decreasing.
\end{lemma}
\begin{proof}
  By Lemmas~\ref{lem:colSum_one} and~\ref{lem:colOne_to_rowOne}, every entry of
  $\mathrm{colSums}(A)(n)$ is a convex combination of the entries of $rowSums(A)(n)^{-1}$.
  By Lemmas~\ref{lem:rowSum_one} and~\ref{lem:rowOne_to_colOne}, every entry of
  $\mathrm{rowSums}(A)(n+1)$ is a convex combination of the entries of $colSums(A)(n)^{-1}$.
  Therefore, every entry of $\mathrm{rowSums}(A)(n+1)$ must be in between
  $\min(\mathrm{rowSums}(A)(n))$ and $\max(\mathrm{rowSums}(A)(n))$.

  By Lemmas~\ref{lem:rowSum_one} and~\ref{lem:rowOne_to_colOne}, every entry of
  $\mathrm{rowSums}(A)(n+1)$ is a convex combination of the entries of $colSums(A)(n)^{-1}$.
  By Lemmas~\ref{lem:colSum_one} and~\ref{lem:colOne_to_rowOne}, every entry of
  $\mathrm{colSums}(A)(n+1)$ is a convex combination of the entries of $rowSums(A)(n+1)^{-1}$.
  Therefore, every entry of $\mathrm{colSums}(A)(n+1)$ must be in between
  $\min(\mathrm{colSums}(A)(n))$ and $\max(\mathrm{colSums}(A)(n))$.
\end{proof}

\begin{lemma}
  \label{lem:entry_lower_bound}
  \lean{entry_lower_bound}
  \uses{def:colOneSeq}
  \uses{def:RCseqLeft}
  \uses{def:RCseqRight}
  \uses{def:rowSums}
  \uses{lem:colSum_one}
  \uses{lem:rowSums_colSums_min_max_monotone_antitone}
  Suppose that $A$ is an $N \times N$ matrix $A$ with all positive entries.
  Then there is a fixed $\mu > 0$ such that for every $n$, every entry of $\mathrm{colOneSeq}(A)(n)$
  is $\geq \mu$.
\end{lemma}
\begin{proof}
  Let $A = (a_ij)$ and let $a$ be its minimal entry. Let $x_n = RCseqLeft(A)(n)$ and let
  $y_n = RCseqRight(A)(n)$.
  Let $\lambda_n = \mathrm{rowSums}(A)(n)$. Let $\lambda = \min(\lambda_1)$. By
  Lemma~\ref{lem:rowSums_colSums_min_max_monotone_antitone}, $\lambda \leq \lambda_{n,i}$.
  By Lemma~\ref{lem:colSum_one}, $\sum_i x_{ni}a_{ij}y_{nj} = 1$. So
  \begin{displaymath}
    y_nj = 1 / \sum_i a_{ij}x_{ni} \leq 1 / a_{ij}x_{ni} \leq 1 / a x_{ni}
  \end{displaymath}
  for all $i, j$. Thus, in particular $y_{nj} \leq 1 / a \max (x_n)$.
  Since
  \begin{displaymath}
    \sum_j x_{ni} a_{ij} y_{nj} = \lambda_{n,i} \geq \lambda,
  \end{displaymath}
  it follows that
  \begin{displaymath}
    x_{n,i} \geq \lambda / \sum_j a_{ij} y_{nj} \geq a \lambda \max(x_n) / N.
  \end{displaymath}
  Also $y_{n,j} = 1 / \sum_i a_{ij}x_{ni} \geq 1 / N \max(x_n)$ and we see that
  \begin{displaymath}
    \mathrm{colOneSeq}(A)(n)_ij = x_{ni} a_{ij} y_{nj} \geq a \lambda / N^2.
  \end{displaymath}
  We set $\mu = a \lambda / N^2$ and every entry of $\mathrm{colOneSeq}(A)(n)$ is therefore
  $\geq \mu$.
\end{proof}

\begin{lemma}
  \label{lem:colSums_tendsTo_one}
  \lean{colSums_tendsTo_one}
  \uses{def:colSums}
  \uses{def:rowSums}
  \uses{def:colOneSeq}
  \uses{lem:rowSums_colSums_bound}
  \uses{lem:rowSums_colSums_min_max_monotone_antitone}
  \uses{lem:entry_lower_bound}
  Suppose that $A$ is an $N \times N$ matrix $A$ with all positive entries.
  Then $\lim_{n \to \infty} \mathrm{colSums}(A)(n) = 1_N$.
\end{lemma}
\begin{proof}
  Let $\lambda_n = \mathrm{colSums}(A)(n)$ and $\delta_n = \mathrm{rowSums}(A)(n)$.
  By Lemmas~\ref{lem:rowSums_colSums_bound} and~\ref{lem:rowSums_colSums_min_max_monotone_antitone},
  $\max(\lambda_n) \to 1 + c$ where $c \geq 0$. Set $\max(\lambda_n) = 1 + c_n$.
  For any $j$, set $\mu_j = \sum_{i : \lambda_{ni} \leq 1} colOneSeq(A)(n)_{ij}$ and set
  $\mu_j' = \sum_{i : \lambda_{ni} > 1} colOneSeq(A)(n)_{ij}$. Then
  \begin{displaymath}
    \delta_{nj} \geq \mu_j + \frac{1}{1 + c_n} \mu_j' = \frac{1 + c_n \mu_j}{1 + c_n} \geq
    \frac{1 + c_n a_n}{1 + c_n}
  \end{displaymath}
  where $a_n$ denotes the minimum entry of $\mathrm{colSums}(A)(n)$. Then if
  $\max(\lambda_{n+1})=\lambda_{n+1, \lambda_0}$,
  \begin{displaymath}
    1 + c \leq \lambda_{n+1, i_0} = \sum_j \mathrm{rowSums}(A)(n)_{i_0j}/\lambda_{ni_0}\delta_{nj}
    \leq (1 + c_n) / (1 + c_n a_n).
  \end{displaymath}
  If $c > 0$, then
  \begin{displaymath}
    (1 + c_n)/(1 + c_n a_n) \leq (1 + c_n) / (1 + c \mu)
  \end{displaymath}
  where $\mu$ is obtained from Lemma~\ref{lem:entry_lower_bound}.
  So $1 + c \leq (1 + c_n) / (1 + c \mu)$ and by taking limit $n \to \infty$, we get a contradiction.
  Thus $c=0$ and $\max(\lambda_n) \to 1$. Since $\sum_i \lambda_{n,i} = N$, $\lambda_n \to 1_N$.
\end{proof}


\begin{lemma}
  \label{lem:rowSums_tendsTo_one}
  \lean{rowSums_tendsTo_one}
  \uses{def:rowSums}
  \uses{lem:rowSum_one}
  \uses{lem:rowOne_to_colOne}
  \uses{lem:colSums_tendsTo_one}
  Suppose that $A$ is an $N \times N$ matrix $A$ with all positive entries.
  Then $\lim_{n \to \infty} \mathrm{rowSums}(A)(n) = 1_N$.
\end{lemma}
\begin{proof}
  By Lemmas~\ref{lem:rowSum_one} and~\ref{lem:rowOne_to_colOne}, every entry of
  $\mathrm{rowSums}(A)(n+1)$ is a convex combination of the entries of $colSums(A)(n)^{-1}$.
  The lemma thus follows from Lemma~\ref{lem:colSums_tendsTo_one},
\end{proof}

\begin{lemma}
  \label{lem:rescale}
  \lean{rescale}
  Suppose that $A$ is an $N \times N$ matrix $A$ with all positive entries.
  Suppose that $x_n, y_n \in \mathbb{R}^N$ for $n \in \mathbb{N}$ are vectors with all positive
  entries.
  Suppose that for any $i, j$, $x_{n, i} y_{n, j}$ converges to a positive limit.
  Then there exists $x'_n, y'_n \in \mathbb{R}^N$ such that for any $i, j$,
  $x'_{n,i}y'_{n,j} = x_{n,i}y_{n,j}$ for any $n$ and both
  $x'_{n,i}, y'_{n,j}$ converge to positive limits.
\end{lemma}
\begin{proof}
  Let $x'_{n,i} = x_{n,i} / x_{n,1}$ and $y'_{n,j} = y_{n,j} x_{n,1}$.
  Then $x'_{n,i}y'_{n,j} = x_{n,i}y_{n,j}$.
  $y'_{n,j}$ converges to a positive limit by assumption.
  Since $x'_{n,i} = x_{n,i}y_{n,1} / x_{n,1}y_{n,1}$ and both $x_{n,i}y_{n,1}$ and $x_{n,1}y_{n,1}$
  converge to a positive limit by assumption, $x'_{n,i}$ also converge to a positive limit.
\end{proof}

\begin{theorem}
  \label{thm:sinkhorn_existence}
  \lean{sinkhorn_existence}
  \uses{def:colOneSeq}
  \uses{def:RCseqLeft}
  \uses{def:RCseqRight}
  \uses{def:rowSums}
  \uses{lem:colSum_one}
  \uses{lem:rescale}
  \uses{lem:entry_lower_bound}
  \uses{lem:rowSums_tendsTo_one}
  \uses{thm:sinkhorn_uniqueness}
  Suppose that $A$ is an $N \times N$ matrix $A$ with all positive entries. Then there are
  $d_1, d_2 \in \mathbb{R}^N$ with all positive entries such that $\mathrm{diag}(d_1) * A * \mathrm{diag}(d_2)$ is
  doubly stochastic.
\end{theorem}
\begin{proof}
  Let $\mu>0$ be obtained from Lemma~\ref{lem:entry_lower_bound}. Then for every $n$, every entry of $\mathrm{colOneSeq}(A)(n)$ is $\geq \mu$. Also by Lemma~\ref{lem:colSum_one}, every entry of $\mathrm{colOneSeq}(A)(n)$ is $\leq 1$.
  Let $x_n = RCseqLeft(A)(n)$ and $y_n = RCseqRight(A)(n)$. Then for each $i,j$, $x_{n,i}y_{n,j}$
  is bounded and has a positive lower bound. By compactness, there is a subsequence
  $(x_{n_k}, y_{n_k})_k$ such that each $x_{n_k,i}y_{n_k,j}$ converges to a positive limit.
  By Lemma~\ref{lem:rescale}, there is $(x'_{k}, y'_{k})_k$ such that
  $x'_{ki}y'_{kj} = x_{n_k,i}y_{n_k,j}$ and $d_1, d_2 \in \mathbb{R}^N$ such that $d_1, d_2$
  have positive entries and $(x'_k, y'_k) \to (d_1, d_2)$.
  Let $A = (a_ij)$.
  The sum of the $i$th row of $\mathrm{diag}(d_1) * A * \mathrm{diag}(d_2)$ is
  \begin{displaymath}
    \sum_i d_{1i} a_{ij} d_{2j} = \lim_{k \to \infty} \sum_i x'_{ki} a_{ij} y'_{kj}
      = \lim_{k \to \infty} \sum_i x_{n_k,i} a_{ij} y_{n_k,j}
      = \lim_{k \to \infty} \mathrm{rowSums}(A)(n_k)_i = 1
  \end{displaymath}
  where the last equality follows from Lemma~\ref{lem:colSums_tendsTo_one}.
  Similarly, every column sum of $\mathrm{diag}(d_1) * A * \mathrm{diag}(d_2)$ is 1 using
  Lemma~\ref{lem:rowSums_tendsTo_one}.
\end{proof}

\chapter{Star of David theorem}

This section contains a proof of the Star of David theorem for binomial coefficients.
See \url{https://en.wikipedia.org/wiki/Star_of_David_theorem} for more details.

For all $n, k \in \mathbb{N}$,
\[
  \gcd\bigl(\gcd\bigl(\binom{n-1}{k-1},\, \binom{n}{k+1}\bigr),\, \binom{n+1}{k}\bigr)
  \;=\;
  \gcd\bigl(\gcd\bigl(\binom{n-1}{k},\, \binom{n}{k-1}\bigr),\, \binom{n+1}{k+1}\bigr).
\]

\section{Edge Cases}

\begin{lemma}[Edge case $n=0$]
  \label{lem:starofdavid_n_zero}
  \lean{starofdavid_n_zero}
  For all $k$, the identity holds when $n = 0$.
\end{lemma}

\begin{proof}
  This follows by case-splitting on $k = 0, 1, \ge 2$ and using direct computation or the fact that $\binom{0}{m} = 0$ for $m \ge 1$.
\end{proof}

\begin{lemma}[Edge case $k=0$]
  \label{lem:starofdavid_k_zero}
  \lean{starofdavid_k_zero}
  For all $n$, the identity holds when $k = 0$, since $\binom{n}{0} = 1$ and $\binom{n}{1} = n$.
\end{lemma}

\begin{proof}
  This follows by case splitting on $n=0$: When $n=0$ this follows by direct computation; when $n \ge 1$ this follows from standard binomial identities.
\end{proof}

\section{Main Case Setup}

Write $n = m+1$, $k = j+1$ so all $\mathbb{N}$-subtractions are clean. Define:
\begin{align*}
  a &= \binom{m}{j}, &
  b &= \binom{m+1}{j+2}, &
  c &= \binom{m+2}{j+1}, \\
  d &= \binom{m}{j+1}, &
  e &= \binom{m+1}{j}, &
  f &= \binom{m+2}{j+2}, \\
  M &= \binom{m+1}{j+1} = a + d.
\end{align*}
The LHS is $g = \gcd(a, b, c)$ and the RHS is $h = \gcd(d, e, f)$.

\section{Product Identity}

\begin{lemma}[Product identity]
  \label{lem:product_identity}
  \lean{product_identity}
  $a \cdot b \cdot c = d \cdot e \cdot f$.
\end{lemma}

\begin{proof}
  Multiply both sides by $(j+1)(j+2)$ and use the absorption identity to rewrite, then cancel. The out-of-range case ($j+1 > m$) follows since both sides are zero.
\end{proof}

\section{Key Identities}

The proof uses equational reasoning over the following standard identities:

\begin{itemize}
  \item \textbf{Absorption:} $(n+1) \cdot \binom{n}{k} = \binom{n+1}{k+1} \cdot (k+1)$
  \item \textbf{Pascal:} $\binom{n+1}{k+1} = \binom{n}{k} + \binom{n}{k+1}$
  \item \textbf{Absorption relation:} $(m - j) \cdot \binom{m}{j} = (j+1) \cdot \binom{m}{j+1}$
\end{itemize}

\section{Divisibility: \texorpdfstring{$g \mid d$}{g | d}}

\begin{lemma}[$g$ divides $d+e$]
  \label{lem:gcd_abc_dvd_d_plus_e}
  \lean{gcd_abc_dvd_d_plus_e}
  $g \mid (d + e)$.
\end{lemma}

\begin{proof}
  Rewrite $c = a + d + e$ via Pascal's rule. Then note $g \mid c$, $g \mid a$.
\end{proof}

\begin{lemma}[$g$ divides $d$ --- key lemma]
  \label{lem:gcd_abc_dvd_d}
  \lean{gcd_abc_dvd_d}
  \uses{lem:product_identity, lem:gcd_abc_dvd_d_plus_e}
  $\gcd(a, b, c) \mid d$.
\end{lemma}

\begin{proof}
  Reduce to showing $p^k \mid d$ for each prime power $p^k$ dividing $g$. From the absorption identities: $p^k \mid (j+1)d$, $p^k \mid (m+1)d$, and $p^k \mid (m+2)e$. Since $p$ cannot divide both $m+1$ and $m+2$, at least one of these coefficients is coprime to $p$, allowing cancellation.
\end{proof}

\section{Symmetric Divisibility: \texorpdfstring{$h \mid a$}{h | a}}

\begin{lemma}[$h$ divides $a$]
  \label{lem:gcd_def_dvd_a}
  \lean{gcd_def_dvd_a}
  \uses{lem:product_identity}
  $\gcd(d, e, f) \mid a$, by the symmetric prime-power argument.
\end{lemma}

\begin{proof}
  Same structure as Lemma~\ref{lem:gcd_abc_dvd_d}, using $h \mid (m-j)a$, $h \mid (m+1)a$, and $h \mid (m+2)a$ derived from the absorption identities.
\end{proof}

\section{Assembly}

\begin{lemma}[$g \mid h$]
  \label{lem:gcd_abc_dvd_gcd_def}
  \lean{gcd_abc_dvd_gcd_def}
  \uses{lem:gcd_abc_dvd_d}
  $g \mid \gcd(d,e,f) = h$.
\end{lemma}

\begin{proof}
  From $g \mid d$, derive $g \mid e$ (via $g \mid d+e$) and $g \mid f$ (via $f = a + d + b$).
\end{proof}

\begin{lemma}[$h \mid g$]
  \label{lem:gcd_def_dvd_gcd_abc}
  \lean{gcd_def_dvd_gcd_abc}
  \uses{lem:gcd_def_dvd_a}
  $h \mid \gcd(a,b,c) = g$.
\end{lemma}

\begin{proof}
  From $h \mid a$, derive $h \mid b$ (via $h \mid a+b$) and $h \mid c$ (via $c = e + a + d$).
\end{proof}

\section{Main Theorem}

\begin{theorem}[Star of David]
  \label{thm:starofdavid}
  \lean{starofdavid}
  \uses{lem:starofdavid_n_zero, lem:starofdavid_k_zero, lem:gcd_abc_dvd_gcd_def, lem:gcd_def_dvd_gcd_abc}
  For all $n, k \in \mathbb{N}$,
  \[
    \gcd(\gcd(\binom{n-1}{k-1}, \binom{n}{k+1}), \binom{n+1}{k})
    = \gcd(\gcd(\binom{n-1}{k}, \binom{n}{k-1}), \binom{n+1}{k+1}).
  \]
\end{theorem}

\begin{proof}
  Edge cases $n=0$ and $k=0$ by Lemmas~\ref{lem:starofdavid_n_zero} and~\ref{lem:starofdavid_k_zero}. For $n = m+1$, $k = j+1$: mutual divisibility $g \mid h$ and $h \mid g$ (Lemmas~\ref{lem:gcd_abc_dvd_gcd_def} and~\ref{lem:gcd_def_dvd_gcd_abc}) gives $g = h$ by antisymmetry of divisibility.
\end{proof}

