\chapter{Valuation Ring Intersected with Subfield (Stacks 052L)}

This section contains a proof of the fact about valuation rings intersected with a subfield.
See \url{https://stacks.math.columbia.edu/tag/052L} for more details.

\begin{lemma}[Subfield membership from multiplication]
\label{lem:subfield_mem_of_mul_eq}
\lean{Subfield.mem_of_mul_eq}
\leanok
If $a, b \in K$ for a subfield $K \subseteq L$ with $a \neq 0$ and $a \cdot x = b$, then $x \in K$.
\end{lemma}

\begin{proof}
\leanok
We have $x = a^{-1} b$, and subfields are closed under inversion and multiplication.
\end{proof}

\begin{lemma}[Divisibility lifts to the intersection]
\label{lem:dvd_inf_of_dvd_in_subring}
\lean{dvd_inf_of_dvd_in_subring}
\leanok
Let $B$ be a subring of a field $L$ and $K$ a subfield. If $a, b \in K \cap B$ and $a \mid b$ in $B$, then $a \mid b$ in $K \cap B$.
\end{lemma}

\begin{proof}
\leanok
\uses{lem:subfield_mem_of_mul_eq}
Let $c \in B$ satisfy $b = ac$. If $a = 0$ then $b = 0$ and divisibility is trivial. If $a \neq 0$, then $c = a^{-1}b \in K$ by Lemma~\ref{lem:subfield_mem_of_mul_eq}, so $c \in K \cap B$ and witnesses divisibility in the intersection.
\end{proof}

\begin{theorem}[Valuation Ring $\cap$ Subfield (Stacks 052L)]
\label{thm:valuation_ring_inter_subfield}
\lean{ValuationRing.inter_subfield}
\leanok
Let $K \subseteq L$ be a field extension and $B$ a subring of $L$ that is a valuation ring. Then $A = K \cap B$ is a valuation ring.
\end{theorem}

\begin{proof}
\leanok
\uses{lem:dvd_inf_of_dvd_in_subring}
By \texttt{ValuationRing.iff\_dvd\_total}, it suffices to show dvd-totality in $K \cap B$. Given $a, b \in K \cap B$, dvd-totality in $B$ gives $a \mid b$ or $b \mid a$ in $B$. In either case, Lemma~\ref{lem:dvd_inf_of_dvd_in_subring} lifts the divisibility to $K \cap B$.
\end{proof}

\chapter{Vantieghem's Theorem}

This section contains a proof of Vantieghem's theorem.
See \url{https://en.wikipedia.org/wiki/Vantieghem%27s_theorem} for more details.

\begin{lemma}[Square less than power for large values]
    \label{lem:vantieghem_sq_lt_pow}
    \lean{Vantieghem.sq_lt_pow_of_ge_five}
    For all $d \geq 5$, $d^2 < 2^d$.
\end{lemma}
\begin{proof}
    By induction on $d$. The base case $d = 5$ is $25 < 32$. For the inductive step, if
    $n^2 < 2^n$ and $n \geq 5$, then $(n+1)^2 = n^2 + 2n + 1 \leq 2n^2 < 2 \cdot 2^n = 2^{n+1}$,
    using $2n + 1 \leq n^2$ which holds for $n \geq 5$.
\end{proof}

\begin{lemma}[Product at least $n$]
    \label{lem:vantieghem_prod_ge_n}
    \lean{Vantieghem.prod_ge_n}
    For $n \geq 3$, $n \leq \prod_{k=1}^{n-1}(2^k - 1)$.
\end{lemma}
\begin{proof}
    By induction on $n$. For $n = 3$ the product is $1 \cdot 3 = 3$, which equals $n$. For the
    inductive step from $m$ to $m+1$ (with $m \geq 3$), the new factor $2^m - 1 \geq 2$ (since
    $m \geq 3$ gives $2^m \geq 4$), and the existing product is at least $m$, so the new product
    is at least $2m \geq m + 1$.
\end{proof}

\begin{lemma}[GCD of Mersenne-like numbers with prime exponent]
    \label{lem:vantieghem_gcd_mersenne_prime}
    \lean{Vantieghem.gcd_mersenne_prime}
    If $n$ is prime and $1 \leq r < n$, then $\gcd(2^r - 1,\, 2^n - 1) = 1$.
\end{lemma}
\begin{proof}
    By the identity $\gcd(2^r - 1, 2^n - 1) = 2^{\gcd(r,n)} - 1$. Since $n$ is prime and
    $1 \leq r < n$, we have $\gcd(r, n) = 1$, so $\gcd(2^r - 1, 2^n - 1) = 2^1 - 1 = 1$.
\end{proof}

\begin{lemma}[$2^n = 1$ in $\mathbb{Z}/(2^n-1)\mathbb{Z}$]
    \label{lem:vantieghem_two_pow_eq_one_zmod}
    \lean{Vantieghem.two_pow_eq_one_zmod}
    For $n \geq 1$, $(2 : \mathrm{ZMod}\,(2^n - 1))^n = 1$.
\end{lemma}
\begin{proof}
    This follows from the fact that $2^n - 1 \mid 2^n - 1$, translating to
    $2^n \equiv 1 \pmod{2^n - 1}$ in $\mathrm{ZMod}$.
\end{proof}

\begin{lemma}[Powers of two are roots of $X^n - 1$]
    \label{lem:vantieghem_root_of_xn_sub_one}
    \lean{Vantieghem.root_of_xn_sub_one}
    \uses{lem:vantieghem_two_pow_eq_one_zmod}
    For $n \geq 1$ and $k < n$, $((2 : \mathrm{ZMod}\,(2^n-1))^k)^n = 1$.
\end{lemma}
\begin{proof}
    Rewrite $((2^k)^n) = (2^n)^k = 1^k = 1$ using the fact that $2^n = 1$ in $\mathrm{ZMod}\,(2^n-1)$.
\end{proof}

\begin{lemma}[Powers of two are pairwise distinct in $\mathrm{ZMod}$]
    \label{lem:vantieghem_powers_of_two_distinct_zmod}
    \lean{Vantieghem.powers_of_two_distinct_zmod}
    \uses{lem:vantieghem_gcd_mersenne_prime}
    If $n$ is prime and $a, b < n$ with $2^a \equiv 2^b \pmod{2^n - 1}$, then $a = b$.
\end{lemma}
\begin{proof}
    Assume without loss of generality $a < b$ and set $r = b - a$, so $1 \leq r < n$.
    From $2^a \equiv 2^b$, cancelling $2^a$ (coprime to $2^n - 1$ since $2^n - 1$ is odd)
    gives $1 \equiv 2^r$, so $2^n - 1 \mid 2^r - 1$. But $\gcd(2^r - 1, 2^n - 1) = 1$ by the
    Mersenne GCD lemma, forcing $2^n - 1 = 1$, contradicting $n \geq 2$.
\end{proof}

\begin{lemma}[Key integer congruence for the forward direction]
    \label{lem:vantieghem_key_int_congruence}
    \lean{Vantieghem.key_int_congruence}
    \uses{lem:vantieghem_powers_of_two_distinct_zmod, lem:vantieghem_root_of_xn_sub_one, lem:vantieghem_two_pow_eq_one_zmod}
    For $n \geq 3$ prime, $(2^n - 1) \mid \prod_{k=1}^{n-1}(1 - 2^k) - n$ in $\mathbb{Z}$.
\end{lemma}
\begin{proof}
    Work in $R = \mathrm{ZMod}(2^n - 1)$. The elements $1, 2, \ldots, 2^{n-1}$ are pairwise
    distinct roots of $X^n - 1$ in $R[X]$. Let $f = X^n - 1$ and $g = \prod_{k=0}^{n-1}(X - 2^k)$;
    both are monic of degree $n$ and vanish on the same $n$ points, so $f = g$.
    Differentiating and evaluating at $X = 1$: $f'(1) = n$, while for $g'(1)$ only the $j = 0$
    term survives (all other terms contain the factor $1 - 2^0 = 0$), giving
    $g'(1) = \prod_{k=1}^{n-1}(1 - 2^k)$. The resulting equality in $R$ lifts to the
    stated $\mathbb{Z}$-divisibility.
\end{proof}

\begin{lemma}[Sign correction in $\mathbb{Z}$]
    \label{lem:vantieghem_sign_correction_int}
    \lean{Vantieghem.sign_correction_int}
    For $n \geq 2$, $\prod_{k=1}^{n-1}(2^k - 1) = (-1)^{n-1} \prod_{k=1}^{n-1}(1 - 2^k)$
    in $\mathbb{Z}$.
\end{lemma}
\begin{proof}
    Each factor satisfies $2^k - 1 = (-1)(1 - 2^k)$. Multiplying over $k = 1, \ldots, n-1$
    introduces a sign of $(-1)^{n-1}$.
\end{proof}

\begin{lemma}[$(-1)^{n-1} = 1$ for odd prime $n$]
    \label{lem:vantieghem_neg_one_pow_even_sub_one}
    \lean{Vantieghem.neg_one_pow_even_sub_one}
    If $n$ is prime and $n \geq 3$, then $(-1 : \mathbb{Z})^{n-1} = 1$.
\end{lemma}
\begin{proof}
    Since $n \geq 3$ is an odd prime, $n - 1$ is even, so $(-1)^{n-1} = 1$.
\end{proof}

\begin{lemma}[Forward integer divisibility]
    \label{lem:vantieghem_forward_int_dvd}
    \lean{Vantieghem.forward_int_dvd}
    \uses{lem:vantieghem_sign_correction_int, lem:vantieghem_neg_one_pow_even_sub_one, lem:vantieghem_key_int_congruence}
    For $n \geq 3$ prime, $(2^n - 1) \mid \prod_{k=1}^{n-1}(2^k - 1) - n$ in $\mathbb{Z}$.
\end{lemma}
\begin{proof}
    Combine the sign correction with the key congruence. Since $(-1)^{n-1} = 1$ for odd prime $n$,
    the product $\prod(2^k - 1)$ equals $\prod(1 - 2^k)$, and the $\mathbb{Z}$-divisibility follows.
\end{proof}

\begin{lemma}[Forward direction]
    \label{lem:vantieghem_forward_direction}
    \lean{Vantieghem.forward_direction}
    \uses{lem:vantieghem_prod_ge_n, lem:vantieghem_forward_int_dvd}
    For $n \geq 3$ prime, $\prod_{k=1}^{n-1}(2^k - 1) \equiv n \pmod{2^n - 1}$.
\end{lemma}
\begin{proof}
    The forward integer divisibility gives $(2^n-1) \mid \prod(2^k-1) - n$ in $\mathbb{Z}$.
    Since $\prod_{k=1}^{n-1}(2^k-1) \geq n$ (the product lower bound), both sides are natural
    numbers and the divisibility lifts to the natural number congruence.
\end{proof}

\begin{lemma}[$(2^d - 1)$ divides the product]
    \label{lem:vantieghem_factor_dvd_prod}
    \lean{Vantieghem.factor_dvd_prod}
    If $1 \leq d < n$, then $(2^d - 1) \mid \prod_{k=1}^{n-1}(2^k - 1)$.
\end{lemma}
\begin{proof}
    Since $1 \le d < n$, the factor $2^d - 1$ appears in the product,
    so it divides the product.
\end{proof}

\begin{lemma}[Congruence forces $(2^d - 1) \mid n$]
    \label{lem:vantieghem_divisor_divides_n}
    \lean{Vantieghem.divisor_divides_n}
    \uses{lem:vantieghem_factor_dvd_prod}
    If $n \geq 3$, the congruence holds, $d \mid n$, and $2 \leq d \leq n - 1$,
    then $(2^d - 1) \mid n$.
\end{lemma}
\begin{proof}
    Since $d \mid n$: $(2^d-1) \mid (2^n-1)$. Since $1 \leq d \leq n-1$: $(2^d-1) \mid \prod$.
    The congruence gives $(2^n-1) \mid \prod - n$, hence $(2^d-1) \mid \prod - n$.
    Combined with $(2^d-1) \mid \prod$, we conclude $(2^d-1) \mid n$.
\end{proof}

\begin{lemma}[Small composite witness]
    \label{lem:vantieghem_not_dvd_of_small_composite}
    \lean{Vantieghem.not_dvd_of_small_composite}
    For composite $n$ with $3 \leq n \leq 31$, there exists $d$ with $d \mid n$,
    $2 \leq d \leq n-1$, and $(2^d - 1) \nmid n$.
\end{lemma}
\begin{proof}
    Verified by casework over all composite values of $n$ in $[3, 31]$.
\end{proof}

\begin{lemma}[Small composites fail the congruence]
    \label{lem:vantieghem_backward_small}
    \lean{Vantieghem.backward_small}
    \uses{lem:vantieghem_not_dvd_of_small_composite, lem:vantieghem_divisor_divides_n}
    For composite $n$ with $3 \leq n \leq 31$, the congruence
    $\prod_{k=1}^{n-1}(2^k - 1) \equiv n \pmod{2^n - 1}$ cannot hold.
\end{lemma}
\begin{proof}
    The witness lemma gives $d$ with $d \mid n$, $2 \leq d \leq n-1$, and $(2^d-1) \nmid n$.
    If the congruence held, the divisor lemma would force $(2^d-1) \mid n$, a contradiction.
\end{proof}

\begin{lemma}[$\mathrm{minFac}(n) \leq n / \mathrm{minFac}(n)$ for composite $n$]
    \label{lem:vantieghem_minFac_le_sqrt}
    \lean{Vantieghem.minFac_le_sqrt}
    For composite $n \geq 2$, $\mathrm{minFac}(n) \leq n / \mathrm{minFac}(n)$.
\end{lemma}
\begin{proof}
    For composite $n$, $\mathrm{minFac}(n)^2 \leq n$, so $\mathrm{minFac}(n) \leq n / \mathrm{minFac}(n)$.
\end{proof}

\begin{lemma}[$n / \mathrm{minFac}(n) \geq 6$ for large composite $n$]
    \label{lem:vantieghem_div_minFac_ge_six}
    \lean{Vantieghem.div_minFac_ge_six}
    \uses{lem:vantieghem_minFac_le_sqrt}
    For composite $n \geq 32$, $n / \mathrm{minFac}(n) \geq 6$.
\end{lemma}
\begin{proof}
    Let $d = n / \mathrm{minFac}(n)$. Since $\mathrm{minFac}(n) \leq d$ and $n \leq d^2$,
    combined with $n \geq 32$, we get $d^2 \geq 32$, which forces $d \geq 6$.
\end{proof}

\begin{lemma}[$n / \mathrm{minFac}(n)$ divides $n$]
    \label{lem:vantieghem_div_minFac_dvd}
    \lean{Vantieghem.div_minFac_dvd}
    For $n \geq 2$, $(n / \mathrm{minFac}(n)) \mid n$.
\end{lemma}
\begin{proof}
    Since $\mathrm{minFac}(n) \mid n$, the quotient $n / \mathrm{minFac}(n)$ also divides $n$.
\end{proof}

\begin{lemma}[$n / \mathrm{minFac}(n) \leq n - 1$]
    \label{lem:vantieghem_div_minFac_le_pred}
    \lean{Vantieghem.div_minFac_le_pred}
    For $n \geq 2$, $n / \mathrm{minFac}(n) \leq n - 1$.
\end{lemma}
\begin{proof}
    Since $\mathrm{minFac}(n) \geq 2$, we have $n / \mathrm{minFac}(n) \leq n / 2 \leq n - 1$.
\end{proof}

\begin{lemma}[$n \leq (n / \mathrm{minFac}(n))^2$ for composite $n$]
    \label{lem:vantieghem_n_le_sq_div_minFac}
    \lean{Vantieghem.n_le_sq_div_minFac}
    \uses{lem:vantieghem_minFac_le_sqrt}
    For composite $n \geq 2$, $n \leq (n / \mathrm{minFac}(n))^2$.
\end{lemma}
\begin{proof}
    Let $d = n / \mathrm{minFac}(n)$. Since $\mathrm{minFac}(n) \leq d$ and
    $\mathrm{minFac}(n) \cdot d = n$, we get $n = \mathrm{minFac}(n) \cdot d \leq d \cdot d = d^2$.
\end{proof}

\begin{lemma}[Large composite has a suitable divisor]
    \label{lem:vantieghem_backward_large_aux}
    \lean{Vantieghem.backward_large_aux}
    \uses{lem:vantieghem_div_minFac_ge_six, lem:vantieghem_div_minFac_dvd, lem:vantieghem_div_minFac_le_pred, lem:vantieghem_n_le_sq_div_minFac, lem:vantieghem_sq_lt_pow}
    For composite $n \geq 32$, there exists $d$ with $d \mid n$, $2 \leq d \leq n-1$,
    and $n < 2^d - 1$.
\end{lemma}
\begin{proof}
    Take $d = n / \mathrm{minFac}(n)$. Then $d \geq 6$, $d \mid n$, $d \leq n-1$, and
    $n \leq d^2 < 2^d$ by the square-less-than-power lemma for $d \geq 5$. A sharper bound
    $d^2 + 2 \leq 2^d$ (from applying the same lemma at $d-1$) yields $n < 2^d - 1$.
\end{proof}

\begin{lemma}[Large composites fail the congruence]
    \label{lem:vantieghem_backward_large}
    \lean{Vantieghem.backward_large}
    \uses{lem:vantieghem_backward_large_aux, lem:vantieghem_divisor_divides_n}
    For composite $n \geq 32$ with $n \geq 3$, the congruence
    $\prod_{k=1}^{n-1}(2^k-1) \equiv n \pmod{2^n-1}$ cannot hold.
\end{lemma}
\begin{proof}
    The auxiliary lemma gives $d$ with $d \mid n$, $2 \leq d \leq n-1$, and $n < 2^d - 1$.
    If the congruence held, the divisor lemma would give $(2^d-1) \mid n$. But
    $0 < n < 2^d - 1$ makes this impossible.
\end{proof}

\begin{lemma}[Backward direction]
    \label{lem:vantieghem_backward_direction}
    \lean{Vantieghem.backward_direction}
    \uses{lem:vantieghem_backward_small, lem:vantieghem_backward_large}
    For $n \geq 3$, if $\prod_{k=1}^{n-1}(2^k-1) \equiv n \pmod{2^n-1}$, then $n$ is prime.
\end{lemma}
\begin{proof}
    Suppose $n$ is composite. If $3 \leq n \leq 31$ the small case lemma gives a contradiction.
    If $n \geq 32$ the large case lemma gives a contradiction. Hence $n$ must be prime.
\end{proof}

\begin{theorem}[Vantieghem's Theorem]
    \label{thm:vantieghem}
    \lean{vantieghem}
    \uses{lem:vantieghem_forward_direction, lem:vantieghem_backward_direction}
    For $n \geq 3$, $n$ is prime if and only if
    $\prod_{k=1}^{n-1}(2^k - 1) \equiv n \pmod{2^n - 1}$.
\end{theorem}
\begin{proof}
    The forward implication is the forward direction lemma, and the backward implication
    is the backward direction lemma.
\end{proof}

\chapter{Von Staudt-Clausen Theorem}

This section contains a proof of the Von Staudt-Clausen Theorem.
See \url{https://en.wikipedia.org/wiki/Von_Staudt%E2%80%93Clausen_theorem} for more details.

\begin{lemma}[Explicit Formula for Bernoulli Numbers]
    \label{lem:Bernoulli_Number_Explicit_Formula}
    \lean{bernoulli_two_mul_eq_sum}
    An explicit formula for the (even indexed) Bernoulli numbers is given for positive even $n$ by:
    $B_{2n} = \sum_{j=0}^{2n} \frac{1}{j+1} \sum_{m=0}^{j} (-1)^m \binom{j}{m} m^{2n}$.
\end{lemma}

\begin{proof}
    This follows from applying the Mercator series to the forward difference operator.
    % TODO this proof could be made more detailed
\end{proof}

Note that more explanation of the above theorem can be found at \url{https://en.wikipedia.org/wiki/Bernoulli_polynomials#Another_explicit_formula}.

\begin{lemma}[Explicit Formula for Stirling Numbers of the Second Kind]
    \label{lem:Stirling_Number_Second_kind_Explicit_Formula}
    \lean{stirlingSecond_kind_explicit_formula}
    An explicit formula for the Stirling numbers of the second kind is given by:
    $S(n, k) = \frac{1}{k!} \sum_{j=0}^{k} (-1)^{k-j} \binom{k}{j} j^n$.
\end{lemma}

\begin{proof}
    This follows by using inclusion-exclusion to show that the number of surjections from n to k is
    given by $\sum_{j=0}^{k} (-1)^{k-j} \binom{k}{j} j^n$,
    and then dividing by $k!$ for indistinguishability of the subsets.
\end{proof}

Note that this means we can substitute the formula for Stirling numbers of the second kind into the explicit formula for Bernoulli numbers to get another formula for Bernoulli numbers in terms of Stirling numbers.

\begin{lemma}[Sum of Binomial Coefficients Modulo p]
    \label{lem:Sum_of_Binomial_Coefficients_Modulo_p}
    \lean{sum_neg_one_pow_mul_choose_mul_pow_two_mul}
    Let $p$ be a prime number. Then, for $n \geq 1$, we have the following congruences:
    \begin{enumerate}
        \item If $p-1$ divides $2n$, then $\sum_{m=0}^{p-1} (-1)^m \binom{p-1}{m} m^{2n} \equiv -1 \pmod{p}$.
        \item If $p-1$ does not divide $2n$, then $\sum_{m=0}^{p-1} (-1)^m \binom{p-1}{m} m^{2n} \equiv 0 \pmod{p}$.
    \end{enumerate}
\end{lemma}

\begin{proof}
    By Fermat's Little Theorem, $m^{p-1} \equiv 1 \pmod{p}$ for $m = 1, 2, \dots, p-1$.

    Case 1: If $p-1$ divides $2n$, then $m^{2n} \equiv 1 \pmod{p}$ for $m=1, \dots, p-1$.
    Therefore,
    $\sum_{m=1}^{p-1} (-1)^m \binom{p-1}{m} m^{2n} \equiv \sum_{m=1}^{p-1} (-1)^m \binom{p-1}{m} \pmod{p}$.
    From the binomial expansion of $(1-1)^{p-1} = \sum_{m=0}^{p-1} (-1)^m \binom{p-1}{m}$, we have
    $0 = 1 + \sum_{m=1}^{p-1} (-1)^m \binom{p-1}{m}$, so $\sum_{m=1}^{p-1} (-1)^m \binom{p-1}{m} = -1$.
    Thus, $\sum_{m=0}^{p-1} (-1)^m \binom{p-1}{m} m^{2n} \equiv -1 \pmod{p}$.

    Case 2: If $p-1$ does not divide $2n$, let $2n = q(p-1) + r$ where $0 < r < p-1$.
    Then $m^{2n} \equiv (m^{p-1})^q m^r \equiv m^r \pmod{p}$ for $m=1, \dots, p-1$.
    We need to evaluate $\sum_{m=0}^{p-1} (-1)^m \binom{p-1}{m} m^r \pmod{p}$.
    Using the identity $\binom{p-1}{m} \equiv (-1)^m \pmod{p}$, the sum becomes
    $\sum_{m=0}^{p-1} m^r \pmod{p}$.
    For $0 < r < p-1$, the sum of powers $\sum_{m=0}^{p-1} m^r$ is congruent to $0 \pmod{p}$.
    Therefore, $\sum_{m=0}^{p-1} (-1)^m \binom{p-1}{m} m^{2n} \equiv 0 \pmod{p}$.
\end{proof}

\begin{lemma}[Integer Property of Composite Denominators]
    \label{lem:Integer_Property_of_Composite_Denominators}
    \lean{composite_dvd_factorial}
    If $j+1$ is a composite number greater than 4, then $\frac{j!}{j+1}$ is an integer.
\end{lemma}

\begin{proof}
    If $j+1$ is composite and $j+1 > 4$, then either $j+1 = ab$ for integers $a, b$ with $1 < a < b \le j$, in which case $a$ and $b$ are distinct factors in $j!$, so $(j+1) | j!$. Or $j+1 = p^2$ for some prime $p$. If $p>2$, then $p$ and $2p$ are factors in $(p^2-1)!$, so $p^2 | (p^2-1)!$. If $p=2$, $j+1=4$, which is excluded. For all these cases, $\frac{j!}{j+1}$ is an integer.
\end{proof}


\begin{theorem}[Von Staudt-Clausen Theorem]
    \label{thm:Von_Staudt-Clausen}
    \lean{von_staudt_clausen}
    For any positive integer $n$, the Bernoulli number $B_{2n}$ can be expressed as
    $B_{2n} = I_n - \sum_{(p-1)|2n} \frac{1}{p}$
    where $I_n$ is an integer and the sum is over all prime numbers $p$ such that $p-1$ divides $2n$. This is equivalent to saying that $B_{2n} + \sum_{(p-1)|2n} \frac{1}{p}$ is an integer.
\end{theorem}

\begin{proof}
    \uses{lem:Bernoulli_Number_Explicit_Formula}
    \uses{lem:Sum_of_Binomial_Coefficients_Modulo_p}
    \uses{lem:Integer_Property_of_Composite_Denominators}
    \uses{lem:Stirling_Number_Second_kind_Explicit_Formula}

    We start with the explicit formula for Bernoulli numbers given in~\ref{lem:Bernoulli_Number_Explicit_Formula}:
    $B_{2n} = \sum_{j=0}^{2n} \frac{1}{j+1} \sum_{m=0}^{j} (-1)^m \binom{j}{m} m^{2n}$.

    We analyze the term $\frac{1}{j+1} \sum_{m=0}^{j} (-1)^m \binom{j}{m} m^{2n}$ for each $j$.
    Let $A_j = \sum_{m=0}^{j} (-1)^m \binom{j}{m} m^{2n}$.

    For the case $j=3$, so $j+1=4$, we examine the corresponding numerator:
    $\sum_{m=0}^{3} (-1)^m \binom{3}{m} m^{2n} = -1 + 3 \cdot 1^{2n} - 3 \cdot 2^{2n} + 1 \cdot 3^{2n} = 3(3^{2n-1} - 2^{2n} + 1)$.
    For $n \ge 1$, this is always divisible by 4. Specifically, for $n=1$, we get $3(3-4+1)=0$. For $n>1$, $3^{2n-1}$ is an odd power of 3, so it is 3 mod 4. $2^{2n}$ is divisible by 4. So the expression is $3(3-0+1) = 12 \equiv 0 \pmod{4}$.
    Thus, the term for $j=3$ contributes an integer.

    If $j+1$ is a prime number $p$, then $j=p-1$. From lemma \ref{lem:Sum_of_Binomial_Coefficients_Modulo_p}, we have two cases:
    \begin{itemize}
        \item If $p-1$ divides $2n$, then $A_{p-1} \equiv -1 \pmod{p}$. This implies $A_{p-1} = kp - 1$ for some integer $k$. The term for $j=p-1$ is $\frac{kp-1}{p} = k - \frac{1}{p}$.
        \item If $p-1$ does not divide $2n$, then $A_{p-1} \equiv 0 \pmod{p}$. This implies $A_{p-1} = kp$, so the term is $\frac{kp}{p} = k$, an integer.
    \end{itemize}

    If $j+1$ is a composite number $> 4$, from lemma \ref{lem:Integer_Property_of_Composite_Denominators}, the term $\frac{j!}{j+1}$ is an integer. Furthermore, from \ref{lem:Stirling_Number_Second_kind_Explicit_Formula} shows that the other component of this term is also an integer. Thus, the entire term for composite $j+1 > 4$ is an integer.

    Combining these results, we can write the formula for $B_{2n}$ as a sum of terms. The terms where $j+1$ is composite contribute an integer value. The terms where $j+1$ is a prime $p$ such that $p-1$ does not divide $2n$ also contribute an integer value. The only fractional parts come from the terms where $j+1$ is a prime $p$ such that $p-1$ divides $2n$. Each of these terms contributes $-\frac{1}{p}$ to the fractional part.

    Therefore, $B_{2n}$ can be written as an integer $I_n$ (the sum of all integer parts) minus the sum of the fractional parts $\frac{1}{p}$ for all primes $p$ where $p-1$ divides $2n$.

    $B_{2n} = I_n - \sum_{(p-1)|2n} \frac{1}{p}$.
\end{proof}

