\chapter{Wolstenholme's Theorem}

This section contains a proof of Wolstenholme's theorem: for every prime $p \ge 5$, the central binomial coefficient
$\binom{2p-1}{p-1} \equiv 1 \pmod{p^3}$.
See \url{https://en.wikipedia.org/wiki/Wolstenholme\%27s_theorem} for more details.

%---------------------------------------------------------------------------
\section{Factorial and binomial identities}
%---------------------------------------------------------------------------

\begin{lemma}[Choose times factorial equals product]
    \label{lem:wolst_choose_mul_factorial_eq_prod}
    \lean{Wolstenholme.choose_mul_factorial_eq_prod}
    \uses{}
    For any natural number $p \ge 1$,
    \[
        \binom{2p-1}{p-1} \cdot (p-1)! = \prod_{k=1}^{p-1}(p+k).
    \]
\end{lemma}
\begin{proof}
    The descending factorial $(2p-1)^{\underline{p-1}}$ equals $(p-1)! \cdot \binom{2p-1}{p-1}$ by
    the standard identity, and also equals $\prod_{k=1}^{p-1}(p+k)$ after a reflection of the
    index range.
\end{proof}

\begin{lemma}[Factorial coprime to prime cube]
    \label{lem:wolst_factorial_coprime_prime_cube}
    \lean{Wolstenholme.factorial_coprime_prime_cube}
    \uses{}
    If $p$ is prime, then $\gcd\bigl((p-1)!,\, p^3\bigr) = 1$.
\end{lemma}
\begin{proof}
    Every factor in $(p-1)!$ is strictly less than $p$, so $p$ is coprime to $(p-1)!$, and hence
    $p^3$ is coprime to $(p-1)!$.
\end{proof}

\begin{lemma}[Cancelling the factorial]
    \label{lem:wolst_cancel_factorial}
    \lean{Wolstenholme.cancel_factorial}
    \uses{lem:wolst_choose_mul_factorial_eq_prod, lem:wolst_factorial_coprime_prime_cube}
    If $p$ is prime and $p \ge 5$, then
    \[
        \binom{2p-1}{p-1} \equiv 1 \pmod{p^3}
        \;\Longleftrightarrow\;
        \prod_{k=1}^{p-1}(p+k) \equiv (p-1)! \pmod{p^3}.
    \]
\end{lemma}
\begin{proof}
    By Lemma~\ref{lem:wolst_choose_mul_factorial_eq_prod}, $\binom{2p-1}{p-1}\cdot(p-1)! =
    \prod_{k=1}^{p-1}(p+k)$.  Since $\gcd((p-1)!, p^3)=1$
    (Lemma~\ref{lem:wolst_factorial_coprime_prime_cube}), $(p-1)!$ can be cancelled from both
    sides of the congruence.
\end{proof}

%---------------------------------------------------------------------------
\section{Working in ZMod}
%---------------------------------------------------------------------------

\begin{lemma}[Sum of inverses is zero in ZMod p]
    \label{lem:wolst_sum_inv_eq_zero_zmod}
    \lean{Wolstenholme.sum_inv_eq_zero_zmod}
    \uses{}
    For an odd prime $p$,
    \[
        \sum_{k=1}^{p-1} k^{-1} = 0 \quad \text{in } \mathbb{Z}/p\mathbb{Z}.
    \]
\end{lemma}
\begin{proof}
    The map $k \mapsto p - k$ is an involution on $\{1,\ldots,p-1\}$ satisfying
    $(p-k)^{-1} = -k^{-1}$ in $\mathbb{Z}/p\mathbb{Z}$, so the sum equals its own negation.
    Since $p$ is odd, $2$ is invertible, forcing the sum to be zero.
\end{proof}

\begin{lemma}[Sum of squares is zero in ZMod p]
    \label{lem:wolst_sum_sq_eq_zero_zmod}
    \lean{Wolstenholme.sum_sq_eq_zero_zmod}
    \uses{}
    For a prime $p \ge 5$,
    \[
        \sum_{k=1}^{p-1} k^2 = 0 \quad \text{in } \mathbb{Z}/p\mathbb{Z}.
    \]
\end{lemma}
\begin{proof}
    Multiply both sides by $6$; by the closed form $6\sum_{k=1}^{n}k^2 = n(n+1)(2n+1)$,
    the sum at $n=p-1$ becomes $(p-1)\cdot p\cdot(2p-1)$, which contains the factor $p$,
    hence is zero mod $p$.  Since $p\ge 5$ the factor $6$ is invertible mod $p$.
\end{proof}

\begin{lemma}[Sum of inverse squares equals sum of squares in ZMod p]
    \label{lem:wolst_sum_inv_sq_eq_sum_sq}
    \lean{Wolstenholme.sum_inv_sq_eq_sum_sq}
    \uses{lem:wolst_sum_sq_eq_zero_zmod}
    For a prime $p \ge 5$,
    \[
        \sum_{k=1}^{p-1} k^{-2} = \sum_{k=1}^{p-1} k^2 \quad \text{in } \mathbb{Z}/p\mathbb{Z}.
    \]
\end{lemma}
\begin{proof}
    The map $k \mapsto k^{-1}$ is a bijection on $\{1,\ldots,p-1\}$ in $\mathbb{Z}/p\mathbb{Z}$,
    sending $k^{-2}$ to $(k^{-1})^{-2} = k^2$.  A formal reindexing of the sum via this
    bijection gives the equality.
\end{proof}

\begin{lemma}[Sum of inverse squares is zero in ZMod p]
    \label{lem:wolst_sum_inv_sq_eq_zero_zmod}
    \lean{Wolstenholme.sum_inv_sq_eq_zero_zmod}
    \uses{lem:wolst_sum_inv_sq_eq_sum_sq, lem:wolst_sum_sq_eq_zero_zmod}
    For a prime $p \ge 5$,
    \[
        \sum_{k=1}^{p-1} k^{-2} = 0 \quad \text{in } \mathbb{Z}/p\mathbb{Z}.
    \]
\end{lemma}
\begin{proof}
    By Lemma~\ref{lem:wolst_sum_inv_sq_eq_sum_sq} this equals $\sum k^2$, which vanishes by
    Lemma~\ref{lem:wolst_sum_sq_eq_zero_zmod}.
\end{proof}

%---------------------------------------------------------------------------
\section{Lifting to integer divisibility}
%---------------------------------------------------------------------------

\begin{lemma}[Sum of cross-products divisible by p]
    \label{lem:wolst_sum_inv_zero_mod_p}
    \lean{Wolstenholme.sum_inv_zero_mod_p}
    \uses{lem:wolst_sum_inv_eq_zero_zmod}
    For a prime $p \ge 5$,
    \[
        p \;\Big|\; \sum_{k=1}^{p-1} \prod_{j \ne k} j \quad \text{in } \mathbb{Z}.
    \]
\end{lemma}
\begin{proof}
    Cast to $\mathbb{Z}/p\mathbb{Z}$.  Each term $\prod_{j\ne k} j$ equals $(p-1)!\cdot k^{-1}$.
    Factoring out the common $(p-1)!$, the sum reduces to $(p-1)!\cdot\sum k^{-1}$, which is
    zero by Lemma~\ref{lem:wolst_sum_inv_eq_zero_zmod}.
\end{proof}

\begin{lemma}[Sum of cross-products divisible by p squared]
    \label{lem:wolst_sum_inv_zero_mod_p_sq}
    \lean{Wolstenholme.sum_inv_zero_mod_p_sq}
    \uses{lem:wolst_sum_inv_zero_mod_p, lem:wolst_sum_inv_sq_eq_zero_zmod}
    For a prime $p \ge 5$,
    \[
        p^2 \;\Big|\; \sum_{k=1}^{p-1} \prod_{j \ne k} j \quad \text{in } \mathbb{Z}.
    \]
\end{lemma}
\begin{proof}
    Let $S$ denote the sum.  Pairing each term with its reflection and using Wilson's theorem
    shows $2S = p \cdot T$ where $T = \sum_k \prod_{j \ne k, j \ne p-2-k} j$.  Since $p$
    divides $T$ (by reducing to $\sum k^{-2} = 0$ mod $p$ via
    Lemma~\ref{lem:wolst_sum_inv_sq_eq_zero_zmod}), we get $p^2 \mid 2S$.  Coprimality of $p$
    with $2$ then gives $p^2 \mid S$.
\end{proof}

\begin{lemma}[Square of sum identity]
    \label{lem:wolst_sq_sum_eq}
    \lean{Wolstenholme.sq_sum_eq}
    \uses{}
    In any commutative ring, for a sequence $a_0, \ldots, a_{n-1}$,
    \[
        \Bigl(\sum_{i=0}^{n-1} a_i\Bigr)^2
        = \sum_{i=0}^{n-1} a_i^2 + 2\!\!\sum_{0 \le i < j < n}\!\! a_i a_j.
    \]
\end{lemma}
\begin{proof}
    Expand the square $(\sum a_i)^2 = \sum_i\sum_j a_i a_j$, split the double sum according to
    whether $i=j$, $i<j$, or $i>j$, and use commutativity to combine the off-diagonal terms.
\end{proof}

\begin{lemma}[Sum of cross-inverse products is zero in ZMod p]
    \label{lem:wolst_sum_cross_inv_eq_zero_zmod}
    \lean{Wolstenholme.sum_cross_inv_eq_zero_zmod}
    \uses{lem:wolst_sum_inv_eq_zero_zmod, lem:wolst_sum_inv_sq_eq_zero_zmod, lem:wolst_sq_sum_eq}
    For a prime $p \ge 5$,
    \[
        \sum_{1 \le i < j \le p-1} i^{-1} j^{-1} = 0 \quad \text{in } \mathbb{Z}/p\mathbb{Z}.
    \]
\end{lemma}
\begin{proof}
    By Lemma~\ref{lem:wolst_sq_sum_eq} applied to $(a_k) = (k^{-1})$, the square of
    $\sum k^{-1}$ equals $\sum k^{-2} + 2\sum_{i<j} i^{-1}j^{-1}$.
    Both $\sum k^{-1}$ (Lemma~\ref{lem:wolst_sum_inv_eq_zero_zmod}) and $\sum k^{-2}$
    (Lemma~\ref{lem:wolst_sum_inv_sq_eq_zero_zmod}) vanish mod $p$, so
    $2\sum_{i<j} i^{-1}j^{-1} = 0$, and $2$ is invertible since $p$ is odd.
\end{proof}

%---------------------------------------------------------------------------
\section{Product expansion modulo p cubed}
%---------------------------------------------------------------------------

\begin{lemma}[Product expansion formula (exact)]
    \label{lem:wolst_prod_one_plus_p_mul_eq}
    \lean{Wolstenholme.prod_one_plus_p_mul_eq}
    \uses{}
    In $\mathbb{Z}/p^3\mathbb{Z}$, for any sequence $a_0,\ldots,a_{n-1}$,
    \[
        \prod_{k=0}^{n-1}(1 + p\,a_k) =
        1 + p\sum_k a_k + p^2\!\!\sum_{i<j}\!\! a_i a_j + p^3 \cdot 0.
    \]
\end{lemma}
\begin{proof}
    By induction on $n$, expanding the product step by step.  Every term involving $p^3$ or
    higher vanishes because $p^3 = 0$ in $\mathbb{Z}/p^3\mathbb{Z}$.
\end{proof}

\begin{lemma}[Product expansion formula]
    \label{lem:wolst_prod_one_plus_p_mul}
    \lean{Wolstenholme.prod_one_plus_p_mul}
    \uses{lem:wolst_prod_one_plus_p_mul_eq}
    For $p \ge 2$, in $\mathbb{Z}/p^3\mathbb{Z}$,
    \[
        \prod_{k=0}^{n-1}(1 + p\,a_k) =
        1 + p\sum_k a_k + p^2\!\!\sum_{i<j}\!\! a_i a_j.
    \]
\end{lemma}
\begin{proof}
    Immediate from Lemma~\ref{lem:wolst_prod_one_plus_p_mul_eq} after simplifying the $p^3\cdot 0$
    term.
\end{proof}

%---------------------------------------------------------------------------
\section{Connecting the product to the 1 + p S form}
%---------------------------------------------------------------------------

\begin{lemma}[Elements 1 to p-1 are units in ZMod p cubed]
    \label{lem:wolst_isUnit_cast_of_lt}
    \lean{Wolstenholme.isUnit_cast_of_lt}
    \uses{}
    If $p$ is prime and $1 \le k \le p-1$, then the image of $k$ in $\mathbb{Z}/p^3\mathbb{Z}$
    is a unit.
\end{lemma}
\begin{proof}
    Since $0 < k < p$ and $p$ is prime, $\gcd(k, p) = 1$, so $\gcd(k, p^3) = 1$, making $k$
    a unit in $\mathbb{Z}/p^3\mathbb{Z}$.
\end{proof}

\begin{lemma}[Factor identity in ZMod p cubed]
    \label{lem:wolst_pk_div_k_eq}
    \lean{Wolstenholme.pk_div_k_eq}
    \uses{lem:wolst_isUnit_cast_of_lt}
    For a prime $p$ and $1 \le k \le p-1$, in $\mathbb{Z}/p^3\mathbb{Z}$,
    \[
        (p + k) \cdot k^{-1} = 1 + p \cdot k^{-1}.
    \]
\end{lemma}
\begin{proof}
    Multiply out: $(p+k)\cdot k^{-1} = p\cdot k^{-1} + k\cdot k^{-1} = p\cdot k^{-1} + 1$.
    This is exact in $\mathbb{Z}/p^3\mathbb{Z}$ since $k$ is a unit.
\end{proof}

\begin{lemma}[Product factored into factorial times product of (1+p/k) terms]
    \label{lem:wolst_prod_pk_eq_factorial_mul_prod}
    \lean{Wolstenholme.prod_pk_eq_factorial_mul_prod}
    \uses{lem:wolst_isUnit_cast_of_lt, lem:wolst_pk_div_k_eq}
    For a prime $p \ge 5$, in $\mathbb{Z}/p^3\mathbb{Z}$,
    \[
        \prod_{k=1}^{p-1}(p+k) = (p-1)! \cdot \prod_{k=1}^{p-1}(1 + p\,k^{-1}).
    \]
\end{lemma}
\begin{proof}
    Factor each term as $(p+k) = k\cdot(1+p\cdot k^{-1})$ using the identity of
    Lemma~\ref{lem:wolst_pk_div_k_eq} (which relies on $k$ being a unit,
    Lemma~\ref{lem:wolst_isUnit_cast_of_lt}), then separate the products and collect the $k$
    factors into $(p-1)!$.
\end{proof}

%---------------------------------------------------------------------------
\section{Vanishing of the correction terms}
%---------------------------------------------------------------------------

\begin{lemma}[Linear correction term vanishes in ZMod p cubed]
    \label{lem:wolst_p_mul_sum_inv_eq_zero}
    \lean{Wolstenholme.p_mul_sum_inv_eq_zero}
    \uses{lem:wolst_factorial_coprime_prime_cube, lem:wolst_sum_inv_zero_mod_p, lem:wolst_sum_inv_zero_mod_p_sq}
    For a prime $p \ge 5$,
    \[
        p \cdot \sum_{k=1}^{p-1} k^{-1} = 0 \quad \text{in } \mathbb{Z}/p^3\mathbb{Z}.
    \]
\end{lemma}
\begin{proof}
    Since $p^2 \mid \sum_{k=1}^{p-1}\prod_{j\ne k} j$ (Lemma~\ref{lem:wolst_sum_inv_zero_mod_p_sq}),
    after multiplying through by $p$ we get $p^3 \mid p\cdot(\text{that sum})$, which is zero in
    $\mathbb{Z}/p^3\mathbb{Z}$.  The passage between the integer sum and $\sum k^{-1}$ in
    $\mathbb{Z}/p^3\mathbb{Z}$ uses that $(p-1)!$ is a unit
    (Lemma~\ref{lem:wolst_factorial_coprime_prime_cube}).
\end{proof}

\begin{lemma}[Quadratic correction term vanishes in ZMod p cubed]
    \label{lem:wolst_p_sq_mul_sum_cross_inv_eq_zero}
    \lean{Wolstenholme.p_sq_mul_sum_cross_inv_eq_zero}
    \uses{lem:wolst_sum_cross_inv_eq_zero_zmod}
    For a prime $p \ge 5$,
    \[
        p^2 \cdot \sum_{1 \le i < j \le p-1} i^{-1} j^{-1} = 0 \quad \text{in } \mathbb{Z}/p^3\mathbb{Z}.
    \]
\end{lemma}
\begin{proof}
    Apply the ring homomorphism $\mathbb{Z}/p^3\mathbb{Z} \to \mathbb{Z}/p\mathbb{Z}$ to the sum.
    Since each inverse is compatible with this map (they are units), the image is
    $\sum_{i<j} i^{-1}j^{-1}$ in $\mathbb{Z}/p\mathbb{Z}$, which is zero by
    Lemma~\ref{lem:wolst_sum_cross_inv_eq_zero_zmod}.  Hence $p$ divides the sum in
    $\mathbb{Z}/p^3\mathbb{Z}$, making $p^2$ times the sum divisible by $p^3$, i.e., zero.
\end{proof}

%---------------------------------------------------------------------------
\section{Assembly of the main result}
%---------------------------------------------------------------------------

\begin{lemma}[Product of (1+p/k) terms equals 1 in ZMod p cubed]
    \label{lem:wolst_prod_one_plus_inv_eq_one}
    \lean{Wolstenholme.prod_one_plus_inv_eq_one}
    \uses{lem:wolst_prod_one_plus_p_mul, lem:wolst_p_mul_sum_inv_eq_zero, lem:wolst_p_sq_mul_sum_cross_inv_eq_zero}
    For a prime $p \ge 5$,
    \[
        \prod_{k=1}^{p-1}\bigl(1 + p\,k^{-1}\bigr) = 1 \quad \text{in } \mathbb{Z}/p^3\mathbb{Z}.
    \]
\end{lemma}
\begin{proof}
    By Lemma~\ref{lem:wolst_prod_one_plus_p_mul}, the product equals
    $1 + p\sum k^{-1} + p^2\sum_{i<j} i^{-1}j^{-1}$.  The linear term vanishes by
    Lemma~\ref{lem:wolst_p_mul_sum_inv_eq_zero} and the quadratic term by
    Lemma~\ref{lem:wolst_p_sq_mul_sum_cross_inv_eq_zero}, leaving $1$.
\end{proof}

\begin{lemma}[Product p+k equals factorial in ZMod p cubed]
    \label{lem:wolst_prod_pk_eq_factorial_mod}
    \lean{Wolstenholme.prod_pk_eq_factorial_mod}
    \uses{lem:wolst_prod_pk_eq_factorial_mul_prod, lem:wolst_prod_one_plus_inv_eq_one}
    For a prime $p \ge 5$, in $\mathbb{Z}/p^3\mathbb{Z}$,
    \[
        \prod_{k=1}^{p-1}(p+k) = (p-1)!.
    \]
\end{lemma}
\begin{proof}
    By Lemma~\ref{lem:wolst_prod_pk_eq_factorial_mul_prod},
    $\prod(p+k) = (p-1)!\cdot\prod(1+p\,k^{-1})$.
    By Lemma~\ref{lem:wolst_prod_one_plus_inv_eq_one}, the second factor is $1$,
    giving $(p-1)!$.
\end{proof}

\begin{lemma}[Product congruence as Nat.ModEq]
    \label{lem:wolst_prod_pk_modEq_factorial}
    \lean{Wolstenholme.prod_pk_modEq_factorial}
    \uses{lem:wolst_prod_pk_eq_factorial_mod}
    For a prime $p \ge 5$,
    \[
        \prod_{k=1}^{p-1}(p+k) \equiv (p-1)! \pmod{p^3}.
    \]
\end{lemma}
\begin{proof}
    Lift the $\mathbb{Z}/p^3\mathbb{Z}$ equality of Lemma~\ref{lem:wolst_prod_pk_eq_factorial_mod}
    to a statement about the modular equality operator.
\end{proof}

\begin{theorem}[Wolstenholme's theorem]
    \label{thm:wolstenholme}
    \lean{wolstenholme}
    \uses{lem:wolst_cancel_factorial, lem:wolst_prod_pk_modEq_factorial}
    For every prime $p \ge 5$,
    \[
        \binom{2p-1}{p-1} \equiv 1 \pmod{p^3}.
    \]
\end{theorem}
\begin{proof}
    By Lemma~\ref{lem:wolst_cancel_factorial}, it suffices to show
    $\prod_{k=1}^{p-1}(p+k) \equiv (p-1)! \pmod{p^3}$,
    which is exactly Lemma~\ref{lem:wolst_prod_pk_modEq_factorial}.
\end{proof}

\chapter{Worpitzky's Identity}

This section contains a proof of Worpitzky's Identity.
See \url{https://en.wikipedia.org/wiki/Eulerian_number} for more details.

\begin{definition}[Eulerian number]
    \label{def:eulerian_number}
    \lean{EulerianNumber}
    Let $n \in \mathbb{N}$. For a permutation $\sigma \in S_n$, an \textit{ascent} is an index $i \in \{0, \dots, n-2\}$ such that $\sigma(i) < \sigma(i+1)$. We denote the set of ascents of $\sigma$ as $\mathrm{Asc}(\sigma)$ and the number of ascents as $k = |\mathrm{Asc}(\sigma)|$.
    The Eulerian number $A(n, k)$ is the number of permutations in $S_n$ with exactly $k$ ascents.
    We define $A(n, 0) = 1$ for all $n \ge 0$. For $n \ge 1$, we have $A(n, k) = 0$ if $k \ge n$.
\end{definition}

\begin{lemma}[Sum of Ascents and Descents]
    \label{lem:ascents_descents_sum}
    \lean{count_bump_perm_back}
    \uses{def:eulerian_number}
    For any integer $n \ge 1$ and any permutation $\sigma \in S_n$, let $\mathrm{Des}(\sigma) = \{i \in \{0, \dots, n-2\} : \sigma(i) > \sigma(i+1)\}$ be the set of descents. Let $k = |\mathrm{Asc}(\sigma)|$ and $d = |\mathrm{Des}(\sigma)|$. Then:
    \[ k + d = n - 1 \]
\end{lemma}

\begin{proof}
    The set of indices considered for ascents and descents is $\{0, 1, \dots, n-2\}$, which has cardinality $n-1$. Since $\sigma$ is a permutation, all elements are distinct, so for any $i$, $\sigma(i) \neq \sigma(i+1)$. Therefore, the relation must be either $\sigma(i) < \sigma(i+1)$ (an ascent) or $\sigma(i) > \sigma(i+1)$ (a descent). The sets $\mathrm{Asc}(\sigma)$ and $\mathrm{Des}(\sigma)$ partition the set of indices, so their sizes sum to $n-1$.
\end{proof}

\begin{lemma}[Insertion Bijection]
    \label{lem:insertion_bijection}
    \lean{perm_down_bij}
    For $n \in \mathbb{N}$, let $\mathcal{I}: S_n \times \{0, \dots, n\} \to S_{n+1}$ be the map where $\mathcal{I}(\sigma, j)$ is the permutation obtained by inserting the element $n+1$ into the sequence $\sigma(0), \dots, \sigma(n-1)$ at position $j$ (specifically, before the element at index $j$ if $j < n$, or appended to the end if $j=n$).
    Then $\mathcal{I}$ is a bijection.
\end{lemma}

\begin{proof}
    Let $\tau \in S_{n+1}$. Since $n+1$ is the maximal element in the codomain, its position in $\tau$ is unique. Let $j$ be the index such that $\tau(j) = n+1$. Removing the element $n+1$ from $\tau$ results in a sequence of length $n$ containing the elements $\{1, \dots, n\}$, which corresponds to a unique permutation $\sigma \in S_n$. Thus, the inverse map is well-defined, mapping $\tau$ to $(\sigma, j)$. Since an inverse exists, $\mathcal{I}$ is a bijection.
\end{proof}

\begin{lemma}[Insertion Effect on Ascents]
    \label{lem:insertion_effect}
    \lean{decomposeEnd}
    \uses{def:eulerian_number, lem:ascents_descents_sum, lem:insertion_bijection}
    Let $\sigma \in S_n$ be a permutation with $k$ ascents. Let $\sigma' = \mathcal{I}(\sigma, j)$ for some $j \in \{0, \dots, n\}$.
    Then:
    \begin{enumerate}
        \item The number of ascents in $\sigma'$ is $k+1$ if $j=n$ or if $j-1 \in \mathrm{Des}(\sigma)$ (i.e., $n+1$ is inserted at the end or immediately after a descent). There are exactly $n-k$ such positions.
        \item The number of ascents in $\sigma'$ is $k$ if $j=0$ or if $j-1 \in \mathrm{Asc}(\sigma)$ (i.e., $n+1$ is inserted at the beginning or immediately after an ascent). There are exactly $k+1$ such positions.
    \end{enumerate}
\end{lemma}

\begin{proof}
    \uses{lem:ascents_descents_sum}
    We analyze the local change in ascents caused by inserting $n+1$ at index $j$.
    Note that $n+1$ is greater than all elements in $\sigma$.
    \begin{itemize}
        \item If $j=0$: The sequence starts $n+1, \sigma(0)$. This is a descent. Existing ascents shift indices but their count is preserved. Total ascents: $k$.
        \item If $j=n$: The sequence ends $\sigma(n-1), n+1$. Since $\sigma(n-1) < n+1$, this adds a new ascent. Total ascents: $k+1$.
        \item If $0 < j < n$: We insert between $a = \sigma(j-1)$ and $b = \sigma(j)$. The pair $(a, b)$ is replaced by $(a, n+1)$ and $(n+1, b)$. Since $a < n+1$, $(a, n+1)$ is always an ascent. Since $n+1 > b$, $(n+1, b)$ is always a descent.
            \begin{itemize}
                \item If $(a, b)$ was an ascent ($a < b$), we removed one ascent and added one ascent ($a < n+1$). The total count remains $k$.
                \item If $(a, b)$ was a descent ($a > b$), we removed zero ascents and added one ascent ($a < n+1$). The total count becomes $k+1$.
            \end{itemize}
    \end{itemize}
    Counting the positions:
    \begin{itemize}
        \item Count preserving ascents ($k \to k$): Position $j=0$ plus positions $j$ where $j-1$ was an ascent. Total $= 1 + k$.
        \item Count increasing ascents ($k \to k+1$): Position $j=n$ plus positions $j$ where $j-1$ was a descent. Using Lemma \ref{lem:ascents_descents_sum}, the number of descents is $(n-1) - k$. Total $= 1 + (n - 1 - k) = n - k$.
    \end{itemize}
\end{proof}

\begin{lemma}[Recurrence for Eulerian numbers]
    \label{lem:eulerian_recurrence}
    \lean{eulerianNumber_rec}
    \uses{def:eulerian_number, lem:insertion_bijection, lem:insertion_effect}
    For any $n \in \mathbb{N}$ and integer $k$, the Eulerian numbers satisfy the recurrence relation:
    \[ A(n+1, k+1) = (n-k)A(n, k) + (k+2)A(n, k+1) \]
\end{lemma}

\begin{proof}
    \uses{lem:insertion_bijection, lem:insertion_effect}
    By Lemma \ref{lem:insertion_bijection}, we can partition $S_{n+1}$ based on the pre-image $(\sigma, j)$. A permutation in $S_{n+1}$ has $k+1$ ascents if and only if it was formed by:
    1. Taking $\sigma \in S_n$ with $k$ ascents and inserting $n+1$ in a position that increases the ascent count. By Lemma \ref{lem:insertion_effect}, there are $n-k$ such positions. Since there are $A(n, k)$ such $\sigma$, this contributes $(n-k)A(n, k)$.
    2. Taking $\sigma \in S_n$ with $k+1$ ascents and inserting $n+1$ in a position that preserves the ascent count. By Lemma \ref{lem:insertion_effect} (replacing $k$ with $k+1$), there are $(k+1)+1 = k+2$ such positions. Since there are $A(n, k+1)$ such $\sigma$, this contributes $(k+2)A(n, k+1)$.

    These cases are exhaustive and disjoint. Thus, $A(n+1, k+1)$ is the sum of these contributions.
\end{proof}

\begin{lemma}[Binomial Coefficient Identity]
    \label{lem:binomial_identity}
    \lean{choose_succ_right_eq'}
    For any integers $n, k \ge 0$ and any variable $x$, the following algebraic identity holds:
    \[ (n-k)\binom{x+k+1}{n+1} + (k+1)\binom{x+k}{n+1} = x\binom{x+k}{n} \]
\end{lemma}

\begin{proof}
    We expand the binomial coefficients:
    \[ \text{LHS} = (n-k) \frac{x+k+1}{n+1} \binom{x+k}{n} + (k+1) \frac{x+k-n}{n+1} \binom{x+k}{n} \]
    Factor out $\frac{1}{n+1} \binom{x+k}{n}$:
    \[ = \frac{1}{n+1} \binom{x+k}{n} \left[ (n-k)(x+k+1) + (k+1)(x+k-n) \right] \]
    Simplify the bracketed term:
    \[ (nx + nk + n - kx - k^2 - k) + (kx + k^2 - kn + x + k - n) \]
    Grouping by $x$ and constants:
    \[ x(n-k+k+1) + (nk+n-k^2-k + k^2-kn+k-n) = x(n+1) + 0 \]
    Substituting back:
    \[ = \frac{1}{n+1} \binom{x+k}{n} \cdot (n+1)x = x \binom{x+k}{n} \]
\end{proof}

\begin{theorem}[Worpitzky identity]
    \label{thm:worpitzky_identity}
    \lean{worpitzky}
    \uses{def:eulerian_number, lem:eulerian_recurrence, lem:binomial_identity}
    For all $n \in \mathbb{N}$ and any variable $x$, the following identity holds:
    \[ x^n = \sum_{k=0}^{n} A(n, k) \binom{x+k}{n} \]
\end{theorem}

\begin{proof}
    \uses{lem:eulerian_recurrence, lem:binomial_identity}
    We proceed by induction on $n$.
    Base case $n=0$: $x^0 = 1$. The sum is $A(0,0)\binom{x}{0} = 1 \cdot 1 = 1$. It holds.

    Inductive step: Assume the identity holds for $n$. Consider the expression for $n+1$:
    \[ \sum_{k=0}^{n+1} A(n+1, k) \binom{x+k}{n+1} \]
    Split the term for $k=0$ (where $A(n+1, 0)=1$) and use the recurrence from Lemma \ref{lem:eulerian_recurrence} for $k \ge 1$:
    \[ A(n+1, k) = (n-(k-1))A(n, k-1) + (k+1)A(n, k) \]
    Substituting into the sum (noting $A(n, n+1)=0$ allow extending the sum):
    \[ \binom{x}{n+1} + \sum_{k=1}^{n+1} \left[ (n-k+1)A(n, k-1) + (k+1)A(n, k) \right] \binom{x+k}{n+1} \]
    Shift the index in the first part by letting $j = k-1$:
    \[ \sum_{j=0}^{n} (n-j)A(n, j) \binom{x+j+1}{n+1} + \sum_{k=0}^{n} (k+1)A(n, k) \binom{x+k}{n+1} \]
    Note that the $k=0$ term in the second sum corresponds to the initial separated $\binom{x}{n+1}$ if we consider $A(n,0)=1$ and algebraic simplification. Combining the sums over $0 \le k \le n$:
    \[ \sum_{k=0}^{n} A(n, k) \left[ (n-k)\binom{x+k+1}{n+1} + (k+1)\binom{x+k}{n+1} \right] \]
    Using Lemma \ref{lem:binomial_identity}, the term in brackets is $x \binom{x+k}{n}$:
    \[ \sum_{k=0}^{n} A(n, k) \cdot x \binom{x+k}{n} = x \sum_{k=0}^{n} A(n, k) \binom{x+k}{n} \]
    By the induction hypothesis, $\sum_{k=0}^{n} A(n, k) \binom{x+k}{n} = x^n$.
    Thus, the expression equals $x \cdot x^n = x^{n+1}$.
\end{proof}

